-- RavRadar 4.0.56 — samlet Supabase-adgangskontrol
begin;

-- Udvid tilladte rettigheder uden at antage constraint-navnet.
do $$
declare c record;
begin
  for c in select oid, conname from pg_constraint where conrelid='public.user_permissions'::regclass and contype='c' loop
    if pg_get_constraintdef(c.oid) ilike '%permission_key%' then execute format('alter table public.user_permissions drop constraint %I',c.conname); end if;
  end loop;
end $$;
alter table public.user_permissions add constraint user_permissions_permission_key_check check(permission_key in ('admin_access','handbook_view','handbook_review','rules_view','rules_edit','rules_publish','zones_view','zones_weather_edit','diagnostics_view','diagnostics_download','observations_view','learning_manage','experts_manage','system_manage','full_admin'));

create or replace function public.has_ravradar_permission(p_key text) returns boolean language sql stable security definer set search_path=public as $$
 select exists(select 1 from public.profiles where id=auth.uid() and role='owner' and is_active)
 or exists(select 1 from public.user_permissions up join public.profiles p on p.id=up.user_id where up.user_id=auth.uid() and p.is_active and up.permission_key='full_admin' and up.enabled)
 or exists(select 1 from public.user_permissions up join public.profiles p on p.id=up.user_id where up.user_id=auth.uid() and p.is_active and up.permission_key=p_key and up.enabled);
$$;

create or replace function public.ravradar_document_permission(p_document_key text) returns text language sql immutable as $$
 select case
  when p_document_key in ('handbook','rdks-documentation-center') then 'handbook_view'
  when p_document_key in ('rules','rule-history') then 'rules_view'
  when p_document_key in ('water-level-station-routing','direction-reviews','zone-overrides','dmi-station-registry','coastline-overrides') then 'zones_view'
  when p_document_key like 'diagnostic-%' or p_document_key in ('diagnostics-settings','runtime-diagnostics','weather-health','dmi-water-stations','water-station-routing-audit','ocean-diagnostics','cache-audit','implementation-audit') then 'diagnostics_view'
  else 'full_admin' end;
$$;


create or replace function public.ravradar_document_write_permission(p_document_key text) returns text language sql immutable as $$
 select case
  when p_document_key in ('handbook','rdks-documentation-center') then 'full_admin'
  when p_document_key in ('rules','rule-history') then 'rules_edit'
  when p_document_key in ('water-level-station-routing','direction-reviews','zone-overrides','dmi-station-registry','coastline-overrides') then 'zones_weather_edit'
  when p_document_key like 'diagnostic-%' or p_document_key in ('diagnostics-settings','runtime-diagnostics','weather-health','dmi-water-stations','water-station-routing-audit','ocean-diagnostics','cache-audit','implementation-audit') then 'system_manage'
  else 'full_admin' end;
$$;

create or replace function public.can_manage_ravradar_document(p_document_key text) returns boolean language sql stable security definer set search_path=public as $$
 select public.is_ravradar_owner() or public.has_ravradar_permission('full_admin') or public.has_ravradar_permission(public.ravradar_document_write_permission(p_document_key));
$$;

create or replace function public.save_ravradar_permissions(p_user_id uuid,p_permissions jsonb) returns void language plpgsql security definer set search_path=public set row_security=off as $$
declare
 k text;
 target_role text;
 can_manage_all boolean:=public.is_ravradar_owner() or public.has_ravradar_permission('full_admin');
 expert_keys text[]:=array['admin_access','handbook_view','handbook_review'];
 all_keys text[]:=array['admin_access','handbook_view','handbook_review','rules_view','rules_edit','rules_publish','zones_view','zones_weather_edit','diagnostics_view','diagnostics_download','observations_view','learning_manage','experts_manage','system_manage','full_admin'];
 managed_keys text[];
 enabled_count integer:=0;
begin
 if not (can_manage_all or public.has_ravradar_permission('experts_manage')) then raise exception 'PERMISSION_DENIED' using errcode='42501'; end if;
 if p_permissions is null or jsonb_typeof(p_permissions)<>'object' then raise exception 'PERMISSION_OBJECT_REQUIRED' using errcode='22023'; end if;
 select role into target_role from public.profiles where id=p_user_id;
 if target_role is null then raise exception 'PROFILE_NOT_FOUND' using errcode='P0002'; end if;
 if target_role='owner' and not public.is_ravradar_owner() then raise exception 'OWNER_PROTECTED' using errcode='42501'; end if;
 if not can_manage_all then
  if target_role<>'expert' then raise exception 'EXPERT_TARGET_REQUIRED' using errcode='42501'; end if;
  if exists(select 1 from jsonb_each_text(coalesce(p_permissions,'{}'::jsonb)) item where not (item.key=any(expert_keys)) and lower(item.value)='true') then
   raise exception 'EXPERT_PERMISSION_SCOPE_EXCEEDED' using errcode='42501';
  end if;
  managed_keys:=expert_keys;
 else
  managed_keys:=all_keys;
 end if;
 if exists(select 1 from jsonb_each(p_permissions) item where not(item.key=any(all_keys))) then raise exception 'UNKNOWN_PERMISSION_KEY' using errcode='22023'; end if;
 if exists(select 1 from jsonb_each(p_permissions) item where jsonb_typeof(item.value)<>'boolean') then raise exception 'INVALID_PERMISSION_VALUE' using errcode='22023'; end if;
 foreach k in array managed_keys loop
  insert into public.user_permissions(user_id,permission_key,enabled,updated_at) values(p_user_id,k,coalesce((p_permissions->>k)::boolean,false),now())
  on conflict(user_id,permission_key) do update set enabled=excluded.enabled,updated_at=now();
  if coalesce((p_permissions->>k)::boolean,false) then enabled_count:=enabled_count+1; end if;
 end loop;
 insert into public.admin_audit_log(event_type,subject_key,actor_id,details)
 values('permissions_saved',p_user_id::text,auth.uid(),jsonb_build_object('scope',case when can_manage_all then 'administrator' else 'expert' end,'managed_keys',to_jsonb(managed_keys),'enabled_count',enabled_count));
end $$;

-- Eksperter må kun se ekspertkonti og ekspertrettigheder. Beskyttelsen
-- håndhæves i Supabase og kan derfor ikke omgås ved et direkte browserkald.
alter table public.profiles enable row level security;
alter table public.user_permissions enable row level security;
drop policy if exists profiles_owner_read on public.profiles;
drop policy if exists permissions_owner_read on public.user_permissions;
drop policy if exists ravradar_profiles_read on public.profiles;
drop policy if exists ravradar_user_permissions_read on public.user_permissions;
create policy ravradar_profiles_read on public.profiles for select to authenticated using(
 public.is_ravradar_owner() or public.has_ravradar_permission('full_admin') or id=auth.uid()
 or (public.has_ravradar_permission('experts_manage') and role='expert')
);
create policy ravradar_user_permissions_read on public.user_permissions for select to authenticated using(
 public.is_ravradar_owner() or public.has_ravradar_permission('full_admin') or user_id=auth.uid()
 or (public.has_ravradar_permission('experts_manage')
  and permission_key in ('admin_access','handbook_view','handbook_review')
  and exists(select 1 from public.profiles target_profile where target_profile.id=user_permissions.user_id and target_profile.role='expert'))
);
revoke all on public.profiles,public.user_permissions from anon;
grant select on public.profiles,public.user_permissions to authenticated;


drop policy if exists "authenticated admins manage documents" on public.admin_documents;
drop policy if exists "authenticated admins read document versions" on public.admin_document_versions;
drop policy if exists ravradar_admin_documents_read on public.admin_documents;
create policy ravradar_admin_documents_read on public.admin_documents for select to authenticated
using(public.is_ravradar_owner() or public.has_ravradar_permission('full_admin') or public.has_ravradar_permission(public.ravradar_document_permission(document_key)));
drop policy if exists ravradar_admin_document_versions_read on public.admin_document_versions;
create policy ravradar_admin_document_versions_read on public.admin_document_versions for select to authenticated
using(public.is_ravradar_owner() or public.has_ravradar_permission('full_admin') or public.has_ravradar_permission(public.ravradar_document_permission(document_key)));
revoke insert,update,delete on public.admin_documents,public.admin_document_versions from anon,authenticated;
grant select on public.admin_documents,public.admin_document_versions to authenticated;

-- Bevar eksisterende eksperters hidtidige håndbogsadgang efter migrationen.
insert into public.user_permissions(user_id,permission_key,enabled)
select distinct user_id,'admin_access',true from public.user_permissions where permission_key='handbook_review' and enabled
on conflict(user_id,permission_key) do update set enabled=true;
insert into public.user_permissions(user_id,permission_key,enabled)
select distinct user_id,'handbook_view',true from public.user_permissions where permission_key='handbook_review' and enabled
on conflict(user_id,permission_key) do update set enabled=true;

-- Håndbogen lagres som et beskyttet admin-dokument.
insert into public.admin_documents(document_key,payload,updated_by) values('handbook','{"schemaVersion":"2.0","handbookVersion":"4.0.320","title":"RavRadar Håndbog","updatedAt":"2026-09-02","sections":[{"id":"dmi-deterministic-grid-reuse-4-0-320","chapter":"88.11","title":"DMI-gridet genbruges sikkert i stedet for at blive beregnet igen","summary":"RavRadar behandler det samme DKSS-grid én gang pr. GRIB-message, bevarer alle sampling- og provenancekrav og kan derfor bygge 118 timer uden den tidligere lokale beregningsflaskehals.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> DMI leverede DKSS-filerne. Forsinkelsen lå i RavRadar, som både genopbyggede samme nearest-søgestruktur for hvert kystpunkt og udførte tung fuld-cachebehandling efter næsten hvert asset. 4.0.320 genbruger nu én sikker, message-lokal ecCodes-struktur og gemmer kun let progression undervejs.</div><div class=\"handbook-stack\"><p><strong>Samme data og samme valg:</strong> Det centralt godkendte vandpunkt, spatial-first-reglen, fælles U/V-celle, dybeste gyldige fælles lag, 5 km-grænsen, missing og provenance er uændrede. Optimeringen ændrer ikke en strømværdi eller score.</p><p><strong>Ingen tabt historik:</strong> Den interne processed cache bindes til gridgeneration 9, gridsektionens identitet og ecCodes API-/bindingsversion. Den offentlige griddefinition og dermed målt historik, state og recovery beholder den eksisterende identitet.</p><p><strong>Rigtig feltkadence:</strong> Required current-U, current-V og vandstand behandles for hver krævet time. Valgfrie DKSS-felter følger den etablerede tretimersrytme. DMI er fortsat førstevalg; Copernicus er kun exact-gap-supplement efter grøn DMI-terminalkontrol.</p><p><strong>Atomisk assetgrænse:</strong> Hvert asset bygges isoleret og committes først efter komplet validering. Afbrydelse, exception eller validatorfejl ruller assettet tilbage, så en halv fil ikke kan få færdigmarkør eller falsk collection-success.</p><p><strong>Progression uden falsk readiness:</strong> Bulkcache og sidecars gemmes kompakt og atomisk senest efter otte committede assets eller 60 sekunder og ved sikre forced-grænser. Fuld oprydning og diagnostik køres én gang ved terminal finalisering. En delvis cache er aldrig DMI_READY eller terminal dækning. Tolv dynamiske tests, 21 WAM-bootstraptests og uafhængig review er grønne; Candidate G er fortsat offentlig, mens frisk 673 × 118-currentpreflight, særskilt Feggesund 3 × 118-wavebevis, exact-head, merge, produktion og offentlig kontrol afventer.</p></div>"},{"id":"dmi-cache-health-phase-consistency-4-0-319","chapter":"88.10","title":"DMI-cache kontrolleres ens før og efter oprydning","summary":"En beskadiget strømcache kan ikke længere springe DKSS over; DMI er primær, og Copernicus må kun udfylde præcise dokumenterede DMI-huller.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Run <code>33520738058</code> viste en lokal fasefejl, ikke at DMI generelt manglede strømdata. Den tidlige cachekontrol kunne være grøn, før den afsluttende oprydning fjernede det samme strømpar.</div><div class=\"handbook-stack\"><p><strong>Samme regel i begge faser:</strong> Kystdelens registrerede samplingpunkt skal svare til det aktive vandpunkt. U/V-gridresuméet må enten mangle samlet og blive genopbygget fra verificeret timeproveniens eller bestå same-grid-kontrollen. Et halvt eller afvigende par tæller ikke som sund cache.</p><p><strong>DMI først:</strong> En cache, som ikke kan overleve oprydningen, aktiverer den eksisterende DKSS-recovery før andre kilder. Reglen gælder både Candidate G-vedligeholdelse og den nye integrerede model.</p><p><strong>Copernicus er kun supplement:</strong> Først efter en grøn DMI-terminalgate må Copernicus udfylde de eksakte dokumenterede kystdels-/timehuller, som DMI reelt mangler. Copernicus må ikke skjule eller erstatte en systemisk DMI-fejl.</p><p><strong>Status:</strong> Rettelsen og de afgrænsede lokale tests er grønne. Frisk eksakt 673 × 118-preflight, exact-head, merge, produktion og offentlig kontrol afventer.</p></div>"},{"id":"weather-legacy-wam-rebuild-and-queue-4-0-318","chapter":"90","title":"4.0.318: målt WAM-genopbygning og sikker produktionskø","summary":"PR #244 er merged, men Candidate G er fortsat offentlig; legacy-bølger genhentes målt, first-cutover er action-isoleret, og watchdoggen kan ikke længere erstatte en ventende push.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> PR #244 bestod exact-head <code>33452730102</code> og blev merged som <code>27906d7d</code>. Push-run <code>33471225980</code> blev annulleret før jobs af den tidligere enkelt-pending-kø. Efterfølgeren <code>33471276238</code> stoppede sikkert i legacy-WAM-kæden uden central vejrcache, beskyttede writes, artifact eller Pages. Candidate G er derfor fortsat sidste offentlige model; den integrerede state-6-model er ikke live.</div><div class=\"handbook-stack\"><p><strong>Målt rebuild:</strong> En gammel privat <code>PART::</code>-bølgerække uden den krævede same-cell-proveniens bruges ikke og får ikke opfundet en celleidentitet. Kun bølgefelter og bølgeproveniens fjernes, et partial checkpoint gemmes, og bølgerne genhentes fra den normale målte DMI STAC/GRIB-vej. Strøm, vind, vandstand, temperatur og punktidentitet bevares. Manglende live-WAM stopper fortsat fail-closed.</p><p><strong>Action-isolation:</strong> Kun operationen <code>integrated-cutover</code> må aktivere den integrerede wave-resolver, lang DMI-runtime, first-cutover-refresh, privat bootstrapmode og source-attestering. Schedule, watchdog og manuel Candidate G-vedligehold kan ikke starte dette spor.</p><p><strong>Kø og watchdog:</strong> Produktionsworkflowet bruger <code>queue: max</code> med <code>cancel-in-progress: false</code>. Watchdoggen henter en ufiltreret runliste, filtrerer <code>main</code> lokalt og fejler lukket ved ugyldig historik. Før et eventuelt dispatch gentages hele kontrollen mod en ny runliste og det offentlige manifest; begge beslutninger skal stadig være positive.</p><p><strong>Bevisgrænse:</strong> DMI/WAM 20/20, wave-validator 26/26, integreret generator, watchdog og workflowkontrakter er lokalt grønne. Ny exact-head, frisk fuld produktion/Pages og offentlig desktop-/mobilkontrol udestår.</p></div>"},{"id":"weather-strict-part-cache-and-calendar-4-0-318","chapter":"90","title":"4.0.318: stabil vejropdatering ved dansk midnat","summary":"Kildegaten bruger den danske forecastkalender, og DMI-cachegenbrug kræver et faktisk verificeret strømpar for aktive kystdele.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Vejrworkflowet var aktivt, men flere runs stoppede før en ny offentlig vejrpakkes bygning. En test beregnede \"i morgen\" i UTC omkring dansk midnat, og DMI-cachegenbrug kunne godkendes uden et samlet verificeret kystdelsstrømpar. Begge fejl er lokalt rettet og måltestet; frisk produktions- og Pages-bevis udestår.</div><div class=\"handbook-stack\"><p><strong>Kalender:</strong> Relative prognosedage i tests bruger nu RavRadars fælles <code>Europe/Copenhagen</code>-kalender og et fast klokkeslæt.</p><p><strong>DMI-cache:</strong> Genbrug kræver eksakt aktivt <code>PART::</code>-register og mindst ét finite U/V-par på samme time og række med fuld native provenance i den låste <code>target−48..target+117</code>-matrix. Den faktisk valgte fallback materialiseres atomisk til næste trin.</p><p><strong>Fail-closed:</strong> Nul strict par stopper både normal og WAM-produktion, mens reelt progressivt cachearbejde fortsat checkpointes. Ingen scoreformel, geometri, land-/vandpunkt eller private data ændres.</p></div>"},{"id":"ravscore-operational-recovery-and-historical-maintenance-4-0-318","chapter":"90","title":"4.0.318: historisk modelvedligehold og sikker Pages-recovery","summary":"Candidate G/4.0.316 er stadig offentlig; 4.0.318 tilføjer planforseglede H0→H1-broer, exact-target recovery og fuld femdøgnsvisning ved ufuldstændig historik.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Candidate G/4.0.316 er fortsat den offentlige model. PR #242 bestod exact-head <code>33408976253</code> og blev merged som <code>29f39cce</code>. Frisk produktion <code>33412497717</code> passerede legacy-attesteringen, men stoppede før artifact, Pages og deploy, fordi DMI-producenten fejlede, hvorefter den inaktive private punktkandidat forhindrede de efterfølgende cache-save-trin. Rettelsen lader kun punktkandidaten køre efter DMI-succes, gør den ikke-blokerende og gemmer reel progressiv DMI-/WAM-cache også ved producentfejl. Den hårde WAM-gate er bevaret og udsender kun en afgrænset fejlkode. Ingen geometri, punkter, live-data eller private vejrdata er ændret; ny exact-head, merge og frisk produktion afventer.</div><div class=\"handbook-stack\"><p><strong>Planforseglet H0→H1:</strong> Historical Candidate og historical integrated maintenance bevarer den eksakte gamle source og skriver først PENDING. Complete kræver den eksakte nye Pages-side og skifter controller/profil atomisk. Direct historical Candidate→integrated bruger en immutable IntegratedReturnPlan. Ordinary maintenance kræver fortsat samme aktuelle 11-feltsbinding. Controller-v4 ændres ikke: præcis 30 felter, fire statusser og seks overgangstyper.</p><p><strong>Ingen generel source-abort:</strong> Den gamle kilde må kun gendannes, når terminal evidens beviser, at Pages aldrig accepterede anmodningen. Ved tvetydig start genudgiver en isoleret writer de allerede forseglede målbytes. En separat finalizer uden Pages-rettighed kræver stabil målobservation, exact main, PENDING og CAS. Requested-, source- og tredje manifest-/closurehash valideres fail-closed; tredje eller blandet hash, ændret/manglende plan og gammel CAS stopper. Recoverydeploymentet bliver næste forseglede source-lineage.</p><p><strong>Fuld prognose ved historikmangel:</strong> Hvis den konkrete times direkte input er gyldige, viser state 6 alle 118 timer fra current til +117 timer/fem kalenderdage som <code>HISTORY_INCOMPLETE</code> med konservativ score, interval, dækning og DA/DE/EN-advarsel. Advarslen forsvinder ved <code>FULL_HISTORY</code>. Mangler et direkte input, er kun den berørte time <code>UNAVAILABLE</code>; der gættes, interpoleres eller lånes ikke. Spørg RavRadar skal skelne de to situationer. Den offentlige tekst forklarer enkelt, at nyere bølgeenergi vejer mest, vægten halveres over fire timer, og sidste-mile-leddet højst dæmper det eksisterende leveringssignal 15 %. Brugeren skal ikke kende modellens interne forkortelser. P2-måltestene er lokalt grønne; exact-head-, produktions- og browserbevis udestår.</p><p><strong>Bindingsbevis:</strong> Integrated er <code>778db7aa3946f925607a8304daa42ed17dd30294e4a51bf6d895d7293e84c4e7</code>/<code>e880d5425e6f7b93d8afc99cddf491e58ad5a4a2ab055f8e4455193609c90a73</code> over 43 filer og otte forbrugere. Candidate G-rollback er særskilt <code>c73dac1b4376005e792580791d84eb79c9370e905a2a7fd0bdee857506a20cf8</code>/<code>4ccc2081982677aadbb47a5ee7d6f2b99fdcb7e42113e73029d5c60323a5ee96</code> over 55 filer. Begge bindinger kommer fra <code>version.json.releaseContract.modelBindings</code>.</p><p><strong>Drift:</strong> Ordinær aktiv Candidate G-drift bruger <code>CANDIDATE_G_REFRESH</code>, og scheduleren kan kun udføre Candidate G-refresh; den kan ikke aktivere, rollbacke eller returnere en model. Det aktive 15-minutters kontroljob diagnosticerer run, gates, deploy og live side før sikker reparation og må ikke blindt redispatche eller oprette en ekstra scheduler/vagthund. Runs <code>33343469247</code>/<code>33344823000</code> stoppede sikkert på forbigående 503 uden deploy. Efter PR #238/#239/#240 stoppede også <code>33391418061</code>/<code>33393684620</code> sikkert før DMI og før beskyttede writes; de er bevis for sikker afbrydelse, ikke for offentlig state 6. PR #237 bestod exact-head <code>33352520408</code> og blev merged som <code>8c03e25d</code>. Backendrun <code>33352661061</code> og fuld produktion <code>33352634365</code> var grønne; automatisk run <code>33354263148</code> publicerede <code>rr-20260831034128-210</code> komplet 210/673 uden syntetiske samples.</p><p><strong>Releasebevis:</strong> Produktions-outcome er payloadfri <code>ravradar-production-workflow-outcome-v2</code> med historical actions samt recovery writer/finalizer/gate. Orchestrator/build/deploy-opdelingen, 40 reader-migrationer, role-aware workflowkontrakter, public-integrated 210/673 + 78 browsermoduler, profil/cutover og 8-consumer-binding er lokalt grønne uden P0/P1-reviewfund. Fuld slut-sourcegate, exact-head, merge, frisk 4.0.318-produktion, Feggesund 3 × 118 og offentlig desktop-/mobilbrowser udestår.</p></div>"},{"id":"integrated-cutover-data-and-calibration-closure-4-0-318","chapter":"88.9","title":"RavScore 4.0.320: nyeste status for currentseal, data-preflight og kalibreringslås","summary":"DMI-currentrodårsagen er lokalt afgrænset og rettet, og de integrerede slutbundles er forseglede og lokalt måltestede; frisk 118-timers preflight, exact-head, produktion og offentlig release mangler fortsat.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Candidate G/4.0.316 er fortsat offentlig. Den lokale 4.0.320-releasekandidat og DMI-rodrettelsen er implementeret, og den seneste rettelses målrettede scheduler-/bulk-/workflowtests samt Python-syntakskontrol er grønne. Et grønt 118-timers preflightbevis, exact-head, merge, frisk produktion og offentlig desktop-/mobilverifikation mangler endnu.</div><div class=\"handbook-stack\"><p><strong>Schema 3-currentseal:</strong> <code>OPERATIONAL_COMPLETE</code> kræver for hver af 673 kystdele og begge modes præcis target til +117 med direkte strøm og operationel kausal lineage. Den målte, direkte historik fra target−48 til target−1 er rådgivende under warmup og kan mangle uden at fjerne score; tilstanden er da <code>HISTORY_INCOMPLETE</code> med tydelig advarsel og <code>calibrationEligible=false</code>.</p><p><strong>Isoleret 118-timers data-preflight:</strong> Et særskilt branch-<code>workflow_dispatch</code> med <code>operational_118_preflight</code> kontrollerer kun DMI, de tre save-trin, den payloadfri terminalgate, operationel selector/checker, weather-update og den integrerede audit. Det kører ikke source/full/release/admin/Pages/deploy/browser og må kun gemme én syvdages, privacy-safe rapport.</p><p><strong>Korrigeret rodårsag:</strong> Runs <code>33510636195</code> og <code>33512163102</code> behandlede HARMONIE/WAM, men nul trin i <code>dkss_idw</code>, <code>dkss_nsbs</code> og <code>dkss_lf</code>. <code>DMI_STRICT_CURRENT_ANCHOR_MISSING</code> var derfor ikke bevis for bred DMI-mangel. Cachelinjen førte tilbage til det negative run <code>33498108421</code>; lokalt kunne en preferred run blive afvist som stale uden fremskift, donoren var en kopi af samme progressive cache, og gamle DKSS-stepmarkører kunne undertrykke genbehandling uden strict anchor.</p><p><strong>Jobtarget og runvalg:</strong> Ét eksakt target bindes før DMI og genbruges gennem hele det jobafgrænsede snapshot; et efterfølgende UTC-timeskifte afviser ikke beviset. En ældre preferred run beholdes kun foran en nyere moden run ved kendt observeret cadence og højst én cadences lag. Ved ukendt cadence vælges den nyere modne run.</p><p><strong>Betinget currentrecovery:</strong> Uden strict anchor står de tre DKSS-familier først i den normale collection-loop, og deres gamle stepmarkører genbruges ikke. Det er ikke en ubetinget global DKSS-first-regel.</p><p><strong>Valgfri deployed donor:</strong> Preflighten forsøger at hydrere en uafhængig offentlig Candidate G-DMI-donor under <code>RUNNER_TEMP</code>. Kun en donor, der består den strenge kompatibilitetskontrol, må bruges. Mangler den eller fejler kontrollen, fortsætter frisk officiel DMI uden deployed fallback.</p><p><strong>Første cutover:</strong> Den særskilt checkpointede WAM-historikbootstrap ligger fortsat før den normale collection-loop og kan fortsætte over flere cutoverforsøg. Den efterfølgende loop får seks collectionpladser. Uden strict anchor står DKSS foran WAM i denne loop; med anchor kan WAM stå først. Normal drift bevarer to collections.</p><p><strong>Uændret kildeorden:</strong> DMI er fortsat førstevalg. Copernicus må først efter grøn DMI-terminalgate supplere de eksakte resterende part-/timehuller; fungerende DMI erstattes ikke landsdækkende.</p><p><strong>DMI-cache og terminalgrænse:</strong> En strict-verificeret kompatibel donor må kun kopiere en hel vejrtime til en manglende eller strukturelt tom række. Felter, U/V-par eller bølgekomponenter blandes aldrig mellem runs. Producenten må fejle kontrolleret indtil alle tre saves er udført; derefter skal <code>DMI_READY</code> og strict-anchor-kontrollen være grønne, før selector fortsætter.</p><p><strong>Kalibreringslås:</strong> <code>calibrationEligible=false</code> bæres gennem controller, tur-/observationsbindinger, admin, central hydration og reconciliation under measured-only warmup. Kun en forseglet full-history-audit med komplet 210/673-, privacy- og modelbinding og uden proxyafledt score må sætte <code>true</code>; Feggesund-proxy er altid ikke-kalibreringsegnet.</p><p><strong>Bindingsbevis:</strong> Den integrerede model er forseglet med <code>modelContractSha256=a226e7d10f5c9fa94e122c0e4e3dc1367f1d5e44e763593e4568ac8a3ed1b14b</code> og <code>modelBundleSha256=db475a1bbb1b85fe3e0277b8687d6f1edd6dd8d74e0d6fb4df748f955d5bafe1</code> over 44 kanonisk normaliserede transitive implementeringsfiler og otte deklarerede forbrugere. Candidate G-rollback er forseglet med <code>modelContractSha256=c73dac1b4376005e792580791d84eb79c9370e905a2a7fd0bdee857506a20cf8</code> og <code>modelBundleSha256=ea22921e298a03ed1ef8787a4dbd79fd4fdf1a9b8e188d3c4b44e03f16fdceb0</code> over 56 transitive filer. Den autoritative binding står i <code>version.json.releaseContract.modelBindings</code>. Exact-head <code>33577887262</code> stoppede sikkert i Candidate G-rollbackens public stage på calibration-ceiling. Den symmetriske fem-validator-rettelse samt rollback public-stage 210/673, Candidate-assistent, integrerede public consumers og Edge er lokalt grønne; ny exact-head, sidste 118-bevis, merge, frisk produktion og offentlig browserkontrol afventer.</p><p><strong>Åben evidens:</strong> De tre negative runs er ikke 118-timers bevis. De målrettede slutdifftests og Python-syntakskontrollen er grønne. Frisk 673 × 118-preflight, exact-head, merge, fuld produktion/releasegate/artifact/Pages, aktivering, Feggesunds policybundne 3 × 118 og offentlig desktop-/mobilkontrol står fortsat åbne.</p></div>"},{"id":"integrated-ravscore-first-cutover-4-0-318","chapter":"89","title":"RavScore 4.0.320: integrated-first med målt historikopbygning","summary":"State 6 må gå online med komplet direkte og operationel 118-timersakse, mens ældre historik og privat Candidate G-rollback modnes målt bagefter; release og produktion er stadig afventende.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Candidate G/4.0.316 er fortsat den eneste offentlige model. Den lokale 4.0.320-releasekandidat gør integrated-first muligt, men er ikke release- eller produktionsverificeret. Exact-head, merge, frisk fuld produktion/releasegate/artifact/Pages og offentlig desktop-/mobilkontrol afventer.</div><div class=\"handbook-stack\"><p><strong>Hård 118-timersgate:</strong> Alle 673 kystdele og begge jagtformer skal have 118 sammenhængende timer fra current til +117 med gyldige obligatoriske input og den kausale operationelle WAM-run-/lagbro. Direkte lokale data vinder; kun den navngivne Feggesund-wave-only-proxy må erstatte en helt manglende lokal bølgetuple. Anden direct eller operational missing giver <code>UNAVAILABLE</code> og stopper release. Kun manglende ældre præ-target-historik må blive <code>HISTORY_INCOMPLETE</code>.</p><p><strong>Fuld prognose med ærlig advarsel:</strong> <code>HISTORY_INCOMPLETE</code> viser fortsat current og fem døgn med konservativ lower score, upper bound, dækning og DA/DE/EN-advarsel. Advarslen forsvinder ved <code>FULL_HISTORY</code>, og <code>calibrationEligible=false</code> består, mens historikken er ufuldstændig.</p><p><strong>Privat measured warmup:</strong> Den fulde runtime har præcis én privat Candidate G-rod: enten 673/673 <code>READY</code> rollbackruntime eller <code>BUILDING_MEASURED_ONLY</code>/<code>MEASURED_ONLY</code> med komplet 673-delsdækning og <code>activationReady=false</code>. Warmup er continuation-only, aldrig offentlig model, shadow, controllerstatus, automatisk fallback eller rollbackbevis. Manuel Candidate G-rollback bliver først mulig ved reelt 673/673 READY.</p><p><strong>Checkpoint uden ghost proof:</strong> Det uændrede checkpointschema 4 med <code>candidate-g-rollback-ready-companion</code> bygges, gemmes og publiceres kun ved READY. Under measured warmup skal alle tre trin være eksplicit og hashbundet <code>NOT_APPLICABLE_DURING_MEASURED_WARMUP</code>. Tilfældigt skip eller et falsk checkpointbevis stopper.</p><p><strong>State-less samme-model recovery:</strong> Hvis privat integreret runtime/checkpoint faktisk er fraværende eller legitimt udløbet, må state 6 genstarte fra faktisk målte data og fortsætte som <code>HISTORY_INCOMPLETE</code>. En tilstedeværende ugyldig eller manipuleret integreret state er fatal; Candidate G-only state er ikke samme-model recovery.</p><p><strong>Ingen kunstig historik:</strong> Warmup og cold replay må ikke bruge syntese, interpolation, carry, neutral nulstrøm eller nabolån. Den 40-timers sammenhængende WAM-bro og dens snævre same-run-regel gælder kun Candidate G-migration. Feggesunds operationelle undtagelse er wave-only: direkte lokal DMI vinder, og kun hel lokal tuple-missing må bruge samtidige komplette B05-10+B05-12-tuples. Proxytimer varsles på DA/DE/EN og er ikke kalibreringsegnede, også ved FULL_HISTORY. De skaber aldrig historik, current eller recovery-backfill. Geometri, land-/vandpunkter og kystnormal ændres ikke.</p><p><strong>Controller og bevisgrænse:</strong> Der tilføjes ingen controllerstatus, transition eller offentlig shadowmodel. Integrated-first er kun en lokal kandidat, indtil målrettede tests, exact-head, merge, frisk fuld produktion og offentlig 210/673-browserkontrol faktisk er grønne.</p></div>"},{"id":"integrated-ravscore-state6-history-bounds-2026-08-30","chapter":"89.0","title":"Historisk 4.0.317-design: score ved manglende historik","summary":"Dette er et historisk pre-merge-øjebliksbillede af 4.0.317 state-6-designet; de daværende statuslinjer er erstattet. Versionen blev senere merged, men ikke deployet, og aktuel status står i 4.0.319-afsnittet ovenfor.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Candidate G er fortsat den eneste offentlige model i den produktionsverificerede appbaseline 4.0.316. Den nye samlede model er lokalt implementeret som 4.0.317-testkandidat med <code>RRS-COASTAL-PROCESS-INTEGRATED-1.1.0</code>/state <code>6.0.0</code> og er ikke en offentlig shadowmodel.</div><div class=\"handbook-stack\"><p><strong>Tre ærlige kvaliteter:</strong> <code>FULL_HISTORY</code> er enten en <code>EXACT_POINT_SCORE</code> fra kendt fortsættelse eller en <code>CONSERVATIVE_TAIL_RESET_POINT_SCORE</code> efter modelkontraktens faste konservative lukning; den sidste er kalibreringsegnet modelpolitik, ikke en påstand om fysisk eksakt state. <code>HISTORY_INCOMPLETE</code> betyder, at den aktuelle times direkte input er gyldige, men ældre historik mangler; RavRadar viser da den konservative nedre score og fører den øvre grænse, spændet, årsagerne og dækningen med. <code>UNAVAILABLE</code> betyder, at et direkte obligatorisk strøm-, bølge- eller søgeinput mangler eller er ugyldigt; scoren er da <code>null</code>. Der interpoleres, bæres frem eller lånes ikke fra andre zoner.</p><p><strong>Vinduer og grænser:</strong> Current scorer fortsat kun 48 timer med 0,03/0,15 m/s, +10/-8 og 24/48-kernen. Ukendte historiske currentintervaller omsluttes med stærkest tilladt ud- og indstrømningsbane uden at opfinde en måling. State-løs recovery bruger <code>bounded-private-48h-history-cold-replay-v3</code> med <code>expectedCausalPositionCount=48</code>, faktisk komplet/ukendt antal og <code>historyTransition</code>. Replayet er fortsat <code>HISTORY_INCOMPLETE</code> efter 0, 5, 47 og også 48 komplette timer: 48/48 mærkes <code>VERIFIED_CAUSAL_HISTORY_WINDOW</code>, kortere/gappede forløb <code>UNKNOWN_HISTORY_INTERVAL</code>, men den ukendte bølgemobiliseringshale er endnu ikke lukket. Først efter 288 timers kausal fortsættelse kan bølgesporet nulstilles til det hidtidige lower-bound-spor; last-mile-sporet lukkes efter 40 timer til minimum-factor-sporet. <code>conservativeResetAt</code> gør lukningen eksplicit, mens de separate fysiske pointstates bevares til fortsættelse og rollback. Senere historikhuller åbner bounds igen fra det konservative scoringsspor. 168 timers datasikker researchretention er kun til replay og audit og har ingen scoreeffekt.</p><p><strong>Bruger og læring:</strong> Den samme DA/DE/EN-advarsel følger score, detaljer, fem døgn, admin og ekspert og forsvinder automatisk ved <code>FULL_HISTORY</code>. <code>HISTORY_INCOMPLETE</code> og <code>UNAVAILABLE</code> er altid <code>calibrationEligible=false</code> gennem browser, lokal/Edge-assistent, ture/observationer og lager. Numerisk score rangerer først; <code>FULL_HISTORY</code> vinder kun ved eksakt scoretie, før de eksisterende retnings-, vandstands- og tidsregler.</p><p><strong>Fælles modelbinding:</strong> Kandidaten bruger profil <code>cn-003-015-in10-out8-full24-cos48-gap3-wave4-48-historybounds12d-lastmileewma4-tail40-atten15-v5</code>, komponentskema <code>ravscore-components-huntability-delivery-mobilisation-bounds-v5</code>, forklaringsskema <code>ravscore-explanation-integrated-bounds-v5</code>, ranking <code>direction-broad-19-history-tie-v2</code>, bedste tidspunkt <code>score-history-water-tie-earliest-v3</code> og præsentation <code>score-bands-35-55-75-exceptional90-v1</code>. <code>modelContractSha256=778db7aa3946f925607a8304daa42ed17dd30294e4a51bf6d895d7293e84c4e7</code> binder parameterkontrakten, og <code>modelBundleSha256=e880d5425e6f7b93d8afc99cddf491e58ad5a4a2ab055f8e4455193609c90a73</code> binder præcis 43 kanonisk normaliserede, transitive implementeringsfiler. Den maskinlæsbare autoritet for værdierne er <code>version.json.releaseContract.modelBindings.integrated</code>. Releasekontrakten vælger ikke aktiv model; den integrerede schema-4-runtime læser bindingen fra <code>data/live/manifest.json</code> ved <code>/ravScoreModelBinding</code>.</p><p><strong>State og sikker overgang:</strong> Candidate G migreres direkte til schema 6 gennem <code>candidate-g-schema2-signed-current-reweight-bounded40h-wave-approach-to-integrated-schema6-v5</code>. Schema 5 var en aldrig-offentlig releasekandidat og må kun være eksakt <code>READY</code>-migrationskilde gennem <code>integrated-schema5-ready-point-to-schema6-history-bounds-v1</code>; aktiv privat runtime, cache og checkpoint er schema 6. Manuel hel rollback bruger <code>integrated-schema6-to-candidate-g-schema2-v3</code>.</p><p><strong>Privat runtime og checkpoint:</strong> Den fulde private runtime er en eksakt otte-fils bundle; browseren får kun manifest, startpakke, detaljer og kystdele. Checkpoint-only recovery bruger atomisk checkpointschema 4/status <code>ravscore-schema6-with-candidate-g-rollback-companion</code>/cache <code>ravscore-continuation-schema6-v2</code> med 673 schema-6-states og en parret, beskyttet <code>READY</code> Candidate G-companion schema 1/status <code>candidate-g-rollback-ready-companion</code>. Generation, target, binding, hashes og 673/673 skal matche, og companionen må aldrig rekonstrueres fra <code>HISTORY_INCOMPLETE</code>. Serializer-/protected-storage-tests er grønne; samlet public-runtime-/workflow-regression udestår.</p><p><strong>Hel rollback:</strong> Kun under manuel rollback må en eksakt <code>READY</code>/<code>memoryReady</code> Candidate G-runtime projicere sin egen mode-score som <code>FULL_HISTORY</code> + <code>EXACT_POINT_SCORE</code> med collapsed bounds, span 0, coverage 48, tomme reasons og reset false. Non-READY/mismatch stopper, og <code>calibrationEligible=false</code> består separat. Den maskinlæsbare Candidate G-binding står i <code>version.json.releaseContract.modelBindings.candidateGRollback</code>. På denne version er kontraktdigesten <code>c73dac1b4376005e792580791d84eb79c9370e905a2a7fd0bdee857506a20cf8</code> og bundledigesten <code>4ccc2081982677aadbb47a5ee7d6f2b99fdcb7e42113e73029d5c60323a5ee96</code> over 55 transitive filer.</p><p><strong>Producent-/forbrugerkontrakt:</strong> Kvalitet og bounds skal føres gennem 210 zoner/673 kystdele, startup/detaljer/hashes, ranglister, bedste tidspunkt, zonedetaljer, fem døgn, strand/waders, lokal og Edge-baseret Spørg RavRadar, evidens/faste svar, konto/tur/observation, admin/ekspert, central profil, scheduler, recovery/rollback, audits og releasegates. Trip-/observationslagring af lower/upper/span/coverage/reasons er implementeret gennem klient, immutable snapshot, DTO, Edge og SQL med grønne målrettede tests. Den checkpointparrede READY companion er ligeledes implementeret og målrettet testet; samlet exact-head-/workflow-/produktionsbevis udestår.</p><p><strong>Status og offentlig evidens:</strong> 4.0.316/<code>49dd4cb</code> er den produktionsverificerede offentlige appbaseline. Det friske Candidate G-datasæt <code>rr-20260830091913-210</code> var komplet som acquisition/public runtime med 210 zoner/673 kystdele, men havde 0 aktive zoner og 210 <code>UNAVAILABLE</code> på grund af utilstrækkelig sammenhængende strømhistorik. Det beviser den gamle scoreregression, ikke at state 6 er udgivet eller empirisk mere fundpræcis. Den lokale 4.0.317-testkandidat kræver stadig exact-head, merge, frisk fuld produktion/deploy og offentlig mobil-/desktopkontrol.</p></div>"},{"id":"feggesund-direct-first-two-neighbor-wave-proxy-2026-09-02","chapter":"89.1","title":"Feggesund: direkte først, to naboer kun ved helt bølgehul","summary":"Direkte lokal DMI vinder altid; kun en helt manglende Feggesund-bølgetuple må erstattes af et synligt, energikonsistent estimat fra B05-10 og B05-12.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> For <code>DK-B05-11</code>/Feggesund bruges den komplette lokale DMI-WAM-tuple altid, når den findes. Kun når hele tupletten med bølgehøjde, periode og middelretning mangler, må samtidige komplette direkte DMI-tuples fra både <code>DK-B05-10</code> og <code>DK-B05-12</code> danne en wave-only proxy. Delvis lokal tuple, én manglende nabo eller forskellig time/run giver <code>MISSING</code>.</div><div class=\"handbook-stack\"><p><strong>Matematik:</strong> Bølgehøjden er kvadratroden af middelværdien af <code>Hs²</code>. Periode og cirkulær FROM-retning vægtes med <code>Hs²</code>. Uenighed klassificeres <code>LOW</code>, <code>MODERATE</code> eller <code>HIGH</code> ud fra retning, energi og periode; den værste klasse vises.</p><p><strong>Synlig og ikke kalibreringsegnet:</strong> En proxytimes score viser på DA/DE/EN, at bølgedata er estimeret fra to samtidige naboområder, fordi lokal DMI-WAM mangler. Varslet forsvinder ved direkte lokal input. Alle berørte mode-/zone-/public-scorer, ture og observationer har <code>calibrationEligible=false</code>, også ved ellers <code>FULL_HISTORY</code>.</p><p><strong>Hård afgrænsning:</strong> Proxyen gælder kun bølger. Den må ikke levere strøm, currenthistorik, recovery-backfill eller kunstig state og må ikke flytte geometri, land-/vandpunkter eller kystnormal. Den er et ingeniørestimat, ikke lokal surfzonemodel eller bevis for bedre fundpræcision.</p><p><strong>Releasebevis:</strong> Tre dele × 118 timer skal give præcis 354 privacy-sikre udfald som direct, proxy eller missing. Direct + proxy skal være 354 og missing 0; koordinater, rå U/V og private payloads må ikke indgå.</p><p><strong>Kilder:</strong> <a href=\"https://www.dmi.dk/friedata/dokumentation/data/forecast-data-wave-model-wam\">DMI WAM</a>, <a href=\"https://confluence.ecmwf.int/download/attachments/59774192/wave_parameters.pdf?version=1\">ECMWF''s bølgeparametre</a> og <a href=\"https://help.marine.copernicus.eu/en/articles/6175153-how-to-describe-wave-height-period-and-direction-parameters\">Copernicus Marine</a> støtter energimatematikken og FROM-konventionen, men ikke lokal rav- eller surfzonepræcision.</p></div>"},{"id":"ddm-2024-static-context-not-surf-score-2026-08-30","chapter":"89.2","title":"Danmarks Dybdemodel har lavtvandsdata, men er ikke en surfzonemodel","summary":"DDM 2024/v2 er nyttig statisk dybdekontekst; fravalget som RavScore-input skyldes opløsning og dynamik, ikke fravær af lavtvandsdata.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> <a href=\"https://gst.dk/ansvarsomraader/soekort-og-marine-data/soeopmaaling-og-dybdedata/danmarks-dybdemodel\">Danmarks Dybdemodel 2024/v2</a> er et officielt 50 × 50 m middel-dybdegrid med dybde-, kilde- og opmålingsårslag. Den prioriterer moderne søopmåling og indeholder også lavtvandsdata fra satellit og lidar.</div><div class=\"handbook-stack\"><p>RavRadar fravælger altså ikke DDM, fordi den mangler lavtvandsdata. Grænsen er, at celler med utilstrækkeligt grundlag interpoleres, kystlinjen er generaliseret 1:100.000, og produktet er et statisk grid. Det opløser ikke dynamiske sandrevler, aktuelle ripkanaler eller bølgeopløst surfzone.</p><p>DDM kan bruges som forsknings- og forklaringskontekst, men ikke som zonetime-score eller anledning til at flytte geometri, land-/vandpunkter eller kystnormaler. Den fysiske sidste levering forbliver derfor markeret uopløst.</p></div>"},{"id":"optional-public-fallback-for-fresh-primary-4-0-316","chapter":"88","title":"Frisk vejrvisning kræver ikke en gyldig ældre reserve","summary":"4.0.316 lader en frisk measured-only primary publicere current og fem døgn uden at vise en gammel eller udløbet fallback.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En frisk ny vejrpakkes udgivelse må ikke afhænge af, at RavRadar også har en stadig gyldig ældre reserve. Findes ingen sikker reserve, vises den ikke; den friske primary kan fortsætte gennem sine egne strenge kontroller.</div><div class=\"handbook-stack\"><p><strong>Hvad der skete:</strong> PR #233 bestod exact-head <code>33299676128</code> og blev merged som <code>63d789a4</code>. Run <code>33299747300</code> kom forbi den gamle D1-lås og startede build, men stoppede ved fallbackstaging, fordi ingen measured-only reserve både var under 72 timer og inden for prognosehorisonten. Det run publicerede derfor intet artifact eller Pages-deploy; den efterfølgende rettelse og fulde verifikation gjorde senere 4.0.316/<code>49dd4cb</code> til offentlig appbaseline.</p><p><strong>Optional reserve:</strong> En komplet, auditeret measured-only fallback kan stadig bruges. En gammel, udløbet, ufuldstændig, ukendt, blandet, rekonstrueret eller manipuleret fallback må aldrig vises; den er fraværende i manifestet og fjernes fra offentlige fallbackfiler. Forventet fravær må ikke blokere aktuelle eller femdøgnsdata.</p><p><strong>Primary er stadig streng:</strong> Uventede optællinger, forskel mellem manifest og filer, auditfejl eller manglende direkte current/future-input stopper fortsat fail-closed. RavRadar interpolerer ikke, backfiller ikke, låner ikke fra nabozoner og skaber ingen syntetiske data.</p><p><strong>Senere modelbeslutning:</strong> DEC-0102/DEC-0112 kræver, at <code>HISTORY_INCOMPLETE</code> i den kommende model fortsat giver score over current+fem døgn ved gyldige direkte input, med auto-forsvindende DA/DE/EN-advarsel ved score, detaljer, fem døgn, admin og ekspert samt <code>calibrationEligible=false</code>. Manglende direkte input er separat utilgængeligt. Dette er ikke implementeret af P0-hotfixen.</p><p><strong>Status:</strong> 4.0.316/<code>49dd4cb</code> er den produktionsverificerede offentlige Candidate G-appbaseline. Datasæt <code>rr-20260830091913-210</code> var komplet som acquisition/public runtime med 210/673, men Candidate G gav 0 aktive/210 <code>UNAVAILABLE</code> på grund af utilstrækkelig sammenhængende historik. Appbaseline og scoretilgængelighed er dermed to forskellige sandheder.</p></div>"},{"id":"retire-stale-candidate-g-gap-reconstruction-4-0-315","chapter":"87","title":"Historisk: Rekonstruktionsinterlock pensioneret i 4.0.315","summary":"4.0.315-retirementen blev merged og frigav D1-gaten, men runnet stoppede senere før artifact/Pages og udgaven blev ikke liveverificeret.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> 4.0.314 kunne vise grøn workflowstatus, mens normal produktion var no-op. 4.0.315 fjernede det umulige reconstruction-prerequisite, men blev ikke deployet, fordi den første post-merge-produktion stoppede ved næste fallbackgate.</div><div class=\"handbook-stack\"><p><strong>Ingen syntetiske data:</strong> Ingen descriptor blev forseglet, ingen apply/rollback/cleanup blev kørt, og ingen interpolerede Candidate G-data blev anvendt eller deployet.</p><p><strong>Retirementen virkede:</strong> DEC-0111 erstattede DEC-0109 operationelt. PR #233 bestod exact-head <code>33299676128</code>, blev merged som <code>63d789a4</code>, og run <code>33299747300</code> frigav historical D1-readiness og startede build.</p><p><strong>Næste gate stoppede:</strong> Runnet fandt ingen gyldig measured-only fallback inden for 72 timer og prognosehorisonten og stoppede før artifact/Pages. 4.0.315 blev derfor ikke produktionsverificeret.</p><p><strong>Målt-only fortsatte:</strong> Manglende historik forblev manglende. Normal gap-checkpoint, continuation, recovery, trust og turkvalitet kunne ikke skabe data.</p><p><strong>Afløst status:</strong> Den afgrænsede optional-fallback-løsning og de fortsatte fulde releasekrav står i kapitel 88 og DEC-0112.</p></div>"},{"id":"candidate-g-policy-bound-cadence-4-0-314","chapter":"86","title":"Historisk: Policybundet cadence og samlet READY-bevis","summary":"Historisk revisionsspor: 4.0.314-planen blev aldrig anvendt og er trukket tilbage af kapitel 87 og DEC-0111; der må ikke køres nyt inspect eller apply.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Dette kapitel er kun historisk revisionsspor. Kapitel 87 og DEC-0111 trak operationen tilbage før descriptor/apply. Der må ikke køres nyt reconstruction-D1, inspect, apply, rollback eller cleanup.</div><div class=\"handbook-stack\"><p><strong>Den daværende plan:</strong> Planen ville have brugt den versionsstyrede regionale proxy-policy til at skelne otte native tre-timersdele fra de øvrige en-timesdele. Den ville have behandlet målte afstande på op til tre timer som sparse continuity uden at udfylde interne slots og ville have bundet en koordinatfri policyhash til descriptor og CAS.</p><p><strong>Historiske beviser:</strong> PR #231 bestod exact-head 33279317463/job 99171645787, blev merged som d539fc9d, og push 33279411885 var no-op. Exact-main D1 33279463545/job 99172031927 bestod kæden. Read-only inspect 33279639424/job 99172534863 stoppede med <code>ONE_TIME_GAP_AMBIGUOUS_NATIVE_CADENCE</code> før descriptor, apply eller mutation.</p><p><strong>Ingen ny operation:</strong> De syntetiske 210/673-tests dokumenterede den aldrig anvendte sikkerhedsplan, men gav ikke driftsautoritet. Manglende historik forbliver manglende. Normal 4.0.315-produktion er measured-only og må ikke vente på et rekonstruktionsbevis. Se kapitel 87 og <code>DEC-0111</code>.</p></div>"},{"id":"one-time-candidate-g-gap-reconstruction-4-0-311","chapter":"85","title":"Historisk: Én kontrolleret rekonstruktion af morgenhullet","summary":"Historisk revisionsspor: 4.0.311–4.0.313-planen blev aldrig anvendt og er trukket tilbage af kapitel 87 og DEC-0111; ingen inspect/apply-operation er tilbage.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Dette kapitel beskriver i datid en aldrig anvendt plan. Kapitel 87 og DEC-0111 trak den tilbage før descriptor/apply. Der må ikke køres nyt inspect, apply, rollback eller cleanup.</div><div class=\"handbook-stack\"><p><strong>Den historiske undtagelse:</strong> Ejeren havde godkendt én snæver plan for incident <code>RRGAP-2026-08-29-CANDIDATE-G-01</code>. En read-only inspektion skulle have bundet eksakte artifacts, 210 zoner/673 kystdele, model/stateKey, cadence og ankre. Kun afledt kystnormal transportstyrke skulle have været interpoleret; vejr, rå U/V, koordinater, geometri, punkter, scoreoutput og private payloads skulle ikke have været rekonstrueret.</p><p><strong>Den planlagte sikkerhed:</strong> Et eventuelt apply skulle have været manuelt, descriptor- og mål-CAS-bundet med privat rollback og kausal cleanup. Schema 2.1- og trustmarkører skulle have holdt afledt evidens ude af kalibrering og observeret 13-timers udtransport. Ingen descriptor, mutation eller syntetisk state blev skabt, så ingen af disse operationer må nu udføres.</p><p><strong>Defensive læsekontrakter består:</strong> Ældre ture uden attesteret trust bevares som historik med <code>calibration_eligible=false</code>; fravær må ikke fail-open som målt. Denne kompatibilitet kan ikke skabe rekonstrueret state og er ikke en driftsgate for operationen.</p><p><strong>Historiske beviser:</strong> 4.0.312 bestod exact-head 33266087776/job 99136292810 og blev merged som a5ece10d. Backend 33266229687/job 99136669571 stoppede før rekonstruktion, vejrbyg, artifact og Pages. 4.0.313 blev exact-head-valideret i PR #226, merged som ff62ba11 og backendverificeret gennem 33269631305. Read-only inspect 33269849748 stoppede før descriptor eller mutation.</p><p><strong>Ingen fortsættelse:</strong> Den daværende fortsættelsesplan i kapitel 86 blev også trukket tilbage. Normal 4.0.315-produktion er measured-only og følger kapitel 87 og <code>DEC-0111</code>; der kræves og tillades ingen ny reconstruction-D1, inspect eller apply.</p></div>"},{"id":"external-production-silence-watchdog-4-0-309","chapter":"84","title":"Ekstern sikkerhed mod stille vejrproduktion","summary":"Ét payloadfrit eksternt kald kan vække RavRadar, hvis hele GitHubs scheduler bliver stille, uden at starte produktion blindt.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> GitHub forsøger fortsat normal vejrproduktion hvert kvarter. Ét eksternt job kontrollerer forskudt ved UTC-minut 04, 19, 34 og 49, om hele GitHubs planlægning er blevet stille.</div><div class=\"handbook-stack\"><p><strong>Ingen blind produktion:</strong> Det eksterne kald starter kun keepalive-/watchdogworkflowet. Fra 4.0.310 kan det efter mere end 15 minutters samtidig gammel runhistorik og gammelt offentligt manifest bestille én normal produktion, når ingen produktion er aktiv eller i kø. GitHubs interne vagt beholder 45 minutter; præcis grænsealder og friske beviser giver no-op.</p><p><strong>Ingen data ud:</strong> Kaldet indeholder kun repository, workflow, <code>main</code> og et boolsk intent. Vejr, koordinater, rå strømvektorer, private data og Candidate G-state sendes ikke til den eksterne tjeneste.</p><p><strong>Uændrede grænser:</strong> Current-hour-, DMI/Copernicus-, 210/673-, Candidate G-, validate-, release- og deploygates er urørte. Der opfindes eller interpoleres ingen historik. Se <code>DEC-0107</code> og <code>DEC-0108</code>.</p></div>"},{"id":"integrated-ravscore-release-candidate-status-2026-08-29","chapter":"Aktuel status","title":"Historisk: den aldrig-offentlige state-5-releasekandidat","summary":"Dette afsnit beskriver den lokale state-5-kandidat, som aldrig blev offentlig og nu kun er eksakt 5→6-migrationskilde; kapitel 89 er gældende.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Kapitel 18, 54 og 55 beskriver 4.0.315-releasekandidaten; de versionsmærkede afsnit dokumenterer offentlig historik.</div><p>Den senest produktionsverificerede offentlige baseline er 4.0.310 med Candidate G. Først efter grøn exact-head-kontrol, merge, frisk produktion og offentlig mobil-/desktopkontrol må <code>RRS-COASTAL-PROCESS-INTEGRATED-1.1.0</code>/state <code>5.0.0</code> blive den eneste offentlige model ved DEC-0110''s atomiske cutover. Denne håndbogsopdatering er ikke produktionsbevis.</p><p>Der findes ingen ekstra offentlig shadowmodel. Mens den integrerede model er aktiv, er Candidate G kun et privat migrations-/offline-/rollback-orakel og aldrig automatisk fallback. Den planlagte fiktive udførelse af morgenhullet blev opgivet før descriptor, apply, mutation eller offentliggørelse. Workflow-inputs/job, incidentpolicy og mutator er fjernet; en negativ gate forhindrer genåbning, mens historiske kvalitetsmarkører stadig læses konservativt. DEC-0109 er kun dokumentation.</p>"},{"id":"public-natural-phrasing-zone-search-4-0-308","chapter":"83","title":"Naturlige sikkerhedsspørgsmål og alle zonehits","summary":"Spørg RavRadar forstår naturlige spørgsmål om hvidt fosfor, og zonesøgningen viser alle navne, som matcher det skrevne.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> To kanter fundet i den offentlige 4.0.307-kontrol er lukket uden at ændre prognose eller model.</div><div class=\"handbook-stack\"><p><strong>Hvidt fosfor:</strong> Naturlige danske, tyske og engelske spørgsmål om hvidt fosfor på stranden finder nu det lokale, officielt kildebundne sikkerhedssvar, også uden ordet rav. Et mistænkeligt fund skal blive liggende; hold afstand og kontakt politiet.</p><p><strong>Alle zonehits:</strong> Ved afslut tur og manuel indberetning filtrerer søgefeltet den eksisterende rullemenu til alle navne, som indeholder teksten. <code>lyn</code> kan derfor vise både Hundested og Lynæs samt navne med Lyngså, mens <code>voer</code> finder Voerså. Ryd feltet for at se hele listen igen.</p><p><strong>Uændrede grænser:</strong> Candidate G, RavScore, vægte, kurver, DMI/Copernicus, state/cache/recovery, geometri og land-/vandpunkter er urørte. Se <code>DEC-0106</code>.</p></div>"},{"id":"owner-correction-extra-high-audit-4-0-307","chapter":"82","title":"Ekstra høj kontrol af ejerens mindre rettelser","summary":"Den samlede ejerpakke er gennemgået igen; Spørg RavRadar har fået 152 kildeklassificerede lokale emner, 395 nm er ensrettet, og udløbne prognosedage er fjernet.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Den ekstra høje gennemgang fandt og lukkede reelle huller i 4.0.306 uden at ændre Candidate G eller scoresemantik.</div><div class=\"handbook-stack\"><p><strong>Langt større lokal viden:</strong> Spørg RavRadar har 152 kildeklassificerede emner oven på de 17 eksisterende intent-svar. De dækker geologi, materiale, identifikation, behandling, kystfysik, feltmetode, sikkerhed, regler og RavRadar. 456 reproducerbare DA/DE/EN-spørgsmål kører uden netværk eller AI-kvote. Grundbogen er suppleret med ekstern forskning, officielle kilder, RavRadars systematiske analyser og Rav Jagt som navngiven praktisk ekspert.</p><p><strong>Mindre restriktiv på det rigtige domæne:</strong> Det generelle afvisningsfilter bruger hele ord, så <em>Skagen</em> ikke længere rammer <em>kage</em>. Edge er udvidet fra 23 til 38 offentlige fakta, mens den private kontekst fortsat er lukket. Lokale fakta- og sikkerhedssvar virker også, hvis prognosedetaljefilen mangler.</p><p><strong>Én UV-sandhed:</strong> Både lokal vejledning og Edge-faktakontrakt bruger 395 nm. Den tidligere 365 nm-formulering er fjernet fra aktive svar.</p><p><strong>Rigtige prognosedatoer:</strong> Et ældre nøddriftsdatasæt viser kun de datoer, der endnu ikke er udløbet i dansk tid. Gamle værdier får aldrig nye datoetiketter.</p><p><strong>Uændrede grænser:</strong> Candidate G, RavScore, vægte, kurver, DMI/Copernicus, state/cache/recovery, geometri og land-/vandpunkter er urørte.</p></div>"},{"id":"owner-learning-ui-assistant-corrections-4-0-306","chapter":"81","title":"Mere viden og tydeligere betjening","summary":"395 nm, koldt vands mobilisering, Rav Jagt-illustrationer, bredere lokal assistentviden, zonesøgning og tydelige kortpile samles i 4.0.306.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Grundbogen, Spørg RavRadar og de små offentlige betjeningsflader er gjort mere præcise og brugbare.</div><div class=\"handbook-stack\"><p><strong>Ravlygte:</strong> Den aktive vejledning bruger 395 nm. Tidligere aktiv tekst om 365 nm er erstattet.</p><p><strong>Koldt vand:</strong> Højere vandtæthed og opdrift kan gøre rav lettere at mobilisere, men temperaturen giver ingen fundgaranti og er ikke tilføjet som scoreinput. Rav Jagts video og krediterede kysttværsnit uddyber den praktiske forståelse.</p><p><strong>Spørg RavRadar:</strong> Lokal viden dækker nu flere spørgsmål om udstyr, fund, årstider, geologi og søgemetode. Åbne specialspørgsmål kan fortsat bruge den sikre, dataminimerede Edge-vej.</p><p><strong>Betjening:</strong> Zoner kan søges ved afslutning og manuel indberetning, kortsignaturen forklarer pilene, strømpilen er mørkere, og mobilknappen kan bryde over to linjer. Tysk og engelsk viser BernsteinScore og AmberScore.</p><p><strong>Uændrede grænser:</strong> Candidate G, scoresemantik, DMI/Copernicus, state, geometri og land-/vandpunkter er urørte. Se <code>DEC-0103</code>.</p></div>"},{"id":"map-tile-seam-removal-4-0-305","chapter":"80","title":"Kort uden flisegitter","summary":"Et afgrænset overlap på rasterkortets billedfliser fjerner hårfine sømme uden at ændre zoner, pile eller data.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Browseren kunne tegne hårfine vandrette og lodrette sømme mellem Leaflets kvadratiske kortfliser. Det lignede et gitter oven på kortet.</div><div class=\"handbook-stack\"><p><strong>Afgrænset rettelse:</strong> Kun standard- og satellitkortets 256 px-rasterfliser overlapper med 0,5 px. Leaflets additive fliseblanding neutraliseres samtidig for netop disse fliser.</p><p><strong>Uændrede kortlag:</strong> Zonefarver, kystlinjer, pile, labels, klikflader og zoom følger fortsat de eksisterende lag og kontrakter.</p><p><strong>Uændrede data:</strong> Candidate G, RavScore, vejr, prognoser, sortering, konto-/turdata, geometri og land-/vandpunkter er urørte. Se <code>DEC-0101</code>.</p></div>"},{"id":"public-ravradar-contact-4-0-304","chapter":"79","title":"Fælles kontakt til RavRadar","summary":"Om RavRadar bruger nu RavRadar-navnet og den fælles RavRadar-mailadresse på alle tre offentlige sprog.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Kontaktknappen under <em>Om RavRadar</em> hedder <strong>Skriv til RavRadar</strong> og åbner <code>RavRadar@outlook.dk</code> i brugerens eget mailprogram.</div><div class=\"handbook-stack\"><p><strong>Samme identitet på alle sprog:</strong> Dansk, tysk og engelsk bruger RavRadar-navnet og den samme mailadresse.</p><p><strong>Privatliv:</strong> Siden sender eller indsamler ikke oplysninger; der sker kun noget, når brugeren selv aktiverer mail-linket.</p><p><strong>Uændrede grænser:</strong> Ændringen påvirker ikke Candidate G, RavScore, vejr, prognoser, sortering, konto-/turdata, geometri eller land-/vandpunkter. Se <code>DEC-0100</code>.</p></div>"},{"id":"mobile-startup-and-first-install-4-0-303","chapter":"78","title":"Hurtig første og varm mobilstart","summary":"RavRadar prioriterer igen kort, manifest og prognosestartpakke i rækkefølge og undgår tung dobbeltindlæsning ved service workerens første installation.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> 4.0.302''s parallelle start så grøn ud på desktop, men gjorde en fysisk iPhone markant langsommere. 4.0.303 gendanner den prioriterede opstart og gør første service-worker-installation lettere.</div><div class=\"handbook-stack\"><p><strong>Fast rækkefølge:</strong> Kortets zoner og kystprojektion kommer først, derefter det friske manifest og til sidst den præcist manifestbundne prognosestartpakke. Den store detaljepakke er fortsat behovsstyret.</p><p><strong>Ingen første installationsreload:</strong> Når en ny worker overtager en hidtil ukontrolleret side, fortsætter den allerede startede visning. En senere rigtig versionsopdatering kan fortsat genindlæse kontrolleret én gang.</p><p><strong>Let installation:</strong> Kortfilen og de store responsive billeder fra <em>Om RavRadar</em> forhåndshentes ikke længere under installation. De findes stadig og cachelagres, når brugeren faktisk åbner dem.</p><p><strong>Om-returen bevares:</strong> RavRadar-knappen bruger fortsat sikker historikretur fra samme-origin-forsiden og almindeligt <code>./</code>-link som fallback.</p><p><strong>Verificeret resultat:</strong> Exact-head, fuld produktion og offentlig 210 + 5 × 5 er grønne. Ejeren målte både kold og varm fysisk iPhone Safari-start til 4–5 sekunder og bekræftede korrekt version samt fungerende Om-retur.</p><p><strong>Uændrede grænser:</strong> Candidate G, RavScore, vejr, prognoser, sortering, konto-/turdata, privatliv, geometri og land-/vandpunkter er uændrede. Se <code>DEC-0099</code>.</p></div>"},{"id":"content-addressed-lazy-public-details-4-0-295","chapter":"77","title":"Hurtigere kort og femdøgnsvisning – også i nødvisning","summary":"Kort, aktuelle områder og fem dage kommer fra en minimal Candidate G-startpakke; fulde detaljer hentes først ved behov og genbruges kun med eksakt dataset- og SHA-binding.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar behøver ikke længere hente alle detaljer for 210 zoner og 673 kystdele, før kortet og femdøgnsvisningen kan bruges.</div><div class=\"handbook-stack\"><p><strong>Samme score:</strong> Produktionsbygningen bruger præcis den eksisterende Candidate G-bestetid og nationale rangering og lægger kun de fem viste zoner pr. dag og søgemåde i startpakken. Det er ikke en ny eller forenklet RavScore.</p><p><strong>Detaljer ved behov:</strong> Den fulde detaljepakke bevares og hentes ved områdevalg, konto, tur, assistentspørgsmål eller dybt kortzoom. Normal opstart undgår dermed cirka 90–132 MB ukomprimeret data uden at fjerne funktioner.</p><p><strong>Minimal aktuel visning:</strong> Efter offentlig kontrol af 4.0.295 blev også den aktuelle READY-scorepost gjort lille. Startup indeholder kun score, dækningsstatus, tre komponenttal, kompakt vejr, minimale vinder-/dellabels og vinderdelens lille DMI-pilbevis. Forklaringsdiagnoser, timeforløb og Candidate G-state forbliver i detaljepakken.</p><p><strong>Sikker genbrug:</strong> En liveprognose må kun genbruges, når adressen indeholder både det præcise dataset-id og filens SHA-kontrolsum fra det friske manifest. Manifest, kortgeometri og andre ikke-indholdsbundne livefiler hentes fortsat frisk.</p><p><strong>Nødvisning:</strong> Candidate G-nødvisningen får samme lille projektion fra sit allerede kontrollerede offentlige datasæt. Kun startup og dens hash ændres; detaljepakke/hash, scorer, tider og state er uændrede.</p><p><strong>Uændrede grænser:</strong> Candidate G, RavScore, vejr, sortering, konto-/turdata, privatliv, geometri og land-/vandpunkter er uændrede. Se <code>DEC-0092</code> og <code>DEC-0093</code>.</p></div>"},{"id":"broad-read-only-assistant-knowledge-4-0-293","chapter":"76","title":"Klogere Spørg RavRadar – også uden AI-kvote","summary":"Almindelige ravspørgsmål besvares lokalt på DA/DE/EN, mens den gratis GPT-OSS får en bredere evidensbundet grundbogsviden bag uændrede sikkerhedsgrænser.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Spørg RavRadar kan nu svare lokalt på 17 almindelige ravemner på dansk, tysk og engelsk. De svar bruger ingen AI-kvote og virker også ved providerfejl.</div><div class=\"handbook-stack\"><p><strong>Bred lokal viden:</strong> Oprindelse, massefylde, skjulte ravlagre, vind, bølger, strøm, vandstand, kystfælder, felttegn, identifikation/UV, waders, vejrforløb, Candidate G, manglende data, begrænsninger, teknik og udstyr har faste grundbogsbaserede svar.</p><p><strong>Naturlige formuleringer:</strong> Oprindelsessvaret genkender også <em>Hvordan opstod rav?</em>, <em>Wie entsteht Bernstein?</em> og <em>How is amber formed?</em> samt tilsvarende dannelsesvarianter. Det er dækket af særskilte DA/DE/EN-regressioner og produktionsverificeret i 4.0.294; de tre svar bruger hverken netværk eller AI-kvote.</p><p><strong>Klogere Edge:</strong> Åbne specialspørgsmål kan fortsat gå til Cloudflare GPT-OSS. Den tilladte viden er udvidet fra 10 til 23 evidens-ID''er om de samme offentlige emner. Eksakt locale, JSON, evidens, længde og domæne kontrolleres fortsat.</p><p><strong>Credentialhygiejne:</strong> Den 28. august 2026 blev Workers AI-credentialen roteret uden ny release eller redeploy. Kun server-secret''en blev erstattet; den nye vej bestod DA/DE/EN, CORS/origin, rate limit og lokal fallback, før de gamle tokens blev tilbagekaldt efter særskilt ejerbekræftelse. Ingen credentialværdi blev vist eller gemt i projektet.</p><p><strong>Ærlige grænser:</strong> Felttegn og kystfælder er spor og muligheder, ikke beviser. RavScore er ikke en procentchance, fundgaranti eller sikkerhedsvurdering.</p><p><strong>Read-only:</strong> Assistenten kan ikke ændre kort, prognoser, RavScore, vejr, sortering, konto-/turdata, geometri eller land-/vandpunkter. Server-only credential, CORS, rate limits, timeout, gratis kvoteloft, lokal fallback og rollbackflag er uændrede. Den offentlige 4.0.294-kontrol viste samtidig farvet kort, fem bedste områder og fem prognosedage. Se <code>DEC-0091</code>.</p></div>"},{"id":"staged-coastal-point-activation-4-0-292","chapter":"75","title":"Sikker ændring af land-/vandpunkter","summary":"Det aktive punkt fortsætter, mens en privat kandidat DMI-valideres og opvarmes; først en særskilt ejeraktivering efter fulde gates kan skifte produktionen.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En flyttet markør bliver ikke længere aktiv ved første gemning. RavRadar holder det hidtidige punkt i drift, indtil den eksakte kandidat er bevist og ejeren særskilt aktiverer den.</div><div class=\"handbook-stack\"><p><strong>Privat kandidat:</strong> Kandidaten samples i de samme DMI-GRIB-filer, men koordinater og rå værdier gemmes kun i privat cache. Offentlig status viser kun revision, fremdrift og årsagskoder.</p><p><strong>READY-krav:</strong> En fælles strøm-U/V-vandkolonne skal ligge højst 5 km væk. Strøm, bølge, vind og vandstand skal have mindst 96 timers horisont, og den nye punkt-/retningskontekst skal have 48 timers sammenhængende Candidate G-hukommelse.</p><p><strong>Ejerstyret aktivering:</strong> READY skifter intet automatisk. Efter <em>Aktivér klar ændring</em> bygges den eksakte runtime og passerer fuld validering. Først derefter opdateres Supabase med versionskontrol; en nyere adminændring stopper skiftet.</p><p><strong>Recovery:</strong> Det tidligere aktive punkt bevares til rollback, og den opvarmede kandidat kan genbruges efter deployfejl. Ved højst seks lokale warmups vises hele det senest verificerede datasæt; gamle og nye zoner blandes aldrig.</p><p>4.0.292 flytter ingen faktiske punkter eller geometri. Se <code>DEC-0090</code>.</p></div>"},{"id":"mobile-page-cache-self-recovery-4-0-301","chapter":"74","title":"Mobil retur og browserens sidecache","summary":"Om-knappen udfører den samme rigtige historikretur som browsertilbage, når brugeren kom fra RavRadar, og beholder statisk fallback ved direkte åbning.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Mobil Safari kan vise en gemt forside igen uden at starte dens JavaScript forfra. Det interne link skal derfor udløse samme historikretur som browserens tilbagefunktion, ikke en ny root-navigation.</div><div class=\"handbook-stack\"><p><strong>Rigtig historikretur:</strong> Når <em>Om RavRadar</em> faktisk blev åbnet fra den samme RavRadar-root, bruger knappen <code>history.back()</code>. Det rammer den eksisterende <code>pageshow.persisted</code>-genoptegning.</p><p><strong>Sikker fallback:</strong> Det statiske link er fortsat <code>./</code>. Tom, ugyldig, fremmed eller anden referrer samt modificerede klik overtages ikke og følger browserens almindelige navigation.</p><p><strong>Genoptegning af eksisterende state:</strong> Ved en færdig persisted retur genopfriskes Leaflet-layout, zonefarver, <em>Bedste områder</em>, valgt zone, <em>5-dages RavRadar</em> og strømpile. Kun en side, der blev gemt før afsluttet appimport, genindlæses.</p><p><strong>Korrigeret evidens:</strong> 4.0.300 var fysisk rød, fordi 4.0.292''s gamle bevis brugte browsertilbage og ikke det interne link. 4.0.301 retter netop denne forskel uden timer, reload, nonce eller watchdog og bevarer 4.0.295/296''s kompakte startup.</p><p><strong>Ingen faglig eller datamæssig ændring:</strong> Recoveryen skriver ingen data og ændrer ikke Candidate G, RavScore, vejr, prognoseinput, sortering, konto-/turdata, geometri eller land-/vandpunkter. Se <code>DEC-0089</code> og <code>DEC-0098</code>; DEC-0094–0097 er historiske.</p></div>"},{"id":"causal-production-bounded-recovery-4-0-289","chapter":"73","title":"Årsagstro produktion og robust genopretning","summary":"RavRadar vælger aldrig en fremtidig produktionstime, bevarer kompakt recoveryfremdrift og viser kun et komplet fallback inden for 72 timer og dets egen prognosehorisont.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> En fejlet provider eller slutkontrol må ikke gøre RavRadar sort, miste ægte Candidate G-fremdrift eller flytte produktionen ind i en fremtidig prognosetime.</div><div class=\"handbook-stack\"><p><strong>Årsagstro tid:</strong> Hvis den låste DMI-time mangler strøm, må produktionen kun vælge den bedst dækkede nærmeste time bagud inden for tre timer. Copernicus udfylder kun de eksakte huller og får højst to seksminutters forsøg.</p><p><strong>Kompakt checkpoint:</strong> Efter runtimebygningen gemmes præcis 673 hash- og modelbundne Candidate G-states. Vejr, scoreoutput, rå strømvektorer, koordinater, geometri, land-/vandpunkter og private data gemmes ikke.</p><p><strong>Ét komplet fallback:</strong> Startvisning, områdedetaljer, <em>Bedste områder</em> og <em>5-dages RavRadar</em> kommer fra samme auditerede dataset. Det må højst bruges i 72 timer og aldrig efter sin egen seneste prognosetime.</p><p><strong>Kontrolleret orkestrering:</strong> En fejlet, timeoutet eller før-start-fejlet planlagt kørsel får ét genforsøg. Et payloadfrit watchdog reagerer først efter 45 minutters stilhed og kun uden aktiv produktion; tunge builds kører aldrig parallelt. Watchdoget er internt i GitHub og kan ikke alene opdage total stilhed i hele GitHubs scheduler.</p><p><strong>Uændret faglig model:</strong> Candidate G 20/50/30, +10/-8-/13-timersfysikken, DMI-først, vejr, normal sortering, konto-/turdata, geometri og land-/vandpunkter er uændrede. Se <code>DEC-0085</code>.</p></div>"},{"id":"hybrid-auth-eu-trip-storage-4-0-287","chapter":"71","title":"Supabase-login og EU-turlager med envejs-cutover","summary":"Supabase bevarer login og Edge, mens dataminimerede, HMAC-pseudonymiserede ture flyttes til ti EU-låste D1-shards gennem en varigt fasebundet D1-cutover.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Login bliver i Supabase. Normale ture kan gemmes i et større EU-lager uden rå bruger-id, mail, navn, JWT, GPS, rute, koordinater eller rå strømvektorer.</div><div class=\"handbook-stack\"><p><strong>Identitets- og læsegrænse:</strong> Supabase Edge verificerer login og erstatter bruger-/anonym-id med et versionsbåret HMAC-pseudonym, før en tur sendes til Cloudflare. Migration og idempotens-readback henter kun eksplicitte sikre kolonner og bladfelter; hele nested JSON-objekter læses ikke ind over grænsen. Schema-v2 readback validerer den strenge lagrede top-level- og nested-allowlist før projektion; ukendte felter, også null, stopper fail-closed.</p><p><strong>Global idempotens og sletning:</strong> Et payloadfrit registry i shard 0 reserverer klient-/turidentitet på tværs af alle ti shards. En permanent, payloadfri ejer-tombstone sættes før sletning og vinder over samtidige eller forsinkede writes og migrationer. Canonical hash og readback afviser både ændrede dubletter og lagret korruption.</p><p><strong>Envejs, genkørbar cutover:</strong> D1-schema og den varige aktiveringsfase læses før enhver modeændring. Efter kapacitetsbevis og exact-main-kontrol registreres installationstypen umiddelbart før første Edge-deploy. Maintenance-kapabel Edge deployes under uændret mode og gammel Worker. Eksisterende D1 dobbeltattesteres i D1-mode, får derefter en 20-minutters maintenance-lease og dræner gamle requests; først med mindst ti minutters restlease må Worker-secret, deploy og health køre som én højst syv minutter lang gate. En helt ny installation forbliver i Supabase gennem første synk og får først D1-mode efter sin current-run aktiveringsintention og varige markør. Efter D1-aktivering attesteres begge Edge-grænser to gange uden cache, der drænes 20 sekunder, og Supabase-kilden reconcileres idempotent.</p><p><strong>Ingen skjult rollback:</strong> D1 bruger kun HMAC-ejere og kan ikke sikkert gendanne Supabases direkte ejerbinding. En post-activation Supabase-toggle ville derfor skjule D1-only ture og er fjernet som operativ mulighed. Et delvist Edge-deploy på eksisterende D1 må kun repareres fremad i D1. Et delvist Edge-deploy på en dokumenteret helt ny installation repareres derimod med ny exact-main-kontrol, genindsat Supabase-secret, eksakt Edge-redeploy og dobbelt Supabase-attestation. Fejl før kapacitetsbevis/predeploy-CAS har intet current-run intent og må ikke udføre ekstern recoverymutation. Manglende, ukendt eller ugyldig storage-mode fejler lukket med 503.</p><p><strong>Afgrænset legacy-replay:</strong> 4.0.313 kan anerkende en historisk migrationsrække, hvis eneste formforskel er kendte null-blade, som den sikre bladprojektion udelader. Undtagelsen gælder kun migration→migration ved forskellig hash og eksakt kerne-/ikke-null-lighed. Den lagrede D1-række, dens oprindelige hash og registrybinding omskrives aldrig; en manglende registryrad må kun repareres med den oprindelige hash. Live-kilder eller modstridende bindinger afvises.</p><p><strong>Drift:</strong> Et payloadfrit dagligt job advarer ved 70 % og stopper ved 85 %; manglende kapacitetsfelt accepteres ikke som nul. Supabase-varslet fra 9. september 2026 overvåges fortsat, fordi Auth/Edge-egress bliver i Supabase. <strong>Status:</strong> 4.0.312 blev merged som <code>a5ece10d</code>, men backend <code>33266229687</code> stoppede i migrationssynken med <code>TRIP_GATEWAY_UNAVAILABLE</code>; recovery er ikke readiness. 4.0.313 lukkede den afgrænsede genafspilning og blev backendverificeret gennem <code>33269631305</code> uden omskrivning af eksisterende D1-række, hash eller registrybinding. Den planlagte rekonstruktion blev aldrig anvendt og er trukket tilbage af kapitel 87 og <code>DEC-0111</code>; den kræver intet nyt D1-bevis, og der må ikke køres inspect/apply for den. Turlagerets egne kontrakter fortsætter uafhængigt. Se <code>DEC-0082</code>.</p></div>"},{"id":"candidate-g-rolling-boundary-continuity-4-0-286","chapter":"70","title":"Rullende Candidate G-kontinuitet og kontrol før udgivelse","summary":"Et virkeligt kompakt grænsebevis følger til næste reference, godkendte native holds bruger kun READY memory, og den nybyggede runtime kontrolleres før deploy.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> En prøve lige før et faseskudt 48-timersvindue kan bevise sammenhæng og skal bevares til næste rullende reference, men tæller aldrig som en ny måling i det aktuelle vindue.</div><div class=\"handbook-stack\"><p><strong>Rullende kontinuitet:</strong> Det virkelige kompakte grænsebevis følger transporthukommelsen til næste reference, så en dokumenteret 48-timerskæde ikke falsk bliver kort ved næste produktion.</p><p><strong>Ingen interpolation:</strong> Beviset før grænsen afspilles ikke, giver ingen ekstra dækningsminutter og ændrer ikke den faste begyndelsestilstand 0. Et reelt kort vindue uden forgænger og huller over tre timer forbliver utilgængelige.</p><p><strong>Godkendt native pause:</strong> De otte ejerallowlistede Limfjordsproxyer må bruge den allerede afledte transport- og mobiliseringstilstand mellem ægte tretimersmålinger, men kun når hukommelsen er READY, den sidste reference er højst tre timer gammel, og der ikke vises U/V, fart, retning, alignment eller pil som en aktuel måling. Almindelig uverificeret eller for gammel strøm giver fortsat ingen score.</p><p><strong>Kontrol før udgivelse:</strong> Produktionskæden auditerer den faktisk nybyggede offentlige Candidate G-runtime, før Supabase-sync, artifact og Pages. En landsdækkende accepteret, men for kort state eller manglende READY-score stopper før deploy.</p><p>Candidate G 20/50/30 og +10/-8-/13-timersfysikken, vejr, zoner, geometri og land-/vandpunkter er uændrede. Se <code>DEC-0081</code>.</p></div>"},{"id":"candidate-g-cadence-phase-boundary-recovery-4-0-285","chapter":"69","title":"Candidate G ved en forskudt 48-timersgrænse","summary":"Et komplet verificeret tretimersforløb bevares, når den aktuelle reference ligger mellem native prøver, uden at RavRadar opfinder en måling.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Candidate G kræver 48 timers sammenhængende verificeret strøm. Når den aktuelle reference ligger mellem to native tretimersprøver, må et komplet forløb ikke blive falsk kort alene på grund af klokketimens fase.</div><div class=\"handbook-stack\"><p><strong>Dokumenteret grænse:</strong> Der skal både findes et verificeret kompakt bevis umiddelbart før 48-timersgrænsen og et efter grænsen inden for højst tre timer.</p><p><strong>Ingen interpolation:</strong> Beviset før grænsen dokumenterer kun sammenhæng. Det føjes ikke til det aktive vindue som en ny måling, og den faste rand er fortsat 0 på det eksakte grænsetidspunkt.</p><p><strong>Fortsat fail-closed:</strong> Et ægte 47-timersdatasæt uden forgænger, missing, manglende seneste bevis eller et internt hul over tre timer giver ingen score.</p><p><strong>Engangsrecovery:</strong> Den fejlramte 4.0.284-lineage samles kun med afledte transportbeviser fra den eksakte hash-låste sidste sunde offentlige state. Vejr, rå strøm, koordinater, scoreoutput, geometri, land-/vandpunkter og private data kopieres ikke.</p><p>Candidate G 20/50/30 og dens fysiske regler er uændrede. Se <code>DEC-0081</code>.</p></div>"},{"id":"security-boundaries-public-edge-gateways-4-0-284","chapter":"68","title":"Sikker drift og afgrænsede adgange","summary":"4.0.284 flytter tillid fra browseren til smallere HTML-, rettigheds- og Edge-kontrakter og bruger den lokale assistent som standard.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Dynamisk HTML saniteres, ekspertadgang er begrænset i databasen, og observationer går gennem en validerende servergateway i stedet for direkte tabelinsert.</div><div class=\"handbook-stack\"><p><strong>Sikker visning:</strong> Offentlige sider bruger Content Security Policy uden inline JavaScript. Centralt håndbogs-HTML går gennem en allowlist, som fjerner aktive elementer, event handlers, inline-stil, DOM-id''er, ukendte attributter og farlige links.</p><p><strong>Smallere ekspertadgang:</strong> <code>experts_manage</code> kan kun se ekspertprofiler og de tre adgange <code>admin_access</code>, <code>handbook_view</code> og <code>handbook_review</code>. Kun ejer eller fuld administrator kan administrere hele rettighedsmatricen og reviewkøen.</p><p><strong>Sikker observation:</strong> Browserroller kan ikke indsætte direkte i observationstabellen. Edge-gatewayen håndhæver feltallowlist, payloadgrænser, privatliv, brugerbinding, anonym tidsgrænse, idempotens og rate limit før lagring.</p><p><strong>Lokal assistent:</strong> Fjernassistenten er deaktiveret i 4.0.284. RavRadar bruger den lokale Candidate G-assistent og sender ikke spørgsmål eller kontekst til en ekstern model uden en senere særskilt godkendt secret-, omkostnings- og driftsbeslutning.</p><p><strong>Drift:</strong> Supabases mulige begrænsning fra 9. september 2026 overvåges. Kvotehensyn må ikke lempe privatliv, RLS, rate limits eller releasegates.</p><p>Candidate G 20/50/30, score, vejr, zoner, geometri og land-/vandpunkter er uændrede. Se <code>DEC-0080</code>.</p></div>"},{"id":"candidate-g-parent-zone-audit-binding-4-0-283","chapter":"67","title":"Moderzonen bevares i Candidate G-slutkontrollen","summary":"Slutkontrollen beholder nu den autoritative moderzone, når 210 zonegrupper foldes ud til 673 kyststrækninger.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Produktionen havde 673/673 scoreklare kyststrækninger, men slutkontrollen mistede moderzonen under udfladning og kunne derfor ikke genkende otte gyldige native-kadencereferencer.</div><div class=\"handbook-stack\"><p><strong>Samme autoritative kobling:</strong> Moderzonen står som nøglen i kystdelsfilens zonegrupper. Kontrollen kopierer nu denne nøgle med ind i sin flade liste.</p><p><strong>Ingen lempelse:</strong> Rettelsen opfinder ingen måling, historik, retning, pil eller mobilisering. Manglende verificeret strøm stopper fortsat den konkrete kystdel lokalt.</p><p><strong>Produktionsbevist:</strong> Offentlig 4.0.283 har 673/673 kyststrækninger i Candidate G-kæden. 657 har komplet transporthukommelse; 16 er ærligt lokalt utilgængelige under naturlig modning uden reset.</p><p>Candidate G 20/50/30, vejr, zoner, geometri, land-/vandpunkter, admin-data og brugerdata er uændrede. Se <code>DEC-0079</code>.</p></div>"},{"id":"candidate-g-native-window-reference-4-0-282","chapter":"66","title":"Eksakt native reference ved beregningsvinduets begyndelse","summary":"En verificeret tretimersmåling lige før et nyt beregningsvindue kan fortsætte transporttilstanden uden interpolation eller en opdigtet ny måling.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Nogle godkendte regionale strømkilder måler hver tredje time. Ligger den seneste ægte måling lige før Candidate G''s beregningsvindue, kan RavRadar bruge den som transportreference i højst tre timer.</div><div class=\"handbook-stack\"><p><strong>Ikke en ny måling:</strong> Referencen skaber ingen ny pil, bevægelsestime eller mobilisering og udfylder ikke mellemtimer med opdigtede værdier.</p><p><strong>Dataminimeret:</strong> Før den gemmes i Candidate G-state, reduceres den til tidspunkt og kystrelativ transportstyrke. Rå U/V, koordinater og punkt-id''er føres ikke videre.</p><p><strong>Fortsat fail-closed:</strong> Er målingen ældre end tre timer, forkert placeret eller ikke verificeret, bliver den konkrete kystdel fortsat utilgængelig.</p><p>Candidate G 20/50/30, 48-timershistorik, scorekurver, zoner, geometri og land-/vandpunkter er uændrede. Se <code>DEC-0078</code>.</p></div>"},{"id":"candidate-g-native-technical-diagnostics-4-0-281","chapter":"65","title":"Candidate G-native teknisk kontrolvisning","summary":"Den tekniske visning læser nu Candidate G''s egne forklaringsfelter, så Mangler og Ukendt kun vises ved et reelt manglende grundlag.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Candidate G beregnede oplysningerne korrekt, men den tekniske visning læste pensionerede felter fra den gamle scoremotor. Selve RavScore var ikke ændret af visningsfejlen.</div><div class=\"handbook-stack\"><p><strong>Samme motor og forklaring:</strong> Visningen følger nu Candidate G 20/50/30 og forklarer strømstatus, transportreference, 48-timershistorik, fase, udgående forløb, transporttab, levering, rav i bevægelse og samlet RavScore.</p><p><strong>Ærlige mellemtimer:</strong> Når en godkendt strømkilde leverer på native tretimerskadence, står der, at der ikke er kommet en ny måling denne time, og at den seneste verificerede tilstand fastholdes. RavRadar opfinder ikke en ny rå retning, forskel eller klassifikation.</p><p><strong>Historikken betyder noget:</strong> Transportscoren vurderer både den aktuelle strøm og det dokumenterede forløb i det rullende 48-timersvindue. En nyligt begyndt indtransport kan derfor godt have en moderat score, selv om pilen lige nu peger mod kysten.</p><p><strong>Reelle mangler:</strong> Ordene Mangler og Ukendt bruges kun, når det konkrete Candidate G-grundlag faktisk ikke findes, ikke fordi UI''et leder efter et gammelt feltnavn.</p><p>Scorekurver, vejr, zoner, geometri, land-/vandpunkter og private data er uændrede. Se <code>DEC-0077</code>.</p></div>"},{"id":"public-about-ravradar-4-0-279","chapter":"64","title":"Offentlig Om RavRadar-side","summary":"RavRadar viser nu tydeligt, hvem der står bag, hvordan RavScore bør forstås, og hvordan brugeren kan kontakte eller frivilligt støtte projektet.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Forsidens topmenu linker til en ny Om RavRadar-side med Jakob Jørgensen, projektets formål, kontakt og frivillig støtte.</div><div class=\"handbook-stack\"><p><strong>RavScore i sammenhæng:</strong> Scoren vurderer de aktuelle forhold for den enkelte kyststrækning. Den måler ikke, hvor meget rav der grundlæggende findes i landsdelen. Derfor kan 95 point i Limfjorden godt være et dårligere fundvalg end 75 point ved Sæby.</p><p><strong>En model af virkeligheden:</strong> Vejr, havstrømme og kyster er komplekse. Landsdækkende kode må nogle gange bruge en forståelig forenkling; noget, der ser forkert ud, kan være en fejl eller et bevidst kompromis af hensyn til helheden.</p><p><strong>Frivilligt og gratis:</strong> Projektet er gratis at bruge. MobilePay Box <code>4214MX</code> vises med godkendt link og QR-kode. Støtte er frivillig og giver ingen særlige funktioner eller scorer.</p><p><strong>Teknisk:</strong> Siden er responsiv på pc og mobil, bruger komprimerede billedvarianter, indgår i appskallen og indsamler ingen nye brugerdata. Se <code>DEC-0076</code>.</p></div>"},{"id":"candidate-g-only-local-availability-4-0-274","chapter":"63","title":"Historisk 4.0.274: Candidate G som eneste offentlige scoremodel","summary":"I 4.0.274 skjulte et lokalt datahul kun den berørte zone eller søgemåde, mens resten fortsatte på Candidate G 20/50/30.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> Fra 4.0.274 og frem til den integrerede models atomiske cutover var Candidate G den eneste offentlige model med 20 % søgeforhold, 50 % transport og 30 % rav i bevægelse. Afsnittet dokumenterer den daværende kontrakt; den aktuelle lokale releasekandidat står i kapitel 18.</div><div class=\"handbook-stack\"><p><strong>Lokal og ærlig utilgængelighed:</strong> Hvis en zone, søgemåde eller time manglede et sammenhængende Candidate G-grundlag, blev ingen score vist dér. RavRadar lånte ikke et tal fra den gamle model, en moderzone, en nabozone eller en anden time.</p><p><strong>Resten fortsatte:</strong> Den berørte score blev udeladt fra <em>Bedste områder</em> og <em>5-dages RavRadar</em>. Andre zoner fortsatte normalt på Candidate G.</p><p><strong>Samme scorevej overalt:</strong> Forsiden, detaljepanelet og Rav-assistenten brugte den samme lokale Candidate G-beregning. En manglende beregning blev ikke erstattet af en skjult ældre motor.</p><p><strong>Adminstatus:</strong> Adminforsiden viste, om alle zoner var aktive. Hvis ikke, blev de berørte zoner, søgemåder og forståelige årsager listet uden rå strømvektorer, koordinater eller private data.</p><p><strong>Central beskyttelse:</strong> En centralt gemt ældre fallbackkonfiguration måtte ikke overskrive Candidate G-only-kontrakten under produktion. Hydrering, central persistence, state-recovery og releasegates stoppede ved forsøg på rollback.</p><p>Beslutningen opfandt ingen data og ændrede ingen Candidate G-regel, geometri eller land-/vandpunkter. Se <code>DEC-0072</code>.</p></div>"},{"id":"candidate-g-state-continuity-recovery-4-0-272","chapter":"62","title":"Candidate G fortsætter kun fra dokumenteret tilstand","summary":"Produktionen stopper nu, hvis den tidligere Candidate G-tilstand ikke kan hentes som et sammenhørende datasæt, og den landsdækkende nulstart genbruges ikke som normal opvarmning.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> En timeout ved hentning af den offentlige conditions-fil fik en produktion til at fortsætte uden tidligere Candidate G-hukommelse. Det gav kunstigt lave scorer i hele landet. Senere timer fortsatte fra den forkerte nulstart. Fra 4.0.272 stopper samme fejl før offentliggørelse.</div><div class=\"handbook-stack\"><p><strong>Atomisk fortsættelse:</strong> Manifest og conditions skal hentes som ét sammenhørende datasæt. En global <code>NO_PREVIOUS_STATE</code>-nulstart er ikke længere en lovlig opvarmning af den aktive Candidate G.</p><p><strong>Afgrænset recovery:</strong> Den aktuelle engangsrettelse genoptager kun den kompakte Candidate G-tilstand fra den sidste fuldt grønne 673-deles produktion. Kørsel, kildedatasæt, delbestand, tilstandstyper og samlet integritet skal passe eksakt. Den nulstillede fortsættelseslinje genkendes kun i det dokumenterede tidsvindue og kun, når næsten alle dele mangler historik fra før fejlen. Når historikken er tilbage, er rettelsen straks inaktiv. Vejr, scoreformel, vægte, zoner, geometri og land-/vandpunkter kopieres ikke.</p><p><strong>Bevidste punktændringer:</strong> En lille lokal nulstilling med <code>COASTAL_PART_CONTEXT_CHANGED</code> er fortsat lovlig efter en ejerændring af et punktpar. Den berørte del skal selv skaffe frisk tilladt strøm; den må ikke låne en moderzones eller nabodels måling. 673/673-gaten forbliver uændret.</p><p>Se <code>DEC-0071</code>. Rettelsen ændrer ikke Candidate G''s 20/50/30-model eller dens fysiske regler.</p></div>"},{"id":"public-amber-hunting-field-corrections-4-0-271","chapter":"61","title":"Historisk 4.0.271: feltrettelser til Grundbog i ravjagt","summary":"4.0.271 skelnede skarpere mellem dokumenteret fysik, den daværende RavRadar-kontrakt og praktisk felterfaring.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> 4.0.271 skelnede mellem dokumenteret fysik, den daværende offentlige model og ejerens praktiske felterfaring. Den aktuelle integrerede kontrakt står i kapitel 18.</div><div class=\"handbook-stack\"><p><strong>Dokumenteret fysik:</strong> Koldere saltvand er normalt lidt tættere end varmere saltvand med samme saltindhold og kan derfor give rav en smule større opdrift. Effekten er for lille til at få det meste almindelige rav til at flyde.</p><p><strong>Præciseret strømbegreb:</strong> Vind, overfladestrøm og den verificerede modelgridstrøm holdes adskilt. Det dybeste tilgængelige modelgridlag er ikke en måling af den lokale bundnære strøm, undertow eller ripcirkulation; retningen vurderes mod den konkrete kyst og det foregående forløb.</p><p><strong>Praktisk felterfaring fra ejeren:</strong> Rav kan findes i revlehullet, på kystsiden lige bag hullet og på bagsiden af revlen nær hullet. Der skal også søges bag en frisk tanglinje. Speciallygter med ikke offentligt oplyste bølgelængder kan under visse forhold gøre rav lettere at se gennem alger i vand. Disse observationer er nyttige søgetips, ikke universelle regler eller nye scoreinput.</p><p><strong>Rettede misforståelser:</strong> Grus blev fjernet som almindeligt ravtegn, fralandsvind blev adskilt fra udgående modelgridstrøm, og den fejlvendte kystpil blev rettet.</p><p>Se <code>DEC-0070</code> og <code>docs/research/PUBLIC_LEARNING_FIELD_CORRECTIONS_4.0.271.md</code>. Rettelsen var score-neutral.</p></div>"},{"id":"prelaunch-expert-admin-visible-ranking-4-0-270","chapter":"60","title":"Før-lancering, ekspert og synlig rangering","summary":"De nationale lister viser deres fair områdescore, og ekspertens håndbog og adminværktøjer er kontrolleret mod den aktive Candidate G-model.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> Højeste viste områdescore står nu øverst, uden at områder med mange kyststrækninger får flere lodder i lotteriet.</div><p>Områdescoren tager både bedste kyststræknings RavScore og støtte fra flere strækninger med. Når området åbnes, vises fortsat den bedste kyststræknings almindelige RavScore.</p><p>Adminens første lagerkontrol omfatter også <code>coastline-overrides</code>, så en eksisterende kystoverstyring ikke vises som en falsk fejl. Eksperten kan læse og kommentere håndbogen med <code>admin_access</code>, <code>handbook_view</code> og <code>handbook_review</code> uden fuld ret til score, vejr eller kystdata. Officielle håndbogsopdateringer trevejsflettes mod sidste kildebaseline, så centralt godkendte ekspertændringer ikke overskrives ved deploy.</p><p>Arbejdsplanen, kodekapitlet, scenarierne og hypoteseregisteret beskrev den daværende aktive Candidate G med 20/50/30, 48 timers transportvindue, +10/-8-forløbet, 13-timersreglen, waderskurven 6–15 m/s og én bølgeenergistyret mobiliseringstilstand. Gamle 25/40/35-regler er historik; DEC-0072 har fjernet dem som offentlig rollback.</p><div class=\"callout\"><strong>Uændret:</strong> Lokale RavScore-tal, farver, fysisk model, vejrdata, geometri og land-/vandpunkter blev ikke ændret i 4.0.270. Se DEC-0069.</div>"},{"id":"public-current-score-explanations-4-0-269","chapter":"59","title":"Aktuelle scoreforklaringer og enkel zonevisning","summary":"De tre RavScore-komponenter forklarer den viste kystdels faktiske forhold, mens umodne eller tekniske felter holdes ude af den almindelige brugerflade.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> Dette afsnit dokumenterer den offentlige 4.0.269-leverance. Candidate G var den daværende model. Den aktive integrerede kontrakt står i kapitel 54–56; vandstand giver ingen direkte score og kan ikke i sig selv fastslå den lokale sidste-mil-retning.</div><p><em>Hvorfor denne score?</em> skulle fortælle, hvad den aktuelle vind, bølger og strøm betød på den valgte kystdel – ikke blot vise en standardsætning fra scoreintervallet.</p><p><strong>Rav i bevægelse</strong> betød, at bølger – ofte skabt af vind – kunne løsne allerede tilgængeligt rav og andet let materiale fra havbund, tang eller kystnære aflejringer og holde det i bevægelse. Vind gav ikke direkte mobiliseringspoint; strømmen stod for transporten.</p><p>Den daværende tekst forklarede et lavt aktuelt vandniveau og stigende vandstand. Den aktive integrerede model bruger i stedet vandstand som score-neutral kontekst: faldende vand bestemmer ikke strømretningen, men kan falde sammen med søværts transport af noget mobilt rav. Lavere vand kan desuden blotlægge rav, som allerede er afleveret eller fastholdt bag revler; det beviser ikke fysisk koncentration.</p><p>Den offentlige <strong>Fundprognose</strong> var skjult, indtil afsluttede ture med fund og intet fund udgjorde et repræsentativt grundlag. Observationer og intern læring blev bevaret. <strong>Anvendte scorelofter</strong> og den rå tekniske scorevisning var også skjult, men den bagvedliggende logik var ikke slettet.</p><p>Det tomme <strong>Vælg et område på kortet</strong>-felt blev fjernet. Kortvalget var uændret, og informationspanelet åbnede efter et valg.</p><div class=\"callout\"><strong>Daværende aktiv model:</strong> Candidate G brugte 20 % søgeforhold, 50 % transport og 30 % rav i bevægelse. Afsnittets tidligere globale 25/40/35-reserve var erstattet af DEC-0072; et datahul gjorde kun den konkrete Candidate G-score utilgængelig.</div><div class=\"callout\"><strong>Historisk produktionsbevis:</strong> PR #120/exact-head 32703138969, merge d745e0ba og produktion 32703271897 udgav 4.0.269 som rr-20260824080543-210 på 210/673. Browserkontrollen bestod 420 aktuelle, 2.100 femdøgns- og 673 kystdelsvisninger uden fejl.</div>"},{"id":"public-amber-hunting-learning-4-0-268","chapter":"58","title":"Grundbog i ravjagt – fra havbund til fund","summary":"Det offentlige læringsmodul lærer først ravjagtens fysiske kæde, felttegn og metoder og forklarer derefter RavRadar som værktøj.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Grundbogens huskeregel er: <strong>Bølger kan mobilisere. Strøm transporterer. Kysten sorterer og samler.</strong> Retninger skal altid ses i forhold til den konkrete kyst; der findes ikke én dansk vind- eller strømretning, som altid er bedst.</div><p>Grundbogen følger ravets egenskaber og mulige lagre gennem mobilisering, strømtransport, revler, render, opskyl og lokale kystfælder. Den forklarer felttegn som frisk tang, træ, frø, kul, skaller og sorterede linjer som spor frem for fundgaranti.</p><p>Metodeafsnittene dækker stranden, vandkanten, waders og UV-lys. Langbølget UV omkring 395 nm kan være et godt spor, men er ikke et endeligt ægthedsbevis. Varme nåle, ild og andre ødelæggende hjemmetests frarådes.</p><p>Først efter selve ravjagten forklares den integrerede RavScore som et værktøj med 20 % søgeforhold, 50 % transportbevis og 30 % rav i bevægelse. Waders-kurven og gridstrømmens +10/-8 pr. effektiv time er RavRadars testede produktpriorer, ikke universelle naturgrænser. Et langt kraftigt udgående forløb kan gøre transportbeviset 0, men den historiske 13-timers helscore-gate er fjernet, fordi RavRadar hverken observerer ravlageret eller den lokale surfzone.</p><div class=\"callout\"><strong>Viden og usikkerhed:</strong> Modulet skelner direkte forskning, stærk kystfysisk analogi, praktisk erfaring, myter og åbne lokale spørgsmål. RavRadar beskriver rav- og søgeforhold, ikke om en tur er sikker.</div><p><strong>Historisk versionsnote:</strong> 4.0.268 ændrede kun læringsmodulet og almindeligt brugersprog; den daværende Candidate G, score, vejr, geometri, land-/vandpunkter og private data var uændrede. Den aktive modelkontrakt står nu i kapitel 18 og DEC-0110.</p>"},{"id":"observation-upload-closure-4-0-267","chapter":"57","title":"Turindberetningen er lukket ende til ende","summary":"4.0.267 har den fulde uploadkontrakt, bevarer privatlivsgrænsen og er bekræftet af en virkelig ejerindberetning.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar accepterer den krævede tomme lokationsværdi, men afviser fortsat faktiske GPS-, koordinat-, positions-, rute- og spordata.</div><p>Den aktive observationstabel har de to ekstra felter, som kontoindberetningen kræver. Privatlivskontrollen tillader kun værdien <code>null</code> i det krævede lokationsfelt.</p><p>PR #115 bestod exact-head <code>32664463654</code>, blev merged som <code>43ceffc1</code>, og produktion <code>32664525128</code> bestod hele kæden. Ejeren oprettede derefter en ny indberetning, som blev sendt og synlig i <strong>Mine ture og fund</strong>.</p><div class=\"callout\"><strong>Ingen skjult eftersendelse:</strong> De to tidligere forsøg blev stoppet før den lokale kø og blev derfor ikke sendt senere eller oprettet som dubletter.</div><p>Score, vejr, geometri og land-/vandpunkter er uændrede. Se DEC-0066.</p>"},{"id":"production-auth-and-trip-log-4-0-266","chapter":"56","title":"Historisk 4.0.266: Login og Mine ture og fund","summary":"Magic-link- og ejerskabskravet består; den tidligere direkte Supabase-turlæsning er erstattet af DEC-0082''s private Edge-/D1-vej.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Et magic link er et tidsbegrænset engangslink via mail. Det skal føre tilbage til den RavRadar-side, hvor det blev bestilt. <strong>Mine ture og fund</strong> viser de samme eksisterende turposter og opretter ingen kopi.</div><p>Supabase skal have hjemmesidens kanoniske adresse som både standardadresse og tilladt login-returadresse. Den aktuelle adresse er <code>https://jakobjorgensen82-commits.github.io/RavRadar/</code>. Når siden flyttes til <code>https://ravradar.dk/</code>, skal begge indstillinger ændres i samme deployment, og et nyt magic link skal prøves på den nye adresse.</p><p>Kun en indlogget ejer må læse observationer med sit eget bruger-id. Listen henter højst de seneste 100 ture. Kvalitetsmarkørerne fortæller blandt andet, om en tur er indtastet bagefter og ikke har et sikkert historisk vejrgrundlag; de må ikke indeholde mail, navn, GPS, rute eller fri tekst.</p><div class=\"callout\"><strong>Afventende tur:</strong> Hvis en tur ikke kunne sendes færdigt, bliver den i den lokale leveringskø på enheden og prøves igen med samme klient-id ved næste sideindlæsning. Det opretter ikke en dublet.</div><p>Hvis listen midlertidigt ikke kan hentes, bruger RavRadar en enkel brugerforklaring og viser ikke interne leverandørnavne.</p>"},{"id":"account-trip-reporting-and-log-4-0-265","chapter":"55","title":"Historisk 4.0.265: Indberet tur eller fund fra kontoen","summary":"Rapportflowet består, men den fysiske Supabase-lagring er erstattet af DEC-0082''s ene logiske post i det aktive EU-turlager.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En indlogget bruger kan vælge <strong>Indberet tur eller fund</strong> uden først at starte en tur. Brugeren vælger dato og klokkeslæt for turens start samt varigheden. De samme enkle spørgsmål om jagtform, område, kyststrækning, søgning og fund bruges i begge rapportveje.</div><p>RavRadar sætter aldrig dagens vejr på en ældre tur. Hvis et sikkert historisk vejr- og scoresnapshot ikke findes, gemmes turen stadig som erfaring, men den bruges ikke direkte til at ændre scorereglerne eller den aktuelle beregnede fundchance.</p><p>Efterregistreringen gemmes som én turpost i den eksisterende <code>observations</code>-tabel og vises under <strong>Mine ture og fund</strong>. Der oprettes ingen ny tabel eller særskilt fundpost. Listen hentes først ved brugerens klik, viser højst de seneste 100 ture og kan kun læses af ejeren gennem Supabases adgangsregler.</p><div class=\"callout\"><strong>Tre valg ved afslutning:</strong> <strong>Indsend tur</strong> gemmer rapporten. <strong>Svar senere</strong> bevarer turen på enheden. <strong>Afslut uden at indberette</strong> kræver bekræftelse og rydder turen uden at sende en rapport.</div><p>RavRadar indsamler ikke GPS-spor, rute, præcis position, fri tekst eller billeder. Mailadresse og navn gemmes ikke i turposten. Candidate G, 20/50/30, geometri og vejrruntime er uændrede.</p><div class=\"callout\"><strong>Magic link:</strong> Et magic link er et engangslink sendt til brugerens mail. Det logger brugeren ind uden adgangskode. Adgangskodelogin er fortsat muligt.</div>"},{"id":"candidate-g-current-reference-gate-4-0-263","chapter":"54","title":"Historisk 4.0.263: global Candidate G-referencegate","summary":"4.0.263 bevarer den rettede tre-timers transport og lader ikke et senere prognosehul slå en sund aktuel opvarmning fra.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> 4.0.263 brugte Candidate G med 20 % jagtbarhed, 50 % transport og 30 % mobilisering og vurderede en fælles aktuel reference pr. zone.</div><p>Transporthukommelsen accepterede verificerede strømbeviser med op til tre timers afstand. Et senere prognosehul måtte ikke slå en sund aktuel tilstand fra.</p><div class=\"callout\"><strong>Erstattet gate:</strong> 4.0.263 skiftede hele datasættet til 25/40/35 ved et aktuelt hul. DEC-0072 har fjernet den globale modelomskiftning. Et hul gør nu kun den konkrete zone, søgemåde og tid utilgængelig, mens andre Candidate G-scorer fortsætter.</div><p>Ingen geometri, land-/vandpunkter, bund-, dybde-, adgangs- eller sikkerhedsregler ændres, og rå strømvektorer, koordinater og private payloads offentliggøres ikke.</p>"},{"id":"ravscore-candidate-g-bounded-transport-memory-2026-08-23","chapter":"18B","title":"Historisk før aktivering: fast 48-timers transporthukommelse","summary":"4.0.260 indførte hukommelsen score-neutralt; DEC-0060 aktiverer den samme mekanik under pre-public opvarmning.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Candidate G genafspiller et fast, rullende vindue med de seneste 48 timers sammenhængende og verificerede strøm. En gammel maskinstart kan derfor ikke påvirke resultatet, når vinduet er komplet.</div><p>Vinduet begynder ved en fast rand på 0. Det betyder kun, at RavRadar ikke antager dokumenteret indtransport før vinduet; det er ikke bevis for fralandsstrøm. Fuld pålandsstrøm bygger fortsat 10 point pr. effektiv time, fuld fralandsstrøm trækker 8 point pr. effektiv time, og 13 timers fuld fralandsstrøm udtømmer transporten.</p><p>Tilstanden gemmer kun tidspunkt og afledt kystnormal strømstyrke. Manglende eller ikke-verificeret strøm er et hul, ikke neutral strøm. Candidate G kan beregnes foreløbigt med ærlig coverage-status.</p><p>Historisk genafspilning viser samme slutresultat uanset tænkt start 0, 50 eller 100 for alle komplette vinduer. Der kræves derfor ikke en ny 48-timers realtidsudviklingstest.</p><div class=\"callout\"><strong>Historisk aktiveringsstatus:</strong> Dette afsnit blev skrevet ved den score-neutrale 4.0.260-indførelse. DEC-0060/4.0.261 gjorde siden Candidate G gældende under pre-public opvarmning. 25/40/35 var derefter rollback, men DEC-0072 har fjernet den fra den offentlige runtime. Geometri, land-/vandpunkter, private rådata og sikkerhedsregler er fortsat uændrede.</div>"},{"id":"candidate-g-profile-switch-4-0-260","chapter":"54","title":"Historisk 4.0.260: sikker omskifter og præcis rollback","summary":"Historisk revisionsspor: 4.0.260 valgte fortsat 25/40/35; den mekanisme er erstattet, og Candidate G 20/50/30 er nu eneste offentlige profil.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> 4.0.260 byggede og testede en omskifter, mens 25/40/35 endnu var den valgte profil. DEC-0060/4.0.261 valgte senere Candidate G.</div><p>Den daværende omskifter kunne vælge hele datasættets legacyrollback. DEC-0072 har erstattet denne mekanisme: Candidate G er nu eneste offentlige profil, og lokale datagab lukkes uden erstatningsscore.</p><p>Nattens historiske kontrol dokumenterede seks timers videreført tilstand i alle 673 kystdele uden nulstilling eller regnefejl. Det var praktisk evidens, ikke et 48-timersbevis.</p><div class=\"callout\"><strong>Aktuel status:</strong> 25/40/35 kan ikke længere vælges offentligt. Sikkerhed, bund, dybde, render, revler, adgang, privat cache, geometri og land-/vandpunkter indgår fortsat ikke.</div>"},{"id":"ravscore-candidate-g-central-state-4-0-259","chapter":"18B","title":"Historisk 4.0.259: central tilstand og landsdækkende shadow","summary":"I 4.0.259 blev Candidate G beregnet centralt og dataminimeret som forberedelse; den blev aktiv i 4.0.261 og bruger nu 20/50/30.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> I 4.0.259 førte RavRadar Candidate G''s dataminimerede transport- og mobiliseringshukommelse videre for alle 673 kystdele, mens den daværende offentlige score stadig var 25/40/35. Candidate G blev aktiv i 4.0.261 og bruger nu 20/50/30.</div><p>Den oprindelige 4.0.259-tilstand gemte transportpotentiale og effektive udtransporttimer. DEC-0059 erstattede transportdelen med et fast 48-timers vindue af tidspunkt og afledt kystnormal strømstyrke. Mobiliseringspotentialet fortsatte uændret. Rå U/V, vind, bølgehøjde, bølgeperiode, koordinater og private replaydata indgår ikke. Samme-time-rekørsel tæller ikke dobbelt; ændret model, punkt eller kystretning nulstiller fail-closed.</p><p>I 4.0.259 blev Candidate G beregnet med 20/50/30 i et adskilt diagnostic-only-felt. DEC-0060–0062 gjorde Candidate G aktiv og bevarede dengang 25/40/35 som fail-closed rollback. DEC-0072 har siden fjernet det offentlige modelskift.</p><p>Den manuelle landskontrol læser den samme offentlige Candidate G-runtime som produktet og kræver 210 zoner, 673 dele og 1.346 rekonstruerbare modeevalueringer. Den tidligere 243/673 native-only-prøve bevares som historisk forskning, ikke som almindelig dækningsmåling.</p><div class=\"callout\"><strong>Aktuel status:</strong> Et komplet rullende 48-timersvindue gør transporten uafhængig af maskinstart. Candidate G er eneste offentlige profil med 20/50/30; lokale huller giver ingen erstatningsscore.</div>"},{"id":"ravscore-current-led-transport-memory-2026-08-22","chapter":"18B","title":"Historisk Candidate G: strømstyret transporthukommelse","summary":"Candidate G lod strømmen bygge og nedbryde transportpotentialet i et fast 48-timersvindue; afsnittet er bevaret som revisionsspor.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> Candidate G lod verificeret strøm mod kysten bygge transportpotentiale og kraftig strøm væk fra kysten reducere det straks. Den integrerede kandidat genbruger de stærke dele, men har sin egen tids-, sidste-mile- og statekontrakt i kapitel 18.</div><p>Fuld indgående strøm byggede 10 point pr. effektiv time mod 100. Fuld udgående strøm trak 8 point pr. effektiv time: 100, 92, 84, 76, 68, 60, 52, 44, 36, 28, 20, 12, 4 og 0 fra 13 timer. Svagere strøm skaleredes forholdsmæssigt.</p><p>Efter ejerreview blev 0,03 m/s valgt som dødzone og 0,15 m/s som fuld kystnormal styrke. Ved 0,09 m/s talte strømmen halvt, så opbygning tog cirka 20 timer og udtømning fra 100 cirka 26 timer. Profilen var en faglig produktprior, ikke en fundkalibreret naturgrænse.</p><p>Neutral strøm ændrede ikke potentialet. Manglende eller ikke-verificeret strøm var et hul og måtte ikke foregives at være neutral. Candidate G genafspillede de seneste 48 timers sammenhængende afledte strøm fra en fast rand i stedet for at bruge et gammelt gemt transportresultat som ny start.</p><p>Bølger og hændelsestiming justerede dengang leveringen inden for 0,85–1,00, når strømmen allerede havde skabt potentiale. Candidate G brugte 20/50/30 og den vindstyrede waders-jagtbarhed fra DEC-0054.</p><div class=\"callout\"><strong>Historisk driftsstatus:</strong> Candidate G var eneste offentlige model frem til det samlede cutover. Efter cutover er den migrationskilde samt internt offline-/rollback-orakel, ikke offentlig fallback.</div>"},{"id":"ravscore-candidate-g-owner-review-2026-08-22","chapter":"18B","title":"Historisk Candidate G: vindstyret waders-jagtbarhed","summary":"Candidate G brugte vind som hovedsignal for waders og WAM-bølger som et blødt fradrag; afsnittet er bevaret som revisionsspor.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> Dette afsnit dokumenterer Candidate G''s waders-kontrakt, efter at den gamle 50/50-historik blev erstattet af strømstyret transport og bølgeenergistyret mobilisering i DEC-0055 og DEC-0056. Den integrerede kandidat genbruger de fagligt stærke dele.</div><p>Candidate G brugte den ejerbesluttede vægtning 20/50/30. Waders-vinddelen gav 100 til og med 6 m/s og faldt gennem 7/80, 8/60, 10/35, 13/10 og 15/0. WAM-bølger kunne kun reducere vindscoren med 20 procent af et negativt gab, højst 20 point; de kunne ikke hæve jagtbarheden eller alene give et hårdt stop.</p><p>Den samlede waders-score kunne aldrig overstige jagtbarheden. Strandscoren blev ikke ændret af waders-reglen og havde intet jagtbarhedsloft. Modellen beskrev søgeeffektivitet, ikke sikkerhed, og bund, dybde, render, revler, adgang og automatisk stedegnethed indgik ikke.</p><p>Det private replay havde 1.460 evalueringer: 730 uændrede strandscorer, ingen waders-score over jagtbarheden, gennemsnitligt bølgefradrag 4,002 point og alle seks tilfælde ved mindst 15 m/s på 0. Det kontrollerede mekanikken, men var ikke fundkalibrering.</p><div class=\"callout\"><strong>Historisk driftsstatus:</strong> Candidate G var aktiv med 20/50/30 og eneste offentlige scoremodel. Efter den integrerede models cutover bevares kontrakten som migrations- og rollbackreference, ikke som samtidig offentlig model.</div>"},{"id":"ravscore-candidate-g-weight-explanation-4-0-257","chapter":"18B","title":"Historisk Candidate G-spor: tidligere vægtanalyse","summary":"Dette 20/45/35-spor er erstattet af DEC-0054 og bevares kun som revisionsspor; den aktive model er nu 20/50/30.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> 20/45/35 blev erstattet af ejerens 20/50/30. Den aktive og eneste offentlige model er nu Candidate G 20/50/30. 25/40/35 var senere global rollback, men DEC-0072 har fjernet den offentligt.</div><p>I de samme 1.460 evalueringer adskiller yderpunkterne sig 4,947 point i gennemsnit og 282 scorebånd. Forskellen er større for strand end for waders, fordi det synlige waders-loft med vilje begrænser scoren, når vind og bølger gør søgemetoden mindre effektiv.</p><p>Alle tre historiske vægte består de faste proceskontrakter. Scenarierne kan afvise modsigelser, men de kan ikke vælge en statistisk rigtig vægt uden komplette ture med fund og reelle nul-fund.</p><p>Kandidatens maskinlæsbare forklaring viser eksakte komponenter, vægte og bidrag, pilen som lokal strøm nu, historikken som forløbet før nu, den milde fysiske begrænsning og et eventuelt synligt waders-loft.</p><p>Den historiske shadow scorede 243 af 673 dele under en snæver native-DKSS-testkontrakt. Det var ikke bevis for 430 huller i den almindelige vejrproduktion. Aktuel produktion har 673/673 dokumenterede strømidentiteter via DMI, Copernicus eller godkendt proxy.</p><div class=\"callout\"><strong>Aktuel status:</strong> Candidate G er aktiv med 20/50/30. Bund, dybde, render, adgang, geometri og land-/vandpunkter indgår ikke.</div>"},{"id":"ravscore-candidate-g-product-contract-4-0-254","chapter":"18B","title":"Historisk Candidate G-spor: første waders-loft","summary":"18 m/s-kurven og den mere selvstændige bølgekobling er erstattet af DEC-0054 og bevares kun som reference.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> Den score-neutrale variant bevarede alle strandscorer og indførte et wadersloft. Den daværende offentlige 25/40/35-score blev ikke ændret; Candidate G blev senere aktiv med 20/50/30.</div><p>På referencevarianten uden direkte vind havde 219 af 730 waders-evalueringer jagtbarhed under 35. Syv havde samtidig mindst 55 point, og det kanoniske højenergiforløb havde jagtbarhed 0 og score 79. Varianten gav 0 i dette waders-forløb, mens den tilsvarende strandscore fortsat var 84.</p><p>Den historiske vinddel nåede 0 ved 18 m/s. Den blev erstattet af DEC-0054, som når 0 ved 15 m/s og bruger bølger som et blødt fradrag. Bund, dybde, render, vadebredde og adgang indgår ikke.</p><p>Replayet ændrede nul af 730 strandscorer, og ingen waders-score oversteg jagtbarheden. Waders-gennemsnittet faldt fra 35,465 til 27,351 i de udvalgte hændelser.</p><p>Pilen viser fortsat den aktuelle lokale strøm. Historikken beskriver forløbet før nu og forklares særskilt på samme kystdel, tidspunkt og jagtform.</p><div class=\"callout\"><strong>Aktuel status:</strong> Candidate G er aktiv med 20/50/30 og 15 m/s-kurven. Geometri, land-/vandpunkter og datakilder blev ikke ændret af dette historiske spor.</div>"},{"id":"ravscore-candidate-g-decision-basis-2026-08-22","chapter":"18B","title":"Historisk Candidate G-spor: første historikmodel","summary":"Den første 24/48-model er erstattet af DEC-0054–0056 og bevares som revisionsspor; den aktive model er nu 20/50/30.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> Dette analyseværktøj viste, at historik ikke må skabe transport ved nul kapacitet. Den aktive Candidate G bruger nu strømstyret transport og én bølgeenergistyret mobiliseringstilstand.</div><p>Den private kontrol omfattede 1.460 beregninger på 12 historiske hændelser. Hukommelse på 24 timer, en 50/50-blanding og 48 timer gav næsten samme score. Direkte vind gav kun en meget lille selvstændig forskel og overlappede vindens indirekte veje.</p><p>Den historiske nationale shadow kontrollerede 673 dele, men scorede kun de 243, der opfyldte dens snævre native-DKSS-testkontrakt. De 430 øvrige var ikke bevis for manglende almindelig vejrdækning. Aktuel produktion har 673/673 dokumenterede strømidentiteter.</p><p>De efterfølgende ejerbeslutninger løste waders-konflikten, gjorde strømmen til transportled og samlede mobilisering i én bølgeenergitilstand. Modellen er fortsat ikke fundkalibreret, men Candidate G blev offentligt aktiveret i 4.0.261.</p><div class=\"callout\"><strong>Aktuel status:</strong> Den aktive score bruger 20 % søgeforhold, 50 % transport og 30 % rav i bevægelse. Dette afsnit beskriver kun den historiske modeludvikling.</div><p>RavScore er ikke sikkerhedsrådgivning. Ingen geometri, land-/vandpunkter, DMI-kilder eller pile blev ændret af den historiske analyse.</p>"},{"id":"national-ranking-opportunity-correction-4-0-252","chapter":"18A","title":"Mere fair placering mellem store og små zoner","summary":"Landslisterne tager højde for, at mange forskelligt vendte kystdele ellers giver en zone flere chancer for at vinde.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Højeste viste områdescore står øverst i både Bedste områder og 5-dages RavRadar.</div><p>Områdescoren beskytter mod, at et område med mange forskelligt vendte kyststrækninger får flere lodder i lotteriet. Den tager derfor både bedste kyststræknings RavScore og støtte fra flere strækninger med. Det viste tal er den afrundede score, listen faktisk sorterer efter. Når området åbnes, ser brugeren fortsat den bedste kyststræknings almindelige RavScore.</p><div class=\"callout\"><strong>Det ændres ikke:</strong> Lokale RavScore-tal, delscorer, farver, pile, vejrdata og forklaringer er uændrede. Ingen land- eller vandpunkter flyttes.</div>"},{"id":"active-runtime-ravscore-shadow-4-0-250","title":"Historisk 4.0.250: privat RavScore-sammenligning på den aktive kyst","summary":"Dette historiske værktøj sammenlignede gamle regler og kandidater før Candidate G blev aktiv.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> Værktøjet sammenlignede den daværende 25/40/35-score og kandidaterne A, B og C på den kyst, brugerne så.</div><p>Det manuelle job læste de aktive land- og vandpunkter og den private DMI-kæde uden at flytte punkter, skrive til administrationen, deploye eller aktivere en kandidat. Resultatet indgik i analysen, som senere førte til Candidate G.</p><div class=\"callout\"><strong>Aktuel status:</strong> Candidate G 20/50/30 er nu eneste offentlige scoremodel; 25/40/35 bruges kun som historisk sammenligning.</div><h3>Samme DMI-model skal hænge sammen</h3><p>Kontrollen fandt, at komponenter fra forskellige DKSS-modelområder ikke må samles til en falsk komplet serie. En bølge- eller DKSS-familie tæller kun som komplet, når alle komponenter kommer fra samme DMI-collection, og strømmens U og V deler fysisk gitterpunkt.</p><div class=\"callout\"><strong>Fail-closed:</strong> Blandede collections bliver deldækning eller blokering og kan ikke påvirke state eller score.</div>"},{"id":"ravscore-candidate-comparison-4-0-248","chapter":"97","title":"Historisk 4.0.248: RavScore-regler blev sammenlignet automatisk","summary":"Det read-only værktøj udvalgte forskelle mellem den daværende model og de tidlige kandidater.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> Værktøjet sammenlignede 40/35/25, den daværende 25/40/35-model og kandidaterne A, B og C uden at ændre produktionen.</div><p>A afprøvede glatte kurver og hændelseshukommelse, B tilføjede levering og fastholdelse, og C tilføjede en mild begrænsning ved et svagt fysisk led. Rapporten fremhævede forskelle som godt søgevejr uden transport og mobilisering uden levering.</p><div class=\"callout\"><strong>Aktuel status:</strong> Analysen er historik. Candidate G 20/50/30 er eneste offentlige scoremodel, mens 25/40/35 kun bruges til historisk sammenligning. En fremtidig ændring kræver stadig ny beslutning og fuld validering.</div>"},{"id":"cost-aware-validation-4-0-247","chapter":"96","title":"Vi tester det rigtige på det rigtige tidspunkt","summary":"Uændret kildekode testes ikke igen ved hver planlagt vejropdatering, mens hvert nyt produktionsdatasæt stadig får den fulde kontrol.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar sparer gentagne kontroller, men ikke de kontroller som beskytter brugerne mod forkerte friske data.</div><p>Under udvikling køres målrettede tests. En Pull Request skal bestå den fulde kildekodegate på præcis den commit, som ønskes merged. Push og manuelle produktionsbyg kontrollerer også kildekoden før de dyre datatrin. En planlagt vejropdatering på samme allerede kontrollerede kode gentager ikke dette trin.</p><p>Hvert nyt produktionsdatasæt skal fortsat bestå fuld validering efter frisk DMI, eventuelt målrettet Copernicus, scorebygning og proveniens. Releasegaten skal være grøn, før artifact, Supabase og Pages kan fortsætte.</p><p>Den store browserkontrol af 210 zoner og 673 kystdele køres ugentligt eller efter ændringer i brugerflade, score eller offentlig datakontrakt. Mindre ændringer får målrettet kontrol.</p><div class=\"callout\"><strong>Ingen genvej ved fejl:</strong> En kendt fejl eller reel usikkerhed udløser altid den ekstra kontrol, som er nødvendig. DMI-first, 673/673, RavScore, geometri og land-/vandpunkter er uændrede.</div>"},{"id":"locked-hour-history-browser-proof-4-0-238","chapter":"95","title":"Låst time bevares i fallback, historik og browserbevis","summary":"Fallback, verificeret historik og den afsluttende browserkontrol bindes til samme godkendte produktionstime og version.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En produktion må ikke miste sin godkendte starttime, blot fordi bygningen passerer et UTC-timeskifte.</div><p>4.0.238 lod Open-Meteo hente netop nok historiske timer til, at den låste <code>productionReferenceAt</code> fandtes i svaret. DMI forblev førstevalg, og fallback måtte kun udfylde reelle huller eller en manglende hale.</p><p>Verificeret strømhistorik blev bundet til samme reference. De 198 zoner med et fælles DMI-U/V-par kunne vokse naturligt, mens de tolv zoner uden et fælles marint gitterpunkt forblev eksplicit manglende. Fortid, nulværdier og nabotimer blev ikke opfundet.</p><p>Den versionsbundne browseraudit gennemgår begge jagtformer i 210 zoner, 420 aktuelle paneler, 2.100 femdøgnsvalg og 673 kystdele.</p><h3>Senere historiske udvidelser</h3><p>Komplette ture fra 4.0.243 fastholder prognosen ved start og gemmer zone, kystdel, tid, jagtform, grundighed samt fund eller intet fund uden GPS, rute eller præcis position. Den private kandidat-shadow fra 4.0.249 sammenlignede tidlige kandidater med den daværende 25/40/35-model.</p><div class=\"callout\"><strong>Aktuel status:</strong> Candidate G 20/50/30 er nu aktiv. Frisk central produktion og efterfølgende browseraudit er fortsat nødvendige releasebeviser.</div>"},{"id":"targeted-copernicus-after-dmi-4-0-246","chapter":"95","title":"Copernicus henter kun en verificeret DMI-strømtimes huller","summary":"DMI er fortsat førstevalg; ved nul eksakt strømdækning vælges kun en nærliggende verificeret DMI-time, og resultatet skal stadig være 673/673.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar henter ikke normal Copernicus-dækning for hele kysten. Efter frisk DMI finder systemet den relevante verificerede DMI-strømtime og henter kun de konkrete lokale huller.</div><p>4.0.245-produktionen viste, at en time kan indeholde vind eller andre DMI-felter uden lokal strøm. Den ønskede 08:00-time havde 0/673 lokale strømme, mens 09:00 havde 622/673. Målbyggeren stoppede derfor korrekt i stedet for at bestille hele kysten hos Copernicus.</p><p>4.0.246 må kun ved nul eksakt strømdækning vælge den højest dækkede og derefter nærmeste verificerede DMI-strømtime inden for tre timer. Den valgte time bruges samlet til målregister, Copernicus, livefletning, vejr, score og forklaring. Findes ingen nærliggende DMI-time, stopper produktionen.</p><p>Efter supplementet kræver den fulde gate fortsat dokumenteret strøm til alle 673 kystdele. Mangler blot én tilladt post med korrekt time, celle, lag og afstand, frigives intet. En landsdækkende Copernicus-kørsel findes kun som et særskilt manuelt forskningsvalg.</p><div class=\"callout\"><strong>Uændret faglighed:</strong> DMI-først, regionale proxyer, RavScore, pile, geometri og alle land-/vandpunkter er uændrede. Credentials og rå U/V forbliver private.</div>"},{"id":"complete-local-current-reference-4-0-237","chapter":"94","title":"Aktuel lokal score og pile deler én komplet zonetime","summary":"Hver zone vælger sin nærmeste komplette fælles time, så del, score, vejr, tekst, debug og pile ikke blandes på tværs af tider.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Verificeret strøm til 673/673 dele er ikke det samme som, at alle dele i en lokal sammenligning automatisk står på samme klokkeslæt.</div><p>Den tidligere udvælger fandt den nærmeste gyldige strømrecord for hver del. Når DMI og en tilladt supplerende kilde havde forskellige nærmeste tider, kunne delene i samme zone derfor stå på hver sin time. Zonepanelet valgte bagefter den række, der lå nærmest byggetiden, også når den var ufuldstændig, og viste dermed unødigt hovedzonefallback.</p><p>Fra 4.0.237 vælger RavRadar den nærmeste komplette fælles række pr. zone. Begge jagtformer og alle zonens forventede kystdele skal kunne beregnes ved samme eksakte tidspunkt. Tiden gemmes som <code>currentReferenceAt</code> og bruges til vinder, RavScore, vejr, forklaring, debug og lokale pile. En pil må kun bruge den dokumenterede modelcelle fra præcis denne time; en nabotimes celle lånes ikke.</p><p>Kontrollen før frigivelsen fandt en komplet fælles time i alle 210 zoner. Den hidtidige runtime havde 31 af 673 dele på en anden nær-time. I det produktionsverificerede datasæt <code>rr-20260819143933-210</code> står alle 673 dele nu på deres zones valgte fælles time: 196 zoner bruger 15:00Z og 14 bruger 14:00Z. Commit <code>9c971bc1</code> og den fulde centrale kørsel <code>#32264833170</code> bestod frisk data, validering, releasegate, Supabase og Pages.</p><div class=\"callout\"><strong>Uændret faglighed:</strong> Land-/vandpunkter, U/V, kildeorden, afstandsgrænser, RavScoreformel, rollback og kravet om præcis 673/673 er uændrede. Reglen gælder pr. zone og kræver ikke én national klokktime for hele landet.</div>"},{"id":"production-reference-hour-lock-4-0-236","chapter":"93","title":"En planlagt produktion beholder sin godkendte UTC-time","summary":"Readiness, Copernicus-fletning og vejrbygning bruger samme eksakte time, også når jobbet krydser et timeskifte.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En kørsel må ikke godkende én komplet strømtime og senere skifte til den næste, blot fordi bygningen passerer et UTC-timeskifte.</div><p>En naturlig schedule-kørsel godkendte den komplette time kl. 11 lige før kl. 12. Den gamle vejrbygning kiggede derefter på væguret, valgte kl. 12 og manglede de 43 Copernicus-dele, som endnu ikke var indsamlet for den nye time. Den uændrede sikkerhedsgate stoppede korrekt ved 630/673, og intet blev frigivet til Supabase eller Pages.</p><p>Fra 4.0.236 følger readiness-gatens eksakte godkendte time med gennem hele det planlagte build. Live-pilot, RavScore, forklaringer og runtime bygges derfor på én sammenhængende referencetime. Push og bevidst manuel release uden en planlagt readiness-time bruger fortsat den aktuelle tid.</p><p>Datasættets <code>generatedAt</code>, ID og sundhedstidsstempel bruger fortsat den virkelige byggetid. Den faglige lås gemmes særskilt som <code>productionReferenceAt</code>, så kvarterskørsler ikke får samme identitet eller fremstår kunstigt gamle.</p><p>Den normale centrale kørsel <code>#32253251841</code> valgte 12:00 i readiness, beholdt 12:00 gennem hele produktionen og bestod præcis 673/673, fuld validering, releasegate, Supabase og Pages. Live version 4.0.236 viser 210 zoner og 673 verificerede dele med virkelig byggetid 12:36 og særskilt <code>productionReferenceAt=12:00</code>.</p><div class=\"callout\"><strong>Uændret sikkerhed:</strong> Friskhed, land-/vandpunkter, kystgeometri, U/V, pile, scoreformel, kildeorden og afstandsgrænser er uændrede. En release kræver stadig præcis 673/673 og alle fulde gates.</div>"},{"id":"one-local-display-context-4-0-235","chapter":"92","title":"Zonepanelet viser én sammenhængende lokal virkelighed","summary":"Delnavn, tid, score, forklaring, debug og vejr kommer fra den samme lokale vinderpost.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Når RavRadar udpeger en kystdel som bedst, viser hele panelet nu data fra netop den del og det samme klokkeslæt.</div><p>Tidligere kunne den lokale RavScore og debug være korrekte, mens de synlige vejrmetrikker stadig kom fra hovedzonen. Femdøgnsfanerne kunne desuden vælge et andet tidspunkt end den nationale prognose. 4.0.235 samler begge visninger om den samme lokale dagsvinder.</p><p>Vind, bølger, vandstand, strøm, vandtemperatur, trend, score og forklaring følger nu den viste del og tid. Mangler en komplet fælles lokal post, vises en tydeligt mærket hovedzonefallback, hvor score, tekst, debug og vejr samlet kommer fra hovedzonen. Hovedzonedata lånes aldrig skjult ind under en lokal vinder.</p><p>Den landsdækkende regression dækker 210 zoner, 673 kystdele, begge jagtformer og 2.100 femdøgnsvisninger. <code>#32249770288</code> bestod derefter frisk 673/673, fuld validering, releasegate, Supabase og Pages. Live datasæt <code>rr-20260819115558-210</code> er hash- og runtimekontrolleret for 420 aktuelle og 2.100 femdøgnsvisninger; alle bruger enten en komplet lokal kontekst eller en eksplicit samlet hovedzonefallback.</p><p>Den faktiske automatiserede DOM-/kliktest forsøges først med Codex-browserpluginet og målrettet diagnostik. Hvis der ikke findes en konkret reparationsvej, bruges den ejer-godkendte Chromium/Playwright-fallback. Rettelsen flytter ingen land-/vandpunkter og ændrer ikke U/V, pile, kildeorden, RavScore eller 673/673-gaten.</p>"},{"id":"local-part-direction-isolation-4-0-233","chapter":"91","title":"Hver lokal kystdel vurderes mod sin egen kyst","summary":"En lokal score kan ikke længere vælge moderzonens eller en nabodels kystretning.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Strømpilen viser vandets faktiske bevægelse og peger derfor ikke altid mod land. Det er RavScore, som skal sammenholde bevægelsen med netop den kystdel, brugeren ser.</div><p>Ved Havsande viste pilen en nordgående strøm korrekt, men den lokale score for <strong>Havsande – nordkyst</strong> kunne vælge det ældre moderzoneanker <strong>Syd for fyret</strong>. Derfor kunne delnavn, historik, debug og transporttekst modsige hinanden.</p><p>Fra 4.0.233 får hver af de 673 lokale kystdele præcis ét aktivt scoreanker. Det består af delens eget blå vandpunkt, grønne landpunkt, lokale navn og retningen fra vand mod land. Moderzonens eller en nabodels retningsankre kan ikke længere arves ind i lokal score, state/historik, debug eller forklaring.</p><p>Rettelsen ændrer ikke strømvektoren, pilens retning eller placering, modelcellen, kildeordenen, dybdelaget eller 673/673-kravet. Den sikrer, at de allerede godkendte lokale punkter er den samme geografiske sandhed gennem hele beregningen.</p>"},{"id":"controlled-live-current-and-rollback-2026-08-18","chapter":"90","title":"Copernicus-strøm, nye pile og sikker rollback går live","summary":"Gyldige U/V-data må vises på udviklingssiden; kun credentials er hemmelige, og normal drift kræver stadig 673/673.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar bruger DMI først, men kan nu bruge de verificerede Copernicus- og Limfjordsproxyposter direkte i RavScore og de nye strømpile på den ikke-offentlige udviklingsside.</div><p>Kildeordenen er lokal DMI inden for 5 km, Baltic NEMO inden for 5 km, AMM15 inden for 5 km og til sidst kun de otte ejer-godkendte <code>dkss_lf</code>-proxyer inden for 15 km. Supplementet må kun udfylde en manglende strøm ved præcis samme tidspunkt. U og V skal komme fra samme celle og lag, og der interpoleres ikke mellem Copernicus-/proxytider, celler eller lag.</p><p>Den validerede syvdøgnshistorik publiceres som <code>data/live/current-pilot-history.json</code> med U/V, tidspunkt, modelcelle, lag, afstand og kilde. Den hentes ikke ved normal sidestart og gør derfor ikke kortets startpakke tung. Copernicus-loginoplysninger findes kun i det autentificerede indsamlingsjob og kommer aldrig i livefilen, supportpakken eller loggen.</p><p>RavScore, den viste tid og pilens placering bruger samme valgte U/V-post. En Copernicus- eller regionalproxypil står på den faktiske modelcelle. Administratorens blå vandpunkt, en anden times celle eller en for fjern celle kan ikke fremstilles som verificeret pil.</p><p>Normaltilstanden <code>controlled-live</code> kræver præcis 673/673. Hvis supplementet viser en reel fejl, kan den versionsstyrede <code>dmi-only-rollback</code> slå Copernicus og regionalproxy ud af score og pile igen. Vind, bølger, vandstand og andre friske prognoser fortsætter, mens de berørte strømdele står ærligt som <code>missing</code>; rollback må ikke foregive fuld strømdækning.</p><p><strong>Produktionsbevis:</strong> Kørsel <code>#32158041877</code> bestod med 622 lokale DMI-dele, 43 Copernicus-dele og otte regionale proxyer, altså præcis 673/673. Fuld validering, releasegate, Supabase og Pages var grønne, og det deployede datasæt er hashverificeret på den aktive side.</p><div class=\"callout\"><strong>Live eftermåling:</strong> Det naturlige syvdøgnsbevis gennemføres nu på den fungerende udviklingsside. Kapitel 87–89 beskriver den tidligere private indsamlingsforfase og må ikke læses som et fortsat forbud mod den credentialfri liveprojektion.</div>"},{"id":"copernicus-target-geometry-identity-2026-08-18","chapter":"89","title":"En strømtime hører til de vandpunkter, den blev hentet til","summary":"Flyttes et centralt vandpunkt, kan den samme UTC-time ikke genbruges fra den gamle punktbestand.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Det er ikke nok, at Copernicus-cachen indeholder den rigtige klokktime. Den skal også være hentet til præcis de vandpunkter, som er centralt godkendt nu.</div><p>Efter den centrale hydrering laver piloten et digitalt SHA-256-fingeraftryk af alle kystdels-ID''er, parentzoner og vandpunkter. Hver færdig indsamling gemmer fingeraftrykket sammen med tidspunktet og det forventede antal råposter. En download springes kun over, når både time, fingeraftryk og recordantal matcher.</p><p>Hvis ejeren har flyttet blot ét vandpunkt, hvis en ældre cache mangler indsamlingsmanifestet, eller hvis recordantallet er ufuldstændigt, hentes timen igen privat. Alle gamle poster for netop den time erstattes samlet, og ældre historik for den flyttede eller slettede del fjernes. Uændrede deles historik kan bevares, så data fra gammel og ny geometri aldrig blandes.</p><div class=\"callout\"><strong>Fortsat privat:</strong> Fingeraftrykket indeholder ingen rå strømvektorer eller loginoplysninger. Ændringen aktiverer hverken Copernicus, regionalproxy, pile eller RavScore og ændrer ikke kravet om 673/673.</div>"},{"id":"github-owned-production-schedule-4-0-234","chapter":"88","title":"GitHub ejer 15-minuttersproduktionen og venter på den nye strømtime","summary":"Produktionen kører forskudt fra timeskiftet og bygger intet artifact, før den eksakte Copernicus-time findes.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar bruger fra 4.0.234 GitHubs egen 15-minuttersplan ved minut 14, 29, 44 og 59. Den private Copernicus-pilot bestilles ved minut 6, så den nye UTC-time normalt er klar før første produktionskørsel.</div><p>Før det tunge produktionsjob starter, gendanner en lille gate den private Copernicus-cache og kontrollerer kun sikre metadata. Hvis den eksakte aktuelle time mangler, afsluttes den planlagte kørsel uden vejrbygning, Supabase eller Pages. Det eksisterende private heartbeat bestiller piloten, og næste 15-minutterskørsel prøver igen. Fra 4.0.236 følger den time, som readiness-gaten faktisk godkendte, med gennem hele bygningen, så et job heller ikke kan skifte time undervejs.</p><p>Manuel og push-udløst release er fortsat fail-closed og kan ikke springe 673/673, fuld validering eller releasegate over. Cachekontrollen accepterer kun kendt schema, præcis 168 timers retention samt <code>scoreImpact=false</code> og <code>publicRuntime=false</code>; den logger aldrig rå U/V eller credentials.</p><div class=\"callout\"><strong>Overdragelse afsluttet:</strong> Ejeren har slettet cron-job.org-jobbene. Efterfølgende naturlig GitHub-produktion, pilot og cachebevaring er verificeret grønne, så GitHub Actions er eneste normale scheduler. Kildeorden, land-/vandpunkter, score, pile og dækningskrav ændres ikke.</div>"},{"id":"supplementary-current-private-pilot-2026-08-18","chapter":"87","title":"Den private forfase til supplerende strøm","summary":"Historisk indsamlingsfase før ejerens senere godkendelse af kontrolleret live-drift i kapitel 90.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar undersøger flere officielle 3D-strømkilder, men den offentlige app bruger fortsat kun den verificerede DMI-kæde.</div><p>Den private pilot prøver først Baltic NEMO og derefter AMM15, når DMI mangler lokalt. U og V skal komme fra samme produkt, tidspunkt, gittercelle og dybdelag. RavRadar vælger nærmeste gyldige vandkolonne før dybeste fælles lag, interpolerer ikke og accepterer højst 5 km. Data opbevares højst syv døgn med <code>scoreImpact=false</code> og <code>publicRuntime=false</code>. Første autentificerede timeprøve fandt 39 Baltic- og fire AMM15-par blandt de 51 DMI-huller, svarende til et kombineret potentiale på 665/673. Piloten kører privat hver time for at bevise stabilitet.</p><p>Syvdøgnsgrænsen kontrolleres også i den normale releasevalidering. Prøven på selve 168-timersgrænsen bevares, mens ældre, fremtidige eller beskadigede poster fra en gendannet cache fjernes, og identiske prøver samles. En ny prøve uden gyldigt punkt, modelcelle, afstand og samme-tid/celle/lag-U/V stopper den private pilot. Det naturlige fulde syvdøgnsforløb skal stadig bevises i drift.</p><p>Den store DMI-cache kan fylde GitHubs fælles cachekvote. Et lille privat job er planlagt til at gendanne Copernicus-cachen hvert tiende minut, men GitHub leverede ikke de første automatiske events hurtigt nok. Derfor gendanner selve vejrproduktionen nu også den eksisterende private Copernicus-cache lige før de store DMI-cacher behandles. Så er den lille cache nyere end en gammel DMI-cache. Central kontrol har bevist, at den overlever en efterfølgende DMI-cache på cirka 2,9 GB og derefter kan udvides fra to til tre timer. Ingen af gendannelserne uploader data, bruger Copernicus-login eller viser strømværdier.</p><p>Otte dokumenterede modelhuller i den vestlige Limfjord har en særskilt ejerallowlist. 4.0.232-kandidaten samler deres faktiske DMI-strøm privat ved hver vejrbygning, men bruger den ikke offentligt. Før opsamlingen skal det centrale vandpunkt stadig matche ejerens godkendelse, delen skal stadig være en Limfjordsdel, kilden skal være <code>dkss_lf</code>, og modelcellen skal ligge højst 15 km væk. Alle øvrige dele beholder 5-km-grænsen.</p><p>Rå U/V ligger kun i den private syvdøgnscache og må ikke lægges i et artifact i det offentlige repository. Supportbeviset må vise navn, samplingpunkt, run, tid, modelcelle, afstand og dybdelag, men ikke strømværdier. En senere aktivering kræver friske fler-kørselsbeviser og alle fulde releasegates; pilen skal da stå på den faktiske modelcelle.</p><p>En ny release kræver strømbevis til alle aktive kystdele, aktuelt 673 af 673. Den tidligere 95 %-grænse er erstattet. Central #32139054129 og #32140865173 beviste, at 622/673 nu stoppes før release og deploy. Mangler blot én del en tilladt kilde med korrekt celle, tid, lag og afstand, stopper releasen uden at opfinde eller låne data.</p><div class=\"callout\"><strong>Ærlig kvalitet:</strong> Regional proxy mærkes som regional, og celler med kun øverste lag mærkes <code>surface-only</code>. Ingen af delene må fremstilles som en lokal bundmåling.</div>"},{"id":"local-current-arrow-score-time-4-0-231","chapter":"86","title":"Den lokale strømpil følger den scoretime, der faktisk vises","summary":"Den lokale score og pilens DMI-celle vælges nu ved præcis samme tidspunkt.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Et strøm-tal fra kl. 12 må ikke vises med en pil, som blev placeret ud fra datatilstanden kl. 06.</div><p>En lokal kystdel kan mangle verificeret strøm omkring byggetiden og først have en gyldig scorepost senere. Tidligere kunne scoren derfor komme fra den senere time, mens pilens sted blev beregnet ved byggetiden og faldt tilbage til det blå administratorvandpunkt.</p><p>Fra 4.0.231 vælger RavRadar først den lokale scorepost, der faktisk vises. Derefter beregnes <code>flowPoints.current</code> ved præcis samme tid og skal matche scorepostens verificerede DMI-celle. Mangler cellen på den viste time, vises ingen lokal DMI-pil; en anden times celle lånes ikke.</p><div class=\"callout\"><strong>Uændret faglighed:</strong> Strømværdi, dybdelag, RavScore, land-/vandpunkter og femkilometergrænsen er uændrede. Den private syvdøgnsopsamling fortsætter score-neutralt til analysen af ydre tilførsel → overgang → lokal bundnær levering.</div>"},{"id":"current-cross-collection-selection-4-0-230","chapter":"85","title":"Strøm vælges selvstændigt på tværs af DMI''s havområder","summary":"Det nærmeste komplette strømpar vælges for hver DMI-tid uden at blive blokeret af vandstand eller temperatur.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Ét modelområde kan være bedst til vandstand, mens et andet har den nærmeste gyldige strøm. De to valg må ikke blandes.</div><p>RavRadar leder for hvert native DMI-tidspunkt på tværs af alle aktive DKSS-modelområder efter den nærmeste eksakte vandkolonne med både strøm-U og strøm-V. Først derefter vælges det dybeste gyldige lag i den samme kolonne. Ved Havknude fandtes et komplet NSBS-strømpar 2,804 km fra vandpunktet, men det gamle fælles havmodelvalg skjulte det bag et IDW-skalarpunkt 5,131 km væk.</p><p>Vandstand, overfladetemperatur og andre skalare marinefelter beholder deres kysttilpassede modelvalg. De kan ikke længere blokere, flytte eller rydde strømmen. Hvis collection, modelkørsel, celle eller lag skifter mellem to native tider, bliver mellemtimen manglende i stedet for at blande to forskellige fysiske strømvektorer.</p><div class=\"callout\"><strong>Uændret sikkerhed:</strong> Afstandsgrænsen er fortsat 5 km, uverificeret strøm giver ingen pil eller scoreinput, administratorens punkter flyttes ikke, og RavScoreformlen er uændret. Den private syvdøgnsopsamling fortsætter score-neutralt til analysen af ydre tilførsel → overgang → lokal bundnær levering.</div>"},{"id":"current-water-column-and-field-research-4-0-229","chapter":"84","title":"Strømmen vælges tæt på kystens vandpunkt og i det bundnære lag","summary":"RavRadar vælger først den nærmeste gyldige DMI-vandkolonne og derefter det dybeste gyldige lag i den samme kolonne.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Et dybt strømfelt langt væk må ikke bestemme pilen eller scoren ved en anden kyst. Stedet vælges før dybden.</div><p>Det blå vandpunkt, som ejeren kan flytte i administrationen, er udgangspunktet. RavRadar finder den nærmeste DMI-celle, hvor både den øst-vestlige og nord-sydlige strømkomponent findes på samme tidspunkt og dybde. Først derefter vælges det dybeste gyldige lag i netop den vandkolonne. Op til 3 km er bedst, 3–5 km kan bruges som reserve, og over 5 km vises strømmen som manglende.</p><p>DMI kan have forskellige dybeste tilgængelige lag på forskellige forecasttidspunkter. Laget vælges derfor for hver native tid. Mellemtimer beregnes kun, når begge native tider har samme lag, vandcelle og modelkørsel; ellers er strømmen manglende mellem tiderne. Pilen står på den viste times egen dokumenterede celle. Centralt flyttede kystdelspunkter bygges før DMI-sampling, og kun cachen for det flyttede punkt nulstilles.</p><p>En DMI-strømpil står på den præcise modelcelle, som leverede strømmen. Samme sted, lag og tidspunkt følger ind i prognosen og det eksisterende lokale scoreinput. Gamle data med en anden betydning fjernes, så de ikke kan overleve efter et flyttet vandpunkt eller en kodeopdatering. Kun verificeret strøm fra DMI-GRIB-kæden må bruges aktivt. ForecastEDR-strøm uden lagbevis, Open-Meteos overfladestrøm og anden fallbackstrøm lukkes ude før historik, score og kort.</p><p>Den private rotation tager 15 kystdele pr. almindelig kørsel, også når modelgenerationen er uændret. Den genbruger først en tidsrelevant DMI-råfil med stabil identitet. Mangler filen efter en gammel eller tømt cache, må højst én fil pr. havmodelområde og tre i alt hentes inden for det eksisterende DMI-budget og gemmes til genbrug. Filen behandles kun mod private forskningspunkter i et tomt arbejdsområde og kan ikke skrive til offentlig zonecache eller score. Ved 15-minutters drift besøges alle 673 dele på cirka 11 timer og 15 minutter, altså mange gange inden for syv døgn.</p><p>Rotationen registrerer desuden koordinat, afstand og lagmetadata til den nærmeste eksakte fælles U/V-kolonne, også når den ligger længere end 5 km væk. De fjerne strømværdier gemmes ikke og kan hverken skabe pil eller score. Den private ejeroversigt skelner nær-tærskel 5–6 km til rent manuelt geometrireview fra modelhul 6–8 km, strukturelt modelhul over 8 km og pipelinehul inden for 5 km. Selv en nær-tærskel-post må kun flyttes, hvis vandpunktet i sig selv er forkert. Intet punkt flyttes automatisk.</p><div class=\"callout\"><strong>Hele transporten undersøges senere:</strong> Rav kan tilføres fra områder længere ude, bevæge sig gennem flere dybdelag og nå kysten med forsinkelse. Derfor samler RavRadar privat i syv døgn ved kysten samt cirka 5 og 15 km søværts. Det ændrer ikke RavScore nu. Den store analyse skal afgøre, om kæden ydre tilførsel → overgang → lokal bundnær levering giver et selvstændigt, målbart signal uden dobbelt-tælling med vind og bølger.</div>"},{"id":"admin-local-coast-angle-advisory-4-0-227","chapter":"83","title":"Bugtede kyster kan godkendes ud fra helhedsindtrykket","summary":"Vinklen mod et kort lokalt kystsegment er vejledende og kan ikke længere låse ejerens godkendelse.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Et lille kysthak må ikke overtrumfe ejerens kontrol af hele den bugtede kyststrækning.</div><p>RavRadar viser fortsat, hvor meget linjen fra det blå havpunkt til det grønne landpunkt afviger fra den nærmeste korte kystlinje. På en bugtet, takket eller fragmenteret kyst kan dette mikrostykke vende anderledes end den repræsentative strækning.</p><p>Fra 4.0.227 er den lokale vinkel kun en advarsel. Den kan ikke deaktivere <strong>Godkend og gem centralt</strong>, når ejeren har kontrolleret hele zonen og sat de tre flueben. Admin forklarer direkte, at ejerens manuelle helhedsvurdering afgør godkendelsen.</p><div class=\"callout\"><strong>Integriteten bevares:</strong> Manglende punkter, urimelig afstand, manglende kryds med egen kyst og punkter på samme side blokerer fortsat. Central readback og DMI-/releasegates er uændrede, og rettelsen flytter ingen eksisterende punkter eller RavScore-værdier.</div>"},{"id":"supabase-runtime-diagnostics-archive-4-0-234","chapter":"82","title":"Den fulde runtime-diagnostik gemmes kompakt og tabsfrit","summary":"Supabase modtager en lille oversigt og et verificerbart gzip-arkiv i stedet for et meget stort ukomprimeret JSON-dokument.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Den beskyttede runtime-diagnostik voksede til cirka 24 MB som fil og kunne ramme Supabases PostgreSQL-timeout <code>57014</code> to gange i samme release.</div><p>Fra 4.0.234 gemmes samme fulde rapport som gzip/base64 under den eksisterende beskyttede dokumentnøgle. De få felter, adminoversigten bruger, ligger fortsat direkte i dokumentet. Den lokale repræsentative rapport faldt fra 4.014.169 til 208.874 byte uden at fjerne zoner, forsøg eller målinger.</p><p>Ved download pakker browseren arkivet ud og kontrollerer først komprimeret størrelse, udpakket størrelse, SHA-256-fingeraftryk, version og genereringstid. Kun hvis alt stemmer, downloades den oprindelige komplette JSON. Ældre ukomprimerede dokumenter kan fortsat hentes.</p><div class=\"callout\"><strong>Fortsat fail-closed:</strong> Den snævre én-gangs genprøvning af eksakt <code>500/57014</code> bevares. Gentagen timeout, korruption, auth- eller netværksfejl stopper fortsat release eller download. Vejrdata, land-/vandpunkter, RavScore og offentlig runtime ændres ikke.</div>"},{"id":"water-level-current-hour-provenance-4-0-225","chapter":"81","title":"Den aktuelle vandstandstime beholder sin modelidentitet","summary":"Routingens kildeindeks starter nu på samme aktuelle klokktime som den offentlige prognose.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En vejrbygning få minutter efter hel time kunne miste modelnavn og modelkørsel på netop den igangværende vandstandstime.</div><p>Fra 4.0.225 bevarer kildeindekset den aktuelle hele UTC-time, mens forecastalder fortsat beregnes fra den faktiske byggetid. De valgte DMI-punkters collection, model-run, native tider og source keys følger derfor også den aktuelle time.</p><p><strong>Produktionskontrol:</strong> #2810 gennemførte hele validerings- og deploykæden. Alle 22.890 routede DMI-vandstandstimer havde fuld kildeidentitet, inklusive 210/210 zoner i den aktuelle time, og det deployede site serverede samme komplette 210-zone-datasæt.</p><div class=\"callout\"><strong>Uændrede tal:</strong> Vandstand, valgte punkter, vægte, continuity, fallback, RavScore og geometri er uændrede.</div>"},{"id":"water-level-routing-provenance-4-0-224","chapter":"80","title":"Vandstand viser den model, der faktisk leverede værdien","summary":"Kildeoplysningen følger nu de valgte DMI-vandstandspunkter gennem hele routingen.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Den beregnede vandstand var rigtig, men modelnavnet kunne stamme fra zonens gamle model i stedet for de valgte vandstandspunkter.</div><p>Fra 4.0.224 følger de faktiske DKSS-modelområder, modelkørslen og kildetiderne med hver routet vandstandstime. Hvis to modelområder vægtes sammen, mærkes kilden som sammensat og begge dele bevares maskinlæsbart.</p><div class=\"callout\"><strong>Uændrede tal:</strong> Vandstand, valgte punkter, vægte, continuity, fallback, RavScore og hav-/landpunkter er uændrede.</div>"},{"id":"supabase-routing-audit-readback-4-0-219","chapter":"79","title":"Mindre Supabase-forbrug uden tab af admin-data","summary":"En maskinrapport, der alligevel genbygges, hentes ikke længere før hver vejrbygning.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar sparer en overflødig central hentning uden at fjerne data fra admin eller vejrberegningen.</div><p>Vandstandsroutingauditten er en maskinrapport, ikke redigerbar runtime-konfiguration. Fra 4.0.219 genbygges den fortsat fra friske data og uploades beskyttet til ejerens adminrapport, men den gamle udgave hentes ikke først. Stationsregister, aktive routingvalg, regler, overrides og kystaktivering hydrerer fortsat centralt.</p><p>En læsende estimator peger på cirka 1,42 GiB mindre pipeline-readback over 30 dage ved 96 kørsler dagligt. Estimatet er ikke Supabase-billing, så den faktiske næste periode følges fortsat.</p>"},{"id":"current-anchor-model-selection-4-0-218","chapter":"78","title":"Et sent strømpar må ikke fjerne strømmen nu","summary":"En anden DMI-havmodel må kun erstatte aktuel strøm, når den selv har et komplet strømpar omkring nu.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Et lidt bedre DMI-punkt flere døgn ude må ikke rydde en sammenhængende strømserie omkring nu.</div><p>RavRadar vælger én havmodel pr. zone. Hvis den valgte model allerede har et fælles U/V-strømpar inden for seks timer af datasættets genereringstid, skal en kandidatmodel selv have et par i samme tidsvindue for at overtage. En zone uden aktuel strøm må stadig repareres af en bedre kandidat.</p><div class=\"callout\"><strong>Ingen ny faglig model:</strong> DMI-kilder, fallback, RavScore og hav-/landpunkter er uændrede, og manglende data forbliver manglende.</div>"},{"id":"verified-current-history-both-windows-4-0-217","chapter":"77","title":"Verificeret strøm i hele tre-døgnsvinduet","summary":"Den aktuelle DMI-verifikation gemmes nu i både 24- og 72-timershistorikken.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar gemte allerede tre døgns rå vejrprøver, men strømverifikationen blev kun skrevet tilbage til det korte vindue og gik derfor tabt ved næste kørsel.</div><p>Den eksakte aktuelle prøve synkroniseres nu til begge vinduer efter den eksisterende strenge kontrol af DMI''s fælles U/V-par, gitterpunkt og kildetider. Ældre uverificerede prøver ændres ikke, og manglende fortid konstrueres ikke.</p><div class=\"callout\"><strong>Uændret score:</strong> RavScore bruger fortsat kun 24-timersvinduet. Den længere historik er score-neutral og skal opbygges naturligt i 72 timer før senere faglig analyse.</div>"},{"id":"fail-closed-temperature-cache-4-0-214","chapter":"75","title":"Gamle umærkede temperaturer fjernes","summary":"En mulig dybdetemperatur må ikke overleve i cachen som havoverfladetemperatur.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Ældre DMI-temperaturer uden sikker lagmærkning fjernes og vises som manglende, indtil DMI har leveret nye data fra havoverfladen.</div><p>DMI-havmodellerne prioriteres på skift, så overfladetemperaturen genopbygges kontrolleret. Vind-, bølge-, strøm- og vandstandshistorik bevares; der indføres ingen ny kilde eller scoreændring.</p>"},{"id":"dmi-sea-surface-temperature-4-0-213","chapter":"74","title":"Vandtemperatur ved havoverfladen","summary":"Kun DMI''s eksplicitte overfladelag bruges som offentlig vandtemperatur.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> DMI leverer temperatur både ved havoverfladen og i mange dybder. RavRadar bruger nu kun det eksplicitte overfladelag, niveau 0, som den viste vandtemperatur.</div><p>Den tidligere skalarkæde skelnede ikke lagene og kunne lade et dybere temperaturfelt overskrive overfladeværdien. Fra 4.0.213 gemmes lagidentiteten sammen med collection, modelkørsel og tidspunkt, og dybere lag afvises som erstatning.</p><p>Produktionskontrollen i 4.0.221 viser eksplicit <code>surface:0</code> i alle 210 hovedzoner og alle 9.159 kontrollerede DMI-temperaturtrin på tværs af IDW, NSBS og Limfjorden. Otte Limfjordszoners sidste fire viste timer er fortsat en separat horisontanalyse, ikke et lagproblem.</p><div class=\"callout\"><strong>Uændret faglig model:</strong> RavScore, mobiliseringsstate, fallbackprioritet og 72-timershistorik er uændrede.</div>"},{"id":"stable-dmi-current-model-selection-4-0-212","chapter":"18","title":"Stabilt valg af DMI-strømmodel","summary":"Vandstand og temperatur må ikke alene skifte havmodel og slette en sammenhængende strømserie.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En zones DMI-havmodel vælges ud fra et gyldigt fælles strømpar. Et lidt nærmere vandstands- eller temperaturpunkt må ikke rydde denne strømserie.</div><p>Fra 4.0.212 følger skalare marinefelter det eksisterende modelvalg uden at ændre valgets afstandsscore. Kun en kandidat, der faktisk leverer et bedre fælles strøm-U/V-par, kan overtage.</p><div class=\"callout\"><strong>Uændret faglig model:</strong> Der tilføjes ingen kilde eller fallback, RavScore ændres ikke, og manglende strøm forbliver manglende.</div>"},{"id":"dmi-marine-selection-retention-4-0-211","chapter":"73","title":"Havmodelvalget bevares mellem kørsler","summary":"Den valgte DMI-havmodel kan ikke længere gå tabt og rydde en bedre strømserie.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar husker nu både strømserien og præcis hvilken DMI-havmodel der blev valgt for zonen.</div><p>4.0.210 fandt de rigtige huller, men DMI-filerne blev sprunget over som tidligere behandlet. Samtidig var modelvalget faldet ud af den progressive cachemerge.</p><p>Eksisterende modelvalg gendannes fra den faktisk anvendte collection, gitterafstand og kysttype. Den aktuelle DMI-kørsel genbehandles én gang, og en dårligere model må ikke rydde en bedre serie.</p><div class=\"callout\"><strong>Uændret faglighed:</strong> Manglende data forbliver missing. Ingen ny kilde, fallback eller scoreændring indføres.</div>"},{"id":"dmi-current-contiguous-coverage-4-0-210","chapter":"72","title":"Sammenhængende DMI-strøm fra nutiden","summary":"En fjern strømprognosehale kan ikke længere skjule manglende DMI-strøm ved nutiden.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar kontrollerer nu, om strømserien begynder ved den aktuelle vejrbygning og fortsætter uden større huller.</div><p>Den tidligere kontrol så kun på det sidste gyldige tidspunkt. Derfor kunne to eller syv strømtrin fire døgn ude få en zone til at se dækket ud, selv om strøm manglede ved nutiden.</p><p>Den relevante DMI-havmodel prioriteres nu igen, når begyndelsen eller sammenhængen mangler. Manglende værdier forbliver manglende; der tilføjes ingen ny kilde, interpolation eller fallback.</p><div class=\"callout\"><strong>Score-neutral:</strong> Rettelsen genhenter og bevarer DMI-data, men ændrer ikke RavScore eller mobiliseringstærskler. Først efter mindst 72 timers måling kan en senere faglig scoreændring vurderes.</div>"},{"id":"weather-history-retention-4-0-209","chapter":"71","title":"Tre døgns score-neutral vejrhukommelse","summary":"4.0.209 udvidede den rå, private vejrhukommelse fra 24 til 72 timer som score-neutral forberedelse; Candidate G bruger nu sin egen afledte hukommelseskontrakt.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> 4.0.209 udvidede den private rå vejrhukommelse til 72 timer uden at ændre den daværende RavScore.</div><p><code>samples24h</code> og <code>samples72h</code> blev holdt ude af <code>public-conditions.json</code> og bevarede vind, bølger, strøm, vandstand og temperatur til faglig analyse.</p><p>Candidate G bruger nu et fast 48-timers vindue af dataminimeret, afledt strømevidens og en særskilt mobiliseringstilstand. Det er ikke det samme som at bruge hele den rå 72-timerspakke direkte i scoren.</p><div class=\"callout\"><strong>Aktuel status:</strong> Historikken forklarer datagrundlaget; den aktive scorekontrakt står i kapitel 54.</div>"},{"id":"local-validation-central-zone-truth-4-0-208","chapter":"70","title":"Lokale snapshots og centralt aktive zoner","summary":"Et gammelt lokalt vejrsnapshot er ikke i sig selv bevis for, at en zone mangler på den offentlige side.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadars aktive zonebestand bestemmes af centralt gemt administratorstatus, ikke af en historisk udviklerfil alene.</div><p>Den aktuelle offentlige bestand er 210 hovedzoner. De tre Vadehavszoner <code>DK-B04-12</code>, <code>DK-B04-13</code> og <code>DK-B04-14</code> findes både i det deployede zoneregister og i det offentlige vejrdatasæt. Fejø/Femø og Havnø/Mariager Fjord øst er centralt slettede og må ikke genopstå fra ældre filer.</p><p>Den lokale validering stopper fortsat ved mismatch. <code>npm run audit:deployed-zone-weather</code> sammenholder den faktiske deployede bestand skrivebeskyttet.</p><p><strong>Aktuel kontrakt:</strong> Den tidligere generiske <code>npm run hydrate:deployed-weather</code> er pensioneret. En frisk runtime bygges gennem produktionsworkflowets centrale adminhydrering, private bundle/checkpoint og nye vejr. Kun første kontrollerede modelskift har en eksplicit Candidate G-bootstrap.</p><p><strong>Historisk produktionsbevis:</strong> GitHub Actions #31848912461 bestod 4.0.208-kæden med 210/210 matchende zoner.</p><div class=\"callout\"><strong>Fail-closed:</strong> Ingen manglende eller ukendt zone accepteres for at få en grøn test.</div>"},{"id":"clean-idempotent-fallback-validation-4-0-206","chapter":"69","title":"Ren og idempotent fallbackkontrol","summary":"Den private fallbackkæde virker på en ren runner og efter tidligere aktivering uden at genskabe slettede historiske dele.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Fallbackbyggeren opretter selv alle private outputmapper og tager udgangspunkt i den centralt hydrerede aktive kyst.</div><p>Hvis oprindelige nabo-ID''er er erstattet af aktive restdele efter en tidligere aktivering, genbruges restenes aktuelle ID, geometri, landpunkt, vandpunkt og afledte pålandsretning. Historiske hardcodede værdier må ikke overstyre central runtime-sandhed, og et eksisterende punktpar uden retning afvises fail-closed.</p><p>Det kandidatbundne ESA WorldCover 10 m-bevis er genkørt på den aktuelle 17-dels fallbackbestand. Resultatet er uændret: 11 verificerede punktpar, fire sikre vendinger og to blokerede dele. Den rene lokale slutkæde har 2/2 ejerskabsflytninger, 9/9 erstatninger og nul overlap. Den fulde private GitHub-kæde #31829349458 bestod native DMI, central rollback og artifacts på en ren runner.</p><div class=\"callout\"><strong>Ingen automatisk aktivering:</strong> Det grønne tekniske bevis ændrer ikke den offentlige kyst eller RavScore. Aktivering kræver fortsat en særskilt ejerafgørelse.</div>"},{"id":"candidate-bound-land-water-evidence-4-0-203","chapter":"68","title":"Land-/vandbevis følger den præcise kandidat","summary":"Et gammelt punktbevis kan ikke længere anvendes på en ny kystbestand; tvivl stopper delen uden at gætte.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Hvert privat 10-meterbevis er låst til præcis de ukorrigerede kystdele og punktpar, som blev kontrolleret.</div><p>Beviset indeholder både et eksakt delantal og et digitalt fingeraftryk. Ændres geometri, ID eller punktpar, stopper workflowet før DMI, score og artifact i stedet for at genbruge en historisk afgørelse.</p><p>Den foreløbige kandidat har 835 dele: 520 verificerede, 149 sikkert vendte og 166 blokerede. Dette bevis er lavet direkte fra den rå GitHub-kandidat. Slutkandidaten har 652 dele: 427 verificerede, 111 sikkert vendte og 114 blokerede. Fallbackkandidatens 17 dele fordeler sig på 11 verificerede, fire sikkert vendte og to blokerede.</p><p>En blokeret del har ingen aktive land-/vandpunkter. Den bevarer to neutrale muligheder til senere kontrol, mens vejr, state, score og automatisk aktivering er slået fra.</p><div class=\"callout\"><strong>Slettede zoner:</strong> Fejø/Femø og Havnø/Mariager Fjord øst må ikke genopstå fra historiske reviewfiler. Offentlig kyst og RavScore ændres ikke af den private kontrol.</div>"},{"id":"effective-zone-register-4-0-197","chapter":"67","title":"Aktive zoner og historiske registerposter","summary":"Kun centralt aktive hovedzoner må styre den nationale produktions- og kontrolkæde.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar har 210 aktive hovedzoner efter den godkendte sletning af Fejø/Femø. Et historisk register kan stadig indeholde 211 poster uden at den slettede zone må genopstå.</div><p>Den nationale plan, topologiaudit, kystdelsbygger, stednavneaudit og lokalitetsopdeling bruger samme effektive bestand. Hver port stopper, hvis antallet af centralt aktive zoner afviger fra 210. Historiske rapporter og ældre 208-/211-bestande bevares som evidens, men må ikke styre en ny kørsel.</p><div class=\"callout\"><strong>Dataintegritet:</strong> En slettet eller deaktiveret zone må ikke blive aktiv igen, blot fordi en ældre fil stadig indeholder den. Central ejerstatus er runtime-sandhed.</div>"},{"id":"land-water-contract-4-0-196","chapter":"66","title":"Land, vand og den røde pålandspil","summary":"Hvert punktpar skal krydse sin egen kyst vinkelret: blåt i vand, grønt på land.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Den røde linje går fra det blå havpunkt til det grønne landpunkt og viser den retning, som vind og strøm sammenlignes med.</div><p>Hver lokal kyststrækning har ét punkt i vand og ét på land. Linjen skal krydse netop den valgte kyststrækning omtrent vinkelret. Punktparret er den fælles kilde til DMI-sampling, pålandsretning, lokal RavScore, offentlig forklaring og administratorens kort. Et gammelt separat gradtal kan derfor ikke overstyre markørerne.</p><p>Den nationale sidekontrol bruger uafhængig 10-meter landdækning ved flere afstande på begge sider af kysten. Entydigt omvendte par kan rettes gennem den private DMI- og releasekæde. Tvetydige ø-, havne- og smalle kystforløb ændres ikke automatisk, og stednavne bruges aldrig som bevis for land-/vandside.</p><div class=\"callout\"><strong>Godkendelse:</strong> Admin kan kun godkende hele zonen, når hvert punktpar har gyldige punkter på modsatte sider, krydser egen kyst og ligger tæt på vinkelret. En ændring påvirker først den offentlige score efter central readback og fulde DMI-/releasegates.</div>"},{"id":"admin-direction-map-4-0-195","chapter":"65","title":"Land- og havpunkter i administrationen","summary":"Arbejdskortet følger altid den valgte hovedzone og viser dens kystdele og punktpar.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Når administratoren vælger en hovedzone, zoomer land-/vandkortet til netop denne zone.</div><p>Editoren beregner først grænserne fra zonens aktive kystdele og punktpar og positionerer derefter Leaflet-kortet. Først derefter tegnes zone, kystlinjer og markører. Det forhindrer, at Leaflet stopper vektorlaget, fordi et nyt kort endnu ikke har en geografisk position.</p><p>Alle aktive kystdele i hovedzonen tegnes sammen med deres eksisterende blå havpunkter og grønne landpunkter. Den valgte kystdel fremhæves tydeligt, og kun dens markører er flytbare.</p><div class=\"callout\"><strong>Afgrænsning:</strong> Editorens kort er arbejdsfladen. Den tidligere knap <em>Vis på hovedkortet</em> er fjernet. DMI, RavScore og det offentlige kort ændres ikke af denne rettelse.</div>"},{"id":"local-dmi-integrity-4-0-193","chapter":"64","title":"Lokal DMI og geografiske delscorer","summary":"Lokale scorer kræver eget verificeret strømgrid og en reel sammenligning mellem mindst to kystdele.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En lokal score må kun vises, når kystdelens eget DMI-punkt har verificeret strømretning og -hastighed.</div><p>Scheduler og releasekontrol tæller nu alle lokale kystdele, ikke kun hovedzonerne. Alle aktive dele skal have dokumenteret lokalt eller særskilt tilladt U/V-grid, aktuelt 673 af 673, og runtime må ikke udgive flere lokalt scorede dele end den verificerede cache indeholder. Den tidligere grænse på 95 % var en indfasningsregel og gælder ikke længere for nye releases.</p><p>Hvis en komplet lokal sammenligning mangler, bruges den fortsat valide hovedzonescore uden en geografisk påstand. Én enkelt beregnet kystdel kan aldrig bevise, at hele en bugtet zone har ens forhold. Når en lokal score bruges, følger dens rå vejrdata, land-/havpunkt, pålandsretning og fulde faglige forklaring samlet med.</p><p>Den første systemaudit fandt og rettede 13 punktpar, som ikke passede med den lokale tangent ved deres valgte kyststed. En senere bred orienteringsaudit måler noget andet: vedvarende retningsvariation inden for hele strækningen. Den flagger 199 kontrolkandidater i 122 zoner, men 171 er fragmenterede MultiLineString-dele, så resultatet er triage og ikke 199 beviste fejl.</p><div class=\"callout\"><strong>Aktiv kontrakt:</strong> Hver af de 673 dele har ét autoritativt punktpar. På bugtede dele vælger ejeren senere en repræsentativ placering manuelt. Ekstra aktive punktpar og automatisk national genopdeling er fravalgt; en flytning skal fortsat bestå central readback og DMI-/releasegate.</div>"},{"id":"local-part-map-4-0-185","chapter":"63","title":"Hvor ligger zonens kystdele?","summary":"Knappen Hvor er det? viser de navngivne kystdele på det eksisterende kort uden ekstra opstartsdata.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Knappen Hvor er det? viser de navngivne kystdele på hovedkortet.</div><p>Når en hovedzones kystdele scorer forskelligt, kan brugeren trykke <strong>Hvor er det?</strong> Kortet zoomer til zonen, viser alle dens præcise kystdele med navn og fremhæver de aktuelt bedste dele efter den eksisterende 7-points-regel.</p><p>Kortlaget bruger den kystgeometri, som allerede er indlæst. Der hentes ikke billeder eller ekstra data ved normal sideindlæsning. Den offentlige <strong>Hvad fandt du?</strong>-formular er fjernet, mens turregistrering og administratorens observationsanalyse er bevaret.</p>"},{"id":"formaal","title":"1. Formål, målgruppe og fagligt løfte","summary":"Håndbogens rolle som fælles sandhed for ejer, eksperter og udvikling.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Håndbogen er fælles faglig og teknisk reference for ejer, eksperter og udvikling. <span>Den skelner mellem offentlig historik, lokal releasekandidat og fortsat usikkerhed.</span></div><p>RavRadar er et beslutningsstøttesystem til ravjagt langs danske kyster. Systemet samler prognoser, lokale kystdata og en forklarlig RavScore-model. Det skal hjælpe med at vælge <strong>sted og tidspunkt</strong>, men må aldrig fremstille en høj score som et løfte, en procentchance eller en sikkerhedsvurdering.</p>\n<p>Håndbogen er skrevet til tre målgrupper: ejeren, eksterne rav-/sediment-/kysteksperter og fremtidige udviklere. En ekspert skal kunne forstå både hypotesen, de konkrete arbejdspriorer og hvor systemet stadig mangler data.</p>\n<div class=\"callout\"><strong>Fagligt løfte:</strong> Alle væsentlige antagelser skal kunne spores til forskning, praktisk observation, projektbeslutning eller eksplicit hypotese. Tærsklerne må aldrig præsenteres som naturkonstanter, og den integrerede kandidat må ikke kaldes empirisk mere fundpræcis uden repræsentative fund og nul-fund.</div>\n<p>RDKS er autoritativt for bindende beslutninger, aktive krav og kendte problemer. Koden er autoritativ for den implementerede releasekandidat; den produktionsverificerede offentlige adfærd er fortsat 4.0.316/Candidate G indtil det samlede cutover. Ved uoverensstemmelse registreres og rettes den.</p>"},{"id":"evidens","title":"2. Evidensklasser, kildekritik og usikkerhed","summary":"En fast klassifikation, så ekspertviden og hypoteser ikke bliver skjult som fakta.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En fast klassifikation forhindrer, at ekspertviden og hypoteser bliver skjult som fakta.</div><p>RavRadar bruger fire evidensklasser. De skal fremgå, når en faglig påstand foreslås omsat til aktiv modellogik.</p>\n<div class=\"handbook-table-wrap\"><table><tr><th>Klasse</th><th>Betydning</th><th>Må bruges til</th><th>Må ikke bruges til</th></tr><tr><td>Dokumenteret viden</td><td>Relevant forskning, officiel måling eller veletableret kystfysik</td><td>Procesforklaring og forsigtige ændringsforslag</td><td>Lokale numeriske tærskler uden lokal validering</td></tr><tr><td>Ekspertobservation</td><td>Gentagen praktisk erfaring fra kendt område og jagtform</td><td>Testbar og afgrænset hypotese</td><td>Automatisk ændring af landsdækkende score</td></tr><tr><td>RavRadar-hypotese</td><td>Plausibel mekanisme eller arbejdsværdi</td><td>Simulering, eksperiment og audit</td><td>Skjult produktionsregel</td></tr><tr><td>RavRadar-valideret</td><td>Understøttet af kontrollerede projektdata og hold-out-test</td><td>Versionsstyret modelændring</td><td>Universel naturvidenskabelig sandhed</td></tr></table></div>\n<p>En kilde vurderes efter relevans, metode, skala og overførbarhed. Lavdensitetsplast og driftere kan give mekanistisk analogi, men er ikke rav. Form, størrelse, overflade, biofilm, vandmætning og bundkontakt kan ændre transporten.</p>\n<p>Når et ekspertudsagn strider mod kode eller beslutning, registreres det som hypotese. Det kan først blive aktivt, når mekanisme, geografi, betingelser, forventet effekt og modbevis er beskrevet, den autoritative integrerede kæde og RDKS er opdateret, og tests samt releasegates er bestået.</p>"},{"id":"rav-egenskaber","title":"3. Ravets fysiske egenskaber og hvorfor densitet alene ikke er nok","summary":"Ravets opdrift, bundkontakt, form og kobling til organisk materiale.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Ravets opdrift, bundkontakt, form og kobling til organisk materiale betyder, at én partikelregel ikke kan beskrive alle stykker.</div><p>Rav har typisk densitet tættere på havvand end kvarts, men det betyder ikke, at alt rav flyder. Saltindhold, temperatur, luftlommer, porøsitet, indlejret materiale, størrelse og form påvirker opførslen.</p>\n<ol><li>Rav kan ligge mekanisk låst i sand, grus, ler, tørv, tang eller revner.</li><li>Bølger og strøm kan løsne det og reducere bundkontakten.</li><li>Stykket kan rulle, hoppe, glide eller blive kortvarigt suspenderet.</li><li>Det kan transporteres med let organisk materiale.</li><li>Når energien falder eller vandet trækker sig tilbage, kan det aflejres ved opskyl, lavning, revlebagkant eller tangvold.</li></ol>\n<p>RavRadar har ingen partikelstørrelsesmodel. Scoren beskriver et generelt potentiale, ikke banen for et bestemt stykke.</p><h3>3.1 Densitet og form</h3><p>Chubarenko og Stepanova angiver baltisk rav omkring 1,05–1,10 g/cm³. Størstedelen synker i vand og kan have bundkontakt; variation i form, ruhed, biofilm og vandmætning ændrer modstand og synkehastighed, men gør ikke rav til en generel positivt flydende overfladetracer.</p><h3>3.2 Bundkontakt og skjult rav</h3><p>Et frit stykke på glat sand er ikke i samme tilstand som et stykke klemt mellem grus eller dækket af sand. Den integrerede kandidat bruger bølgeenergihistorik som mobiliseringsproxy, men beregner ikke lokal bundskærspænding, begravelsesdybde eller partikelbane.</p><div class=\"implementation\"><strong>Implementeret i:</strong> Energi og state ligger i <span class=\"file-ref\">js/core/ravscore-wave-mobilisation-state.js</span> og <span class=\"file-ref\">js/core/ravscore-integrated-state-pipeline.js</span>; scorevirkningen ligger i <span class=\"file-ref\">js/core/ravscore-integrated.js</span>. <span class=\"file-ref\">js/core/coastal-process-model.js</span> er historisk forklaringsforskning og ikke en samtidig offentlig scorevej.</div>"},{"id":"tilstedevaerelse","title":"4. Tilstedeværelse og kildelagre","summary":"Hvor ravet kan komme fra, og hvorfor vejr ikke kan skabe rav.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Hvor ravet kan komme fra, og hvorfor vejr ikke kan skabe rav. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p>En prognose kan kun være god, hvis der findes rav i eller opstrøms for det område, der aktiveres. RavRadar modellerer i øjeblikket ikke et fysisk lager af rav. Det betyder, at systemet vurderer <strong>transport- og findeforhold</strong>, men ikke kender den reelle mængde rav i sedimentet.</p>\n<p>Mulige kildelagre omfatter eroderende geologiske lag, ældre strand- og klitaflejringer, undervandsrevler, lavninger med organisk materiale, tidligere stormdepoter, tangbælter og materiale transporteret langs kysten fra naboområder. En høj energihændelse kan åbne et lager; efterfølgende hændelser kan tømme det.</p>\n<p>Gentagne høje scorer uden fund kan derfor skyldes lagerbegrænsning og ikke nødvendigvis fejl i strøm- eller bølgemodellen. Fremtidig læring bør skelne mellem ''forholdene var fysisk gunstige'' og ''området leverede faktisk rav''.</p>\n<div class=\"callout\"><strong>Ekspertpunkt E-02:</strong> Identificér kysttyper og områder, hvor geologisk ravtilstedeværelse er kendt, sandsynlig eller lav, og vurder om der kan bygges en langsomt skiftende kildelagerfaktor uden at skabe falsk sikkerhed.</div>"},{"id":"proceskaede","title":"5. Den samlede proceskæde","summary":"Flere mulige veje kan føre til fundbart rav; den fulde kæde er stærkest, men ikke eneste mulighed.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Flere veje kan føre til fundbart rav; en ny storm er ikke altid nødvendig.</div><p>Den fulde proces kan omfatte et muligt lager, mobilisering, transport frem mod kystzonen, sidste nærkystlevering, aflejring/retention, eksponering og søgeforhold. Rav kan også allerede ligge i et sekundært nærkystlager og blive genmobiliseret eller blotlagt af en mindre hændelse.</p><h4>5.1 Tre praktiske veje</h4><ol><li><strong>Ny frigivelse:</strong> høj energi åbner et primært eller begravet lager.</li><li><strong>Genmobilisering:</strong> allerede tilgængeligt rav sættes igen i bevægelse.</li><li><strong>Geneksponering:</strong> ravet flyttes kun lidt, men bliver søgbart.</li></ol><p>Den integrerede model har tre numeriske komponenter: søgeforhold, relativt gridstrømsbaseret transportbevis frem mod kystzonen og rav i bevægelse. Lager, koncentration, aflejring og retention er ikke selvstændige scorekomponenter.</p><div class=\"handbook-callout\"><strong>Vigtig begrænsning:</strong> RavRadar kender ikke det faktiske ravlager eller det sidste stykke gennem surfzonen. Scoren er et indeks, ikke bevis eller fundchance.</div>"},{"id":"boelger","title":"6. Bølger, orbitalbevægelse, brydning og turbulens","summary":"Bølgernes dobbelte rolle som mobilisering og jagtbarhedsproblem.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Bølger kan mobilisere, påvirke søgeforhold og afgrænset dæmpe sidste levering, men en bølgeorbital er ikke gridstrøm eller lokal surfzonecirkulation.</div><p>Bølgeorbitaler, brydning og turbulens kan løsne let materiale fra bund, tang eller nærkystnære aflejringer. Nettotransporten afhænger også af bølgeasymmetri, strøm, strandprofil, undertow og hvor partiklen befinder sig.</p><p><strong>Mobilisering:</strong> <code>Hs² × T</code> bygger én tilstand med cirka fire timers og aftager med cirka 48 timers halveringstid. <strong>Søgeforhold:</strong> Aktuel bølgehøjde kan reducere metode-/sigtbarhed. <strong>Delivery:</strong> En kausal energivægtet DMI-WAM-retning med fire timers halveringstid og en ældre hale kan kun dæmpe eksisterende supply højst 15 % og aldrig øge det.</p><p>DMI-retningen er <code>FROM</code> og roteres én gang +180° til <code>TOWARD</code> mod den uændrede kystnormal. Aktiv energibærende direction-missing fejler lukket. Kun <code>waveHeightM=0</code> er eksakt calm og neutral; <code>wavePeriodS</code> skal stadig være finit og ikke-negativ. <code>waveHeightM&gt;0</code> med <code>wavePeriodS=0</code> er <code>INVALID</code> og fejler lukket. De tre bølgeroller må ikke give hinanden ekstra kredit.</p><h3>6.1 Vigtig begrænsning</h3><p>RavRadar modellerer ikke lokal refraktion, brydning ved dynamiske revler eller surfzonens undertow, feeder-/langskyst- og ripstrømme. <code>physicalDeliveryResolved=false</code>, og fysisk interval er <code>null</code>. DDM 50 m er kun statisk kontekst. Rainville 2026 målte positivt flydende overfladedriftere, ikke negativt flydende rav med mulig bundkontakt; studiet er alene procesanalogi og aldrig ravkalibrering.</p><div class=\"evidence\"><strong>Evidens:</strong> Den generelle fysik er mekanistisk støtte; energi-, tids- og approachkurverne er testede priorer, ikke fundkalibrerede naturgrænser.</div>"},{"id":"stroem","title":"7. Modelgridstrøm: retning, styrke og transportbevis","summary":"Hvordan strøm tolkes, og hvorfor en 180°-fejl er kritisk.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Den verificerede gridstrøm giver et relativt transportbevis frem mod kystzonen. Den er ikke surfzonens undertow eller ripstrøm.</div><p>Strømretning er den retning, vandet bevæger sig mod. Den projiceres på den lokale kystnormal. Positiv komponent er indgående, negativ udgående, og næsten parallel strøm giver kun en lille komponent. En 180°-fejl er derfor kritisk.</p><p>0,03 m/s er dødzone, og 0,15 m/s tæller som fuld styrke. Fuld indgående strøm giver +10 point pr. effektiv time; fuld udgående giver -8 fra første effektive time. Evidens vægtes fuldt i 24 timer og dæmpes glat til nul ved 48 timer. Den gamle 13-timers helscore-gate er fjernet.</p><p>Forløbet genafspilles fra en fast nulrand. Native prøver må ligge op til tre timer fra hinanden som et eksplicit hold uden opdigtet bevægelse. Manglende eller inkompatibel strøm er et hul, ikke neutral strøm.</p><div class=\"callout\"><strong>Vigtig begrænsning:</strong> Et transportled på 0 beviser ikke, at alt rav er væk. Gridcellen opløser ikke revler, render, feeder-/langskyststrøm eller ripstrømme.</div>"},{"id":"vind","title":"8. Vindens direkte og indirekte rolle","summary":"Vind skaber bølger og overfladedrift, men er ikke lig med bundstrøm.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Vind skaber bølger og påvirker søgeforhold, men er ikke lig med gridstrøm eller bundtransport.</div><p>Vind påvirker havet indirekte gennem bølger, vandstand og overfladedrift. Den integrerede model giver ikke vindretningen direkte transport- eller mobiliseringspoint; gridstrømmen giver transportbeviset, mens modellerede bølger giver mobiliseringssignalet.</p><p>Ved waders er vindhastigheden hovedsignal: 100 til og med 6 m/s, derefter 80 ved 7, 60 ved 8, 35 ved 10, 10 ved 13 og 0 ved 15 m/s. Strandjagt har ikke dette loft.</p><p>Fralandsvind kan derfor give roligere søgevand uden i sig selv at fortælle, om rav transporteres ind eller ud.</p>"},{"id":"vandstand","title":"9. Vandstand, setup, tidevand og den aktive kystzone","summary":"Vandstand ændrer både transportvej, aflejring og adgang.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Vandstand ændrer den aktive kystzone, men giver ingen RavScore-point og bestemmer ikke strømretningen.</div><p><code>waterLevelTrendCm3h</code> er den fremadrettede modelændring fra den viste time til tre timer senere. Den er aldrig en observeret ebbe, flod eller tidevandsfase. Stigende vand kan flytte brydnings- og opskylszonen og i nogle forløb føre allerede indgående materiale længere ind, men det beviser ikke indtransport. Faldende vand kan falde sammen med søværts transport af noget mobilt rav. Lavere vand kan samtidig blotlægge rav, som allerede er afleveret eller fastholdt på land- eller læsiden af revler, så et mindre område bliver lettere at afsøge; det beviser ikke, at vandstandsfaldet fysisk har koncentreret ravet.</p><p>Ved faldende vand viser RavRadar derfor en score-neutral fælleskontekst med verificeret kystnormal gridstrøm: udgående, indgående, langs/for svag inden for ±0,03 m/s eller ukendt/native-hold. Konteksten ændrer hverken score, state eller transportpotentiale.</p><p>RavRadar laver ikke en ekstra “hele vandsøjlen”-strøm ud fra vandstandens trend og interpolerer den ikke med gridstrømmen. DMI''s DKSS beregner et tredimensionalt fysisk havfelt med atmosfærisk forcing og tidevands-sealevel ved åbne rande og leverer selv current-U/V. Copernicus Baltic NEMO leverer tilsvarende fysiske hastighedsfelter, også som særskilte øjeblikkelige og detidede produkter. Der er ingen direkte dubletterm mellem RavRadars vandstandskontekst og gridstrømmens transportled, men begge kan reagere på fælles drivere, så residual korrelation er mulig. Modelstrømmen er et samlet modeludfald, ikke bevis for hver lokal proces eller for ens retning i hele vandsøjlen. En ekstra vandstandsregel kunne derfor dobbeltregne korreleret dynamik og ville stadig ikke fortælle fortegnet i surfzonen. Se <a href=\"https://www.dmi.dk/friedata/dokumentation/data/forecast-data-storm-surge-model-dkss\">DMI''s DKSS-dokumentation</a> og <a href=\"https://data.marine.copernicus.eu/product/BALTICSEA_ANALYSISFORECAST_PHY_003_006/description\">Copernicus'' produktbeskrivelse</a>.</p><p>Uden lokal batymetri, revlegeometri og en bølgeopløst surfzonemodel kan RavRadar ikke afgøre, hvilken virkning der dominerer. Ved præcis RavScore-lighed vælger waders lavere kendt vand, derefter ikke-stigende vand og til sidst tidligste tidspunkt; strand vælger tidligste tidspunkt. Den eksakte årsag vises. Lavere vand er kun en søgbarhedsprioritet, ikke tegn på mere rav eller en sikkerhedsvurdering.</p><p>Vadehavet kræver særbehandling: store sekventielle ændringer kan være ægte tidevand, mens unaturlige kildeskift er dataintegritetsfejl.</p>"},{"id":"langskyst","title":"10. Langs- og tværkysttransport","summary":"Rav kan ankomme fra siden og aflejres ved ændringer i kystretning.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Rav kan ankomme fra siden, men modellen måler kun gridstrømmens lokale komponent mod eller væk fra kystzonen.</div><p>Skrå bølger og strøm kan transportere materiale langs stranden. Odder, bugter, havne, revler og indløb kan skabe konvergens, ophobning eller bypass.</p><p>Næsten parallel gridstrøm giver kun en lille kystnormal komponent. Modellen følger ikke et transportnetværk mellem nabozoner og foregiver ikke at måle bølgedrevet langskyststrøm i surfzonen. Den kan derfor overse vigtig tilførsel fra siden.</p><div class=\"callout\"><strong>Ekspertpunkt E-07:</strong> Udpeg kyster hvor langskyst transport er vigtigere end direkte indtransport, og hvordan den kan efterprøves uden at overvurdere bypass.</div>"},{"id":"undertow","title":"11. Undertow, returstrøm og ripstrømme","summary":"Hvorfor store indkommende bølger også kan skabe udadgående bundnær transport.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Undertow, feeder-/langskyststrøm og ripstrøm er forskellige processer og må ikke samles til én antaget “understrøm”.</div><p><strong>Undertow</strong> er den bølgeinducerede, typisk søværts middelretur under den øvre del af vandsøjlen. <strong>Feeder-/langskyststrøm</strong> løber overvejende langs stranden eller ind mod en rende som følge af skrå eller ujævn bølgebrydning og setup-gradienter. <strong>Ripstrøm</strong> er en mere lokaliseret søværts jet gennem eller ved et brud, en rende eller et forbjerg og kan indgå i recirkulation. Et ravstykke kan derfor påvirkes af indgående opskyl ét sted, langsstrøm et andet og udadgående bundnær strøm eller rip et tredje.</p><p>RavRadar har ingen opløst model af disse processer. Den verificerede kystnormale gridstrøm kan reducere det relative transportbevis fra første effektive udgående time, men den bruges ikke som stedfortræder for surfzonens returvand. Et transportled på 0 nulstiller ikke hele scoren og beviser hverken, at intet rav findes, eller at alt rav er ført ud.</p><h4>Primærkilder og forsigtig slutning</h4><ul><li><a href=\"https://doi.org/10.1029/2000JC900084\">Faria m.fl. (2000)</a> viser undertows rumlige struktur og store model-/observationsafvigelser over revlen på én revlekyst.</li><li><a href=\"https://doi.org/10.1002/2016JC012222\">Moulton m.fl. (2017)</a> viser, at rip-/undertowfeltet afhænger af lokal revle-/kanalgeometri, bølgebrydning, setup og batymetri.</li><li><a href=\"https://doi.org/10.1029/2001JC000955\">Haller m.fl. (2002)</a> er et laboratorieforsøg på en fast revlestrand med ripkanaler. Det dokumenterer morfologiafhængig bølgebrydning, feederstrømme og ripcirkulation, men er ikke lavvandsfeltbevis.</li><li><a href=\"https://doi.org/10.1029/2008JC005153\">Reniers m.fl. (2009)</a> fandt, at Stokes-drift og lavfrekvente bevægelser var nødvendige for surfzoneretention; cirka 20 % observerede exits er ikke en universel ravandel.</li><li><a href=\"https://doi.org/10.1016/j.margeo.2018.07.015\">Gallop m.fl. (2018)</a> knytter revlebrydning til ændret ripcirkulation, retention og exit på en dobbelt revlekyst.</li><li><a href=\"https://doi.org/10.1016/j.margeo.2009.09.011\">MacMahan m.fl. (2010)</a> viser, at ripstrøm kan indgå i recirkulation frem for ren eksport.</li><li><a href=\"https://doi.org/10.1016/S0025-3227(97)00025-X\">Aagaard m.fl. (1997)</a> er feltmålinger fra én revlekyst og observerede kraftig søværts rip-/sedimenttransport ved lavvande, mens oscillerende transport uden for surfzonen var landværts.</li><li><a href=\"https://doi.org/10.1029/2020JC016259\">Mouragues m.fl. (2020)</a> er et treugers feltstudie, hvor bølger, vandstand og morfologi gav skiftende regimer: blandt andet lavvandsstærk deflektions-rip under ét forløb og landværts strøm eller lokale hvirvler under andre.</li><li><a href=\"https://doi.org/10.1016/S0025-3227(02)00193-7\">Aagaard, Black og Greenwood (2002)</a> viste, at nettotransport over revler afhænger af undertow, bølgeskævhed, orbitalhastighed, relativ dybde og bundhældning; høj energi alene fastsætter ikke fortegnet.</li><li><a href=\"https://doi.org/10.5194/gmd-18-319-2025\">Jalón-Rojas m.fl. (2025)</a> viste i en bølgeopløst 2DV-model, at vertikal position og densitet ændrer eksponeringen for landværts Stokes-drift og søværts undertow. Mikropartiklerne er analogi, ikke ravkalibrering.</li><li><a href=\"https://doi.org/10.1016/j.watres.2023.120329\">Lofty m.fl. (2023)</a> målte 5 mm-rav omkring 1 041 kg/m³ og fulgte det som lavdensitets naturlig partikel i bedload/saltation. Åbent-kanal-forsøget er ikke en dansk surfzonemodel.</li><li><a href=\"https://doi.org/10.1016/j.envpol.2017.01.085\">Chubarenko m.fl. (2017)</a> understreger, at systematisk ravmonitorering mangler, og opstiller gentagen migration mellem strand og undervandsskråning med mulig tilbageførsel over dage som hypotese.</li></ul><p>Studierne støtter en tosidet, stedafhængig konklusion: Faldende vand kan i et konkret system falde sammen med en søværts transportvej for noget mobilt rav. Lavere vand kan samtidig blotlægge rav, som allerede er afleveret eller fastholdt bag revler og ved kanter, uden at bevise fysisk koncentration. Gentagen migration betyder desuden, at søværts bevægelse ikke er bevis for, at alt rav er væk. Hverken gridstrøm, vandstand eller bølger alene bestemmer sidste-mile-fortegnet; kilderne leverer ingen landsdækkende faldende-vand-regel.</p><div class=\"callout\"><strong>Sidste-mile-usikkerhed:</strong> Om rav fysisk strander, fanges bag en revle, passerer langs kysten eller føres ud gennem en rende, er fortsat uafklaret. Releasekandidaten bruger kun en kausal energivægtet wave-approach med fire timers halveringstid og en ældre hale til at dæmpe eksisterende supply én gang med højst 15 % – højst 7,5 rå totalscorepoint før slutafrunding – vist RavScore kan derfor ændres 8 point – og foregiver ikke lokal surfzonepræcision. Vandstand giver 0 direkte scorepoint.</div>"},{"id":"sortering","title":"12. Hydrodynamisk sortering og ledsagematerialer","summary":"Hvorfor rav ofte findes i bestemte fraktioner, men indikatorerne ikke er entydige.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Rav findes ofte sammen med let ledsagemateriale, men tegnene er ikke entydige.</div><p>Størrelse, form, ruhed, løfteareal, bundfriktion og synkehastighed påvirker sorteringen. En frisk tanglinje kan være et godt felttegn, men tang kan også være gammel, vindflyttet eller komme fra et andet lag i vandet.</p><p>Den integrerede model giver ingen statisk bonus for tang, ålegræs, rev eller lavt vand. Oplysningerne er faglig kontekst og kan senere afprøves mod komplette ture.</p><div class=\"callout\"><strong>Ekspertpunkt E-09:</strong> Rangér ledsagematerialer efter deres værdi som tegn på frisk aflejring frem for gammel omlejring.</div>"},{"id":"vegetation","title":"13. Tang, ålegræs og vegetation som transportør og fælde","summary":"Vegetation kan både flyde, synke, fange og senere frigive rav.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Vegetation kan transportere, fange og senere frigive rav.</div><p>Flydende tang kan samle små stykker, nedsunkne tangbælter kan lagre dem, og vegetation kan sænke lokal strøm og fremme aflejring. Forskning i lavdensitetspartikler støtter mekanismen som analogi, men RavRadar måler ikke vegetationens tæthed, sæson eller tilstand.</p><p>Den integrerede model giver ingen statiske vegetationspoint. Det gamle +3-transportbidrag og en forskningsindikators retentionpoint er historik.</p><div class=\"callout\"><strong>Ekspertpunkt E-10:</strong> Beskriv hvornår tang og ålegræs er transportør, fælde eller blot et gammelt felttegn, og hvordan det kan registreres.</div>"},{"id":"kystmorfologi","title":"14. Kystmorfologi, revler, render, odder og menneskeskabte strukturer","summary":"Hvordan geometri fokuserer, blokerer eller omdirigerer transport.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Kystformen kan fokusere, blokere eller omdirigere transport, men grove steddata giver ikke scorepoint.</div><p>Revler kan flytte brydningslinjen, render kan fokusere returstrøm, odder kan skabe læ eller bypass, og havne og høfder kan afbryde langskyst transport.</p><p>RavRadar har statiske kystoplysninger og lokale kystretninger, men ingen detaljeret batymetri eller morfodynamisk surfzonemodel. Historiske stedbonusser er ikke del af den integrerede score. Bund, dybde, render, revler og automatisk stedegnethed er bevidst udeladt.</p><div class=\"callout\"><strong>Ekspertpunkt E-11:</strong> Vurder hvilke stedegenskaber der kun bør forklares, og hvilke der senere kan efterprøves uden at overse lokale undtagelser.</div>"},{"id":"stormforloeb","title":"15. Storm, efterstorm og tidslig persistens","summary":"En hændelse er et forløb, ikke et øjebliksbillede.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En hændelse er et forløb, ikke et øjebliksbillede.</div><p>Høj energi kan først sætte rav i bevægelse, gridstrømmen kan derefter give transportbevis frem mod kystzonen, og senere roligere eller lavere vand kan gøre tidligere aflejring lettere at finde. Derfor kan tiden efter en storm være bedre end stormens maksimum.</p><p>Den integrerede model bruger ikke gamle faste stormbonusser. Strømevidens vægtes fuldt i 24 timer og dæmpes glat til nul ved 48 timer. Mobiliseringen bygges med cirka fire timers og aftager med cirka 48 timers halveringstid.</p><p>Der er ingen ekstra redigerbar landsregel, som automatisk fastholder høj score. Ravlagerets faktiske størrelse, lokale aflejring og tømning modelleres ikke.</p><div class=\"callout\"><strong>Ekspertpunkt E-12:</strong> Vurder om fire/48-timers mobilisering og 24/48-timers strømvægt afspejler hændelsesforløbet ved forskellige kysttyper.</div>"},{"id":"aflejring","title":"16. Aflejring, opskylslinjer og genmobilisering","summary":"Hvor ravet ender, og hvorfor fundstedet kan flytte sig efter hændelsen.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Rav kan aflejres, blotlægges og flyttes igen; RavRadar beregner ikke den præcise strandingsposition.</div><p>Aflejring kan ske ved swashgrænsen, bag en revle, i en tanglinje, i læ af en odde, ved en strandvold eller i en lavning. Flere opskylslinjer kan repræsentere forskellige vandstande og hændelser.</p><p>Efter aflejring kan rav flyttes igen af bølger, backwash, faldende vand og tilhørende strøm, vind på stranden eller en ny storm. Faldende vand kan både falde sammen med udtransport og blotlægge et depot bag en revle, så et mindre felt bliver lettere at afsøge.</p><p>Vandstandsændring er score-neutral kontekst. Jagtformen påvirker søgeforhold, ikke en skjult aflejringsberegning.</p><div class=\"callout\"><strong>Ekspertpunkt E-13:</strong> Beskriv hvilke kombinationer af faldende vand, bølgeaftagning og kystprofil der bedst forudsiger synlige opskylslinjer.</div>"},{"id":"jagtbarhed","title":"17. Jagtbarhed, sigt og sikkerhed","summary":"Fysisk transportpotentiale er ikke det samme som et godt eller sikkert jagttidspunkt.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Søgeeffektivitet er ikke det samme som fysisk transport eller sikkerhed.</div><p>Den integrerede model bruger 20 % søgeforhold, 50 % transportbevis og 30 % mobilisering. RavRadar har to jagtformer: <code>waders</code> og <code>beach</code>.</p><p>Waders-vindscoren er 100 til og med 6 m/s og falder gennem 7/80, 8/60, 10/35 og 13/10 til 15/0. Bølger kan kun reducere den med 20 procent af et negativt gab. Slutscoren kan ikke overstige waders-søgeforholdene.</p><p>Strandjagt bevarer de eksisterende vind- og bølgekurver og kombinerer det svageste signal med det vægtede gennemsnit; den har ikke wadersloftet. Begge jagtformer kræver vindhastighed og bølgehøjde og fejler lukket ved manglende input.</p><div class=\"callout\"><strong>Sikkerhed:</strong> RavScore vurderer ikke, om det er sikkert at gå i vandet. Lokal bund, mørke, strøm, temperatur, is, adgang og brugerens erfaring indgår ikke fuldt.</div>"},{"id":"score-implementering","title":"Historisk 18. Den aldrig-offentlige state-5-kode","summary":"Historisk beskrivelse af state-5-kandidaten; den aktive lokale state-6-kontrakt står i kapitel 89.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> <code>RRS-COASTAL-PROCESS-INTEGRATED-1.1.0</code>/state <code>5.0.0</code> er 4.0.315-releasekandidaten. Candidate G er fortsat den eneste offentlige 4.0.310-model, indtil exact-head, merge, frisk produktion og offentlig browserkontrol beviser DEC-0110-cutoveret.</div><p>Variant <code>COASTAL-SUPPLY-MOBILISATION-BOUNDED-WAVE-APPROACH-HUNTABILITY-2</code>, profil <code>cn-003-015-in10-out8-full24-cos48-gap3-wave4-48-coldrestart-gapcredit1-lastmileewma4-atten15-v4</code>, komponent <code>ravscore-components-huntability-delivery-mobilisation-v4</code> og forklaring <code>ravscore-explanation-integrated-v4</code> bindes sammen med kontrakt- og bundlehash. Slutværdier dokumenteres først på afsluttet head.</p><h4>18.1 Hovedformel</h4><p><code>grundscore = søgeforhold × 0,20 + levering mod kystzonen × 0,50 + rav i bevægelse × 0,30</code>. Der er ingen 13-timers helscore-gate eller 65/35-dobbeltblanding.</p><h4>18.2 Transport og sidste mile</h4><p>Gridstrøm bruger 0,03/0,15 m/s, +10/-8 og 24 timers fuld vægt med cosinusfade til nul ved 48 timer. En kausal energivægtet bølgeapproach med fire timers halveringstid og en ældre hale danner <code>W/N/T</code>. DMI-WAM <code>FROM</code> roteres præcis én gang +180° til <code>TOWARD</code> mod den uændrede kystnormal. <code>normalAlignment</code> er det energivægtede normalmoment divideret med aktivitet, og <code>approach=clamp((normalAlignment+0,25)/1,25,0,1)</code>. <code>factor=clamp(1-0.15×W×(1-approach),0.85,1)</code>, og <code>delivery=supply×factor</code> anvendes én gang. Bølger kan aldrig skabe eller øge supply; højst 7,5 rå totalscorepoint fjernes før slutafrunding; vist RavScore kan derfor ændres 8 point. Aktiv direction-missing fejler lukket. Kun <code>waveHeightM=0</code> er eksakt calm og neutral; <code>wavePeriodS</code> skal stadig være finit og ikke-negativ. <code>waveHeightM&gt;0</code> med <code>wavePeriodS=0</code> er <code>INVALID</code> og fejler lukket.</p><p><code>physicalDeliveryResolved=false</code>, og fysisk interval er <code>null</code>. DDM 50 m er kun statisk kontekst uden dynamiske revler/surfzone; Rainville 2026 er kun buoyant-object-analogi og ikke ravkalibrering. Ingen geometri eller land-/vandpunkter flyttes.</p><h4>18.3 Mobilisering, jagtbarhed og vandstand</h4><p><code>Hs² × T</code> bygger mobilisering med cirka 4/48 timer. Waders bruger vindkurven 6–15 m/s og et blødt bølgefradrag; strand bevarer sine kurver. Faldende vand kan både ledsage udtransport og blotlægge/fremhæve fastholdt rav bag revler; vandstand er derfor score-neutral kontekst og tie-break.</p><h4>18.4 State, nøddrift og tillid</h4><p>Ægte cold start kræver præcis 48 private verificerede timer plus reel target. Candidate G-rollback bruger samme target uden dobbelt recovery-credit. Nøddrift er kun same-model, komplet, atomisk og hashbundet i højst 72 timer; ingen cross-model fallback eller interpolation. Kun <code>VERIFIED_ONLY</code> er kalibreringsegnet; reconstructed/emergency og ture er ikke kalibreringsgrundlag. Modellen er fysisk motiveret og mekanisk regressionstestet, men ikke dokumenteret empirisk mere fundpræcis.</p>"},{"id":"procesindikator","title":"19. Procesindikatoren for hændelsesfase","summary":"En separat diagnostisk model, som ikke må forveksles med RavScore.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En separat diagnostisk model, som ikke må forveksles med RavScore. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p><code>js/core/coastal-process-model.js</code> beregner en hændelsesindikator med mobilisering 45 %, timing 25 %, fortsættelse 20 % og retention (tilbageholdelse) 10 %. Den klassificerer kysten heuristisk og giver en fasebeskrivelse.</p>\n<p>Indikatoren kan være fagligt nyttig, fordi den gør hændelsesforløbet synligt. Men den påvirker i dag ikke scoretallet. En ekspert kan derfor se høj mobilisering og samtidig en lav score, hvis jagtbarhed eller transport er dårlig.</p>\n<p>Fremtidig ændring skal vælge én af tre retninger: (a) indikator forbliver ren forklaring, (b) indikator bliver en kontrolleret gate/bonus, eller (c) hovedscoren ombygges til en egentlig procesmodel. Den må ikke snige sig ind som skjult dobbeltvægtning.</p>"},{"id":"retninger","title":"20. Retningskonventioner, kystankre og geometrisk audit","summary":"Sådan undgår systemet vendte pile og forkert lokal kystretning.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Sådan undgår systemet vendte pile og forkert lokal kystretning. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p>Vind er ''fra''; strøm er ''mod''; <code>onshoreDirectionDeg</code> er retningen fra hav mod land. UI-pile, rå komponentvektorer og scoreretning skal testes som én kæde.</p>\n<p>Bugtede zoner kan have flere retningankre. Systemet vælger den mindst offshore / mest gunstige relevante kystdel og dokumenterer valgmetoden. Det er en pragmatisk løsning, men kan overvurdere en stor zone, hvis kun en lille kystdel rammes gunstigt.</p>\n<p>Land- og havpunkter, kystlinje, ankre og <code>onshoreDirectionDeg</code> skal auditeres visuelt. Als Odde og Helberskov nord for Mariager Fjord er en fast regressionskontrol.</p>\n<div class=\"callout\"><strong>Ekspertpunkt E-15:</strong> Vurder om flere kystankre skal vægtes efter kystlængde, eksponering og transportforbindelse i stedet for at vælge bedste alignment (vinkel mellem strømmen og retningen ind mod land).</div><h3>Store og 180° rettelser</h3><p>Administratorens godkendte geometri er autoritativ. Hvis de oprindelige land- og havpunkter er byttet om, kan en korrekt rettelse vende pålandsretningen 180°. Systemet må advare om den store ændring, men må ikke blokere den alene på grund af vinklen. Havpunkt, landpunkt og onshoreDirectionDeg skal i stedet være indbyrdes konsistente, og samme værdi skal bruges af score, kort, forecast og debug.</p>"},{"id":"regler","title":"21. Fra faglig viden til versionsstyret scoreændring","summary":"Ekspertviden kan blive til versionsstyret modelkode, men aldrig til en direkte adminregel.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Regelværkstedet er taget ud af aktiv administration, fordi det ikke kan håndhæve modellens state, migration, lokale datagater og releasekrav. Ekspertviden går gennem en kontrolleret kode- og releaseproces.</div><p>En ændringshypotese beskriver påstand, mekanisme, geografi, jagtform, målbare betingelser, tidsvindue, forventet effekt, evidensklasse, tillid, kilde, testeksempler og modbeviser.</p>\n<ol>\n<li>Registrér observation eller kommentar uden scoreeffekt.</li>\n<li>Afgræns en testbar hypotese til relevante kyster og forløb.</li>\n<li>Omsæt en accepteret ændring til den autoritative integrerede kode og RDKS.</li>\n<li>Test positive, negative, grænse- og regressionsscenarier, herunder state, migration, transport-nul, wadersloft og lokal fail-closed.</li>\n<li>Kør kildegate og produktionsgates på PR''ens eksakte head.</li>\n<li>Merge, deploy og verificér den offentlige runtime.</li>\n<li>Kalibrér først senere mod repræsentative ture med både fund og nul-fund.</li>\n</ol>\n<p>Historiske centrale og lokale regeldokumenter bevares som revisionsspor, men indlæses ikke af admin, publiceres ikke og kan ikke påvirke RavScore.</p>"},{"id":"eksperimentdesign","title":"22. Hvordan ekspertudsagn og feltdata skal testes","summary":"Fra anekdote til reproducerbar forbedring.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Fra anekdote til reproducerbar forbedring. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p>En god test skal på forhånd definere hvad der forventes. Eksempel: ''Efter mindst 12 timer med bølger over X og derefter 3–12 timer med strøm mod land, stiger fundraten i zonegruppe Y sammenlignet med tilsvarende perioder uden indgående strøm.''</p>\n<p>Testdata skal indeholde både fund og nul-fund, jagtindsats, tidspunkt, zone, jagtform, vejrsnapshot, modelversion og eventuelle lokale observationer. Uden indsats kan et nul-fund ikke fortolkes sikkert.</p>\n<p>Data bør opdeles i udvikling og hold-out. En regel må ikke vurderes på de samme observationer, som blev brugt til at opfinde den. Små datasæt skal rapporteres med stor usikkerhed.</p>\n<p>Før en scoreændring bør man kontrollere kalibrering, rangering mellem zoner, falske toppe, geografisk bias og om forbedringen kun skyldes sæson eller brugeradfærd.</p>"},{"id":"data","title":"23. Datakilder, forecastintegritet og tidsserier","summary":"DMI-prioritet, fallback og hvorfor kontinuitet er vigtigere end kunstige 120 timer.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> DMI-prioritet, transparent fallback og ærlige huller er vigtigere end kunstige 120 timer. <span>Fagord forklares i teksten eller i ordlisten.</span></div><p>DMI er autoritativ dansk kilde, når data er tilgængelige og brugbare. Open-Meteo og andre godkendte kilder er komponentvis fallback. Hvert kildevalg skal fremgå af proveniensen.</p>\n<p>Vind, bølger, strøm, vandstand og temperatur behandles som separate tidsserier. Skalarserier kan kun tidsudjævnes inden for samme kilde-, model- og runkontrakt. Aktuel strøm interpoleres eller rekonstrueres ikke: DMI, Baltic NEMO og AMM15 skal levere et verificeret lokalt match ved den valgte time; kun de otte godkendte <code>dkss_lf</code>-proxyer må fastholde en allerede afledt tilstand i højst tre timer uden at opfinde en ny måling. Kildeskift må ikke skjule et spring eller blande modelkørsler.</p>\n<p>En horisont på cirka 118–119 sammenhængende timer er acceptabel. Det er bedre end at gentage sidste værdi for at ramme 120.</p>\n<p>Scoreforklaringen og den beskyttede diagnostik skal tilsammen bevare datakilde, modelkørsel, forecasttid, alder, fallback og mangler. Data ældre end friskhedsgrænsen må ikke vises som aktuelle.</p>"},{"id":"stationer","title":"24. DMI-vandstandsstationer, observationer og cachelivscyklus","summary":"Tre separate statuslag for hver station.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Tre separate statuslag for hver station. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p>En station har mindst tre statuslag:</p>\n<ol>\n<li><strong>Registerstatus:</strong> kendt, aktiv, historisk/inaktiv eller ukendt i DMI-registeret.</li>\n<li><strong>Observationsstatus:</strong> seneste måling, leverer nu, midlertidigt tavs eller aldrig observeret.</li>\n<li><strong>Prognose-/cachestatus:</strong> gyldig prognosecache, gyldig til, udløbet eller mangler.</li>\n</ol>\n<p>Samlet anvendelighed må ikke sættes til falsk, blot fordi en ny observation mangler. Hvis gyldig prognosecache findes, kan stationen fortsat anvendes til prognosen. Friske observationer har forrang; cache må kun bruges til dokumenteret udløb.</p>\n<p>Stationsregisteret er persistent. Opdagede stationer fjernes ikke ved en tom kørsel. Admin viser automatisk primær/sekundær station, afstand, vægt, valgmetode og eventuel override. Når administratoren vælger to andre stationer og bruger automatiske afstandsvægte, beregnes bidraget som invers afstand fra zonens datapunkt: den nærmeste station får størst vægt. De viste procenttal i admin følger samme princip som produktionens interpolation.</p><p>Manglende livscyklusfelter må ikke oversættes til påstande som “har aldrig leveret” eller “utilgængelig”. Admin skal i stedet vise, at observations-, cache- eller anvendelighedsstatus ikke er dokumenteret. Det ændrer ikke selve vandstandsdataene.</p>\n<p>Historiske/inaktive stationer skal være tydeligt markeret og må normalt ikke vælges uden advarsel. Hele registeret skal periodisk sammenholdes med DMI''s officielle liste.</p><h3>Automatisk kildevalg og interpolation</h3><p>RavRadar genberegner det automatiske valg fra de vandstandskilder, som er brugbare i den aktuelle kørsel. Et ældre routing-audit er dokumentation og må ikke skjule et nyere gyldigt valg. Systemet vælger normalt to kompatible kilder på hver sin side langs kysten. Kysttopologien bestemmer kandidaterne, mens interpolationsvægtene beregnes ud fra reel geografisk haversineafstand, præcis som ved administratoroverride. Hvis kun én kompatibel kilde findes, bruges den med 100 % vægt. Administratorens override fungerer fortsat som før.</p><h3>Prognosepunkter og kildeaudit</h3><p>Fysiske målestationer opdages i OceanObs <code>station</code>. DMI-prognosepunkter opdages i den særskilte <code>tidewaterstation</code>-collection. Efter hver vejrproduktion skrives en beskyttet audit med alle kilders type, prognosehorisont, gyldighed og routingberettigelse. Dermed kan Hals og andre punkter kontrolleres mod de faktisk modtagne serier.</p><h4>Sikkerhed for manglende data og første administratorvalg</h4><p>RavRadar skelner mellem en reel prognoseværdi på 0 cm og en manglende værdi. Manglende data må aldrig blive omdannet til 0 cm eller gøre en kilde brugbar. Når administratoren vælger en vandstandskilde i en zone, oprettes zonens routing med det samme, override bliver aktivt, og den valgte kilde vises rødt og kan gemmes centralt.</p>"},{"id":"feedback-ai","title":"25. Brugerfeedback, læringsgrundlag og AI","summary":"RavRadar tæller datadækning nu; scorekalibrering er fortsat låst.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Brugerens ture kan gøre beslutningsgrundlaget bedre, men systemet ændrer ikke selv RavScore.</div><p>En indsendt tur knyttes til zone, kystdel, jagtform, start/sluttid, søgeindsats, fund eller nul-fund samt det gemte vejr- og scoresnapshot for turens tidspunkt. Model-id, stateversion og profilbinding bevares ved migration; persondata og samtykke følger særskilte privatlivskrav.</p>\n<p>Kontoens turlog viser turens oprindelige, uforanderlige modelbinding og status. DTO''en indeholder kun den privacy-sikre eksakte <code>model_binding</code>, ikke rå vejrfeatures. Siden udleder aktuelle, historiske og ikke-kalibreringsegnede poster på ny mod det aktive kanoniske modeloverlay og stoler ikke på en gammel serverlabel. Under integreret drift er eksakt integrerede ture aktuelle, mens Candidate G-ture er historiske og ikke egnede. Under en Candidate G-rollback bliver eksakt Candidate G aktuelle, men fortsat <code>calibration_eligible=false</code>, mens integrerede ture vises som historiske. Ingen gemt tur ommærkes.</p>\n<p>Nye schema-3-ture accepteres kun med RavRadars eksakte 11-feltsbinding for enten den integrerede model eller den forseglede Candidate G-rollback. En integreret tur kan kun være kalibreringsegnet, når faktisk zone og kystdel matcher prognosen; Candidate G er altid ikke-kalibreringsegnet. En ukendt eller forfalsket modelbinding afvises både før submit og i databasen.</p>\n<p>Læringsmodulet er <strong>coverage-only</strong>: det tæller brugbare ture, fund, nul-fund, spredning, jagtformer, søgeindsats og snapshotkobling. <code>calibrationLocked=true</code>, og modulet returnerer ingen automatiske scoreforslag. Det ændrer hverken vægte, zoner, tærskler eller den offentlige model.</p>\n<p>Fremtidig kalibrering kræver repræsentative ture med fund og nul-fund, kendt søgeindsats, korrekt model-/prognosekobling, tidsmæssig og geografisk hold-out, særskilt RDKS-beslutning, kodeændring og fuld releasekontrol. Brugerfund er ikke en leveranceforudsætning for den mekaniske kandidat, men uden dem må den ikke kaldes empirisk mere fundpræcis.</p><h3>Offentlige sprog og Spørg RavRadar – 4.0.291</h3><p>Den offentlige flade bruger ét centralt tekstkatalog til dansk, tysk og engelsk. Admin-, ekspert- og interne flader forbliver danske.</p><p>Spørg RavRadar afviser uvedkommende og interne spørgsmål før ekstern model. Bedste sted, bedste tidspunkt og konkret RavScore skal altid komme deterministisk fra den eksakt bundne offentlige RavScore-model og må ikke opfindes af AI. Konto-/turdata, persondata, præcis position, rå vektorer og interne diagnoser må aldrig sendes til modellen.</p><p>Cloudflare <code>@cf/openai/gpt-oss-20b</code> bruges kun gennem den dataminimerede Edge-vej med domænegates, CORS, inputgrænser, rate limits, timeout, struktureret output-/evidensvalidering og lokal fallback. Ingen leverandørcredential findes i browseren.</p>"},{"id":"admin-sikkerhed","title":"26. Administration, Supabase og ekspertrettigheder","summary":"Hele den værdifulde adminfunktionalitet ligger bag adgangskontrol.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Hele den værdifulde adminfunktionalitet ligger bag adgangskontrol.</div><p>GitHub Pages kan udlevere den statiske admin-skal, men uden gyldig Supabase-session og rettigheder må den ikke vise eller hente beskyttede data. Sikkerheden ligger i Supabase JWT/secret-serverflow og Row Level Security – ikke i at skjule et link.</p>\n<p>Håndbogen er et beskyttet admin-dokument. Eksperten skal have <code>admin_access</code> og <code>handbook_view</code>; kommentarer kræver <code>handbook_review</code>. Geometri, vandstandsrouting, retning, diagnostik, brugeradministration og systemadministration har egne rettigheder.</p>\n<p>Det tidligere regelværk bevares som historik, men admin indlæser eller publicerer det ikke, og det kan ikke påvirke RavScore. Model-id, stateversion, profil og cutover ændres kun gennem kode, RDKS og releasegates. Service role / <code>sb_secret</code> må kun findes som serverhemmelighed og aldrig i browserkode eller ZIP.</p>\n<h3>Privat besøgsstatistik – 4.0.216</h3><p>Kun samlede dagstal gemmes. Der gemmes ingen rå besøgsliste, IP-adresse, præcis placering, browserfingeraftryk eller stabil besøgsidentitet. Tællingen kan ikke blokere kort eller vejr.</p>","content":"\n\nFree-kvoten beskyttes ved kun at hente nødvendige adminnøgler og springe identiske maskinoutputs over. Menneskeligt redigeret geometri og routing beholder bounded rollback; store udskiftelige diagnostikker beholder kun deres aktuelle kopi. Oprydning starter med read-only audit og sletter aldrig aktuel admin_documents-sandhed eller de bevarede historiske regeldokumenter.\n\nNye <code>sb_secret_</code>-nøgler sendes kun som <code>apikey</code>. Hvis Supabases interne nøgleoversættelse én enkelt gang giver HTTP 401 / <code>PGRST303</code>, prøver serverkaldet én gang mere efter kort ventetid. Alle andre eller gentagne adgangsfejl stopper fail-closed. Reglen gælder både Node-roundtrips og Python-hydreringen før DMI; GitHub Actions må ikke fortsætte på historiske repositorydata efter en central læsefejl. Nøgler, komplette request-URL''er og rå admin-data må ikke ende i rapporter eller logs.\n\nBeskyttet synkronisering må ikke fortolke en manifestlæsefejl som et manglende manifest. Den stopper i stedet for at genskrive uændrede dokumenter. En målrettet privat kontrol kan genbruge et eksisterende QA-artifact til central create/read/update/delete/rollback uden ny DMI og uden deployrettighed.\n\nForsinkede Leaflet-kortopgaver afbrydes ved faneskift. Et kort må kun initialiseres, hvis den aktive fane og dens kortcontainer stadig findes."},{"id":"diagnostik","title":"27. Diagnostik, sundhed og faglig audit","summary":"Fra datakilde til slutscore uden skjulte spring.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Fra datakilde til slutscore uden skjulte spring. <span>Fagord forklares i teksten eller i ordlisten.</span></div><p>RavRadar skelner mellem brugerprognosens komplethed, DMI-dækning, acquisition, konvertering, horisont, observationer, cache og fallback. En grøn brugerprognose kan eksistere samtidig med degraderet DMI-status.</p>\n<p>Runtime-diagnostik, stationaudit, cacheaudit og implementeringsaudit er beskyttede admindokumenter. De må ikke ligge som offentlige JSON-adresser.</p>\n<p>En faglig scoreaudit skal kunne følge: rå kilder og proveniens → valgt tid → lokalt punkt og kystgeometri → dataminimeret historisk tilstand → søgeforhold, transport og rav i bevægelse → vægtningen 20/50/30 → transport-nul-regel, wadersloft og lokal fail-closed → offentlig slutscore og forklaring. Der indgår ingen adaptiv justering eller adminregel.</p>"},{"id":"workflow-inventory-4-0-121","title":"27a. Aktivt GitHub Actions-inventar","summary":"Kun update-and-deploy.yml er RavRadars workflow; afsluttede diagnostikworkflows er fjernet.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar har ét repository-ejet workflow.</div><p><code>.github/workflows/update-and-deploy.yml</code> bygger produktionsdata, kører releasekontrollerne og deployer GitHub Pages.</p><p><code>schedule-test.yml</code> var en afsluttet diagnose af GitHubs interne schedule, mens <code>pages-microtest.yml</code> var en manuel minimal Pages-test. Ingen aktiv test-, release- eller recoveryprocedure brugte dem, og mikrotesten kunne publicere til samme <code>github-pages</code>-miljø som produktionen. Derfor blev begge fjernet i 4.0.121.</p><p><code>pages-build-deployment</code>, som kan ses i GitHub, er GitHubs egen Pages-mekanisme og ikke en workflowfil i RavRadar.</p>"},{"id":"release","title":"28. Release Governance og RDKS-gate","summary":"Releasekrav og workflowinventar: Kun update-and-deploy.yml er RavRadars aktive workflow; historiske diagnostikworkflows er fjernet i 4.0.121.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Den bindende proces, som skal forhindre gentagelse af 4.0.56-forløbet. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p>En version er ikke installationsklar, før præcis det pakkede indhold har bestået hele valideringen og Release Gate. Kodegennemgang alene er ikke nok.</p>\n<p>Obligatorisk rækkefølge:</p>\n<ol>\n<li>Brug seneste uploadede projekt som eneste arbejdskilde.</li>\n<li>Kortlæg samtaledelta, aktive RDKS-krav og nuværende implementering.</li>\n<li>Opdater kode, håndbog, RDKS, changelog og versionsfelter samlet.</li>\n<li>Kør generatorer i samme rækkefølge som GitHub Actions.</li>\n<li>Kør hele <code>npm run validate</code>.</li>\n<li>Kør <code>npm run release:gate</code>.</li>\n<li>Byg ZIP med <code>npm run release:package</code>.</li>\n<li>Auditér ZIP for <code>.git</code>, secrets, caches og manglende workflowfiler.</li>\n<li>Efter push: verificér den faktiske GitHub Actions-kørsel som grøn.</li>\n<li>Ved fejl: gennemgå hele den resterende pipeline samlet; undgå manuelle lapninger én fejl ad gangen.</li>\n</ol>\n<p>GitHub Secrets og Supabase-installation bevares uden for ZIP. En ny ZIP må ikke kræve genoprettelse af eksisterende secrets, medmindre en bevidst nøglemigration er dokumenteret.</p><h3>Deployisolering fra 4.0.114</h3><p>Data, validering og artifact bygges i jobbet <code>build-and-prepare</code>. Selve GitHub Pages-publiceringen sker i det separate job <code>deploy-pages</code>. Kun deployjobbet bruger miljøet <code>github-pages</code> og Pages-skriverettigheder.</p><p>Hvis Pages fejler efter et færdigt build, kan <strong>Re-run failed jobs</strong> genkøre deploymentet mod det eksisterende artifact uden ny DMI-kørsel. En kode-push eller tvungen release kan prioritere sig foran en ældre almindelig vejropdatering. RavScore og marine auditkrav ændres ikke.</p>"},{"id":"domaene","title":"29. Overgang til ravradar.dk","summary":"Eget domæne foran GitHub Pages og Supabase.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Eget domæne foran GitHub Pages og Supabase. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p>Brugerne skal besøge <code>ravradar.dk</code>, selv hvis GitHub Pages fortsat hoster frontend. Projektet skal derfor bruge relative appstier, korrekt manifest og service worker, og undgå hardcodede GitHub Pages-adresser.</p>\n<p>Før domænet aktiveres skal DNS, GitHub Pages custom domain, HTTPS, <code>www</code>-strategi, Supabase Site URL og redirect-URLs være afklaret. Admin- og loginflow skal testes på både primært domæne og valgt redirectdomæne.</p>\n<p><code>CNAME</code> må først tilføjes, når DNS og Supabase redirects er klar. Ellers kan login eller deployment låses i en halvkonfigureret tilstand.</p>"},{"id":"ekspertmatrix","title":"30. Ekspertens arbejdsplan – det vil vi gerne have din vurdering af","summary":"En praktisk og letforståelig liste over de vigtigste spørgsmål, hvor RavRadar har brug for ekspertens erfaring.","body":"<div class=\"plain-language-intro\"><h3>Hvad er formålet?</h3><p>Dette er ekspertens arbejdsplan for den integrerede releasekandidat. Vi vil have konkrete eksempler, geografisk afgrænsning, målbare tegn og mulige modbeviser. Intet svar ændrer automatisk RavScore.</p></div><section class=\"expert-work-item\"><h3>E-01 – Har størrelse og form betydning?</h3><p><strong>I dag:</strong> Modellen behandler rav som én samlet type og har ingen partikelstørrelsesmodel.</p><p><strong>Spørgsmål:</strong> Hvilke størrelser og former reagerer anderledes, og hvordan kan det registreres?</p></section><section class=\"expert-work-item\"><h3>E-02 – Hvor ligger ravet før mobilisering?</h3><p><strong>I dag:</strong> RavRadar beregner ikke et primært eller sekundært ravlager.</p><p><strong>Spørgsmål:</strong> Hvilke observerbare tegn skelner et tilgængeligt, tømt eller genopfyldt lager?</p></section><section class=\"expert-work-item\"><h3>E-03 – Beskriver bølgerne mobiliseringen rigtigt?</h3><p><strong>I dag:</strong> <code>Hs² × T</code> bygger én tilstand med cirka fire timers opbygning og 48 timers halveringstid.</p><p><strong>Spørgsmål:</strong> Hvornår ændrer periode, retning, varighed eller bund dette forløb?</p></section><section class=\"expert-work-item\"><h3>E-04 – Bygger og falder transportbeviset rigtigt?</h3><p><strong>I dag:</strong> 0,03 m/s er dødzone, 0,15 m/s fuld styrke, indgående giver +10 og udgående -8 pr. effektiv time. De første 24 timer vægtes fuldt og evidens cosinusdæmpes til nul ved 48. Et langt stærkt udgående forløb kan gøre transportleddet 0, men nulstiller ikke hele RavScore.</p><p><strong>Spørgsmål:</strong> Hvor er tærskler, tempo eller tidsvægt for simple?</p></section><section class=\"expert-work-item\"><h3>E-05 – Virker waders-kurven?</h3><p><strong>I dag:</strong> Søgeforhold er 100 til 6 m/s og 0 ved 15 m/s med blødt bølgefradrag. Det er søgeeffektivitet, ikke sikkerhed.</p><p><strong>Spørgsmål:</strong> Hvordan ændrer læ, eksponering og kysttype den praktiske søgning?</p></section><section class=\"expert-work-item\"><h3>E-06 – Hvad betyder faldende vand?</h3><p><strong>I dag:</strong> Vandstand giver 0 direkte scorepoint og bestemmer ikke strømretningen. Faldende vand kan falde sammen med søværts transport af noget mobilt rav. Lavere vand kan blotlægge allerede afleveret eller fastholdt rav bag revler, men beviser ikke fysisk koncentration.</p><p><strong>Spørgsmål:</strong> Hvilke lokale profiler, faser og tegn afgør, hvilken virkning der dominerer?</p></section><section class=\"expert-work-item\"><h3>E-07 – Kan rav komme langs kysten?</h3><p><strong>I dag:</strong> Modellen bruger gridstrømmens lokale kystnormale komponent og følger ikke et netværk mellem nabozoner.</p><p><strong>Spørgsmål:</strong> Hvor skaber langskyst transport konvergens, retention eller bypass?</p></section><section class=\"expert-work-item\"><h3>E-08 – Hvornår føres rav ud, og hvornår bliver det?</h3><p><strong>I dag:</strong> Gridstrømmen er ikke undertow, feeder-/langskyststrøm eller ripstrøm. Den fysiske sidste mile er uopløst; releasekandidaten bruger kun afgrænset kausal energivægtet wave-approach med fire timers halveringstid og en ældre hale til at dæmpe allerede eksisterende supply én gang.</p><p><strong>Spørgsmål:</strong> Beskriv steder og faser med eksport, recirkulation, revlefangst eller genkomst, og hvilke batymetri-/surfzonedata der kræves.</p></section><section class=\"expert-work-item\"><h3>E-09 – Hvilket ledsagemateriale er et godt tegn?</h3><p><strong>I dag:</strong> Tang, skaller og opskyl giver ingen scorepoint.</p><p><strong>Spørgsmål:</strong> Hvilke friske felttegn adskiller ny aflejring fra gammel omlejring?</p></section><section class=\"expert-work-item\"><h3>E-10 – Hvordan virker tang og ålegræs?</h3><p><strong>I dag:</strong> Grove vegetationsflag er kontekst uden statisk bonus.</p><p><strong>Spørgsmål:</strong> Hvornår er vegetation transportør, fælde eller skjul?</p></section><section class=\"expert-work-item\"><h3>E-11 – Hvilke kystformer betyder mest?</h3><p><strong>I dag:</strong> Bund, dybde, render, revler og automatisk stedegnethed er udeladt, fordi lokal batymetri mangler.</p><p><strong>Spørgsmål:</strong> Hvilke forhold kan forklares eller senere testes uden automatiske bonusser?</p></section><section class=\"expert-work-item\"><h3>E-12 – Hvor længe virker en hændelse?</h3><p><strong>I dag:</strong> Gridstrøm har 24 timers fuld vægt og fade til 48; mobilisering har sit eget 4/48-forløb.</p><p><strong>Spørgsmål:</strong> Hvad afbryder de to hukommelser ved forskellige kysttyper?</p></section><section class=\"expert-work-item\"><h3>E-13 – Hvor bliver ravet lagt op?</h3><p><strong>I dag:</strong> RavRadar beregner ikke strandingslinje, aflejring eller retention.</p><p><strong>Spørgsmål:</strong> Hvilke forløb giver små, tydelige og jagtbare koncentrationer?</p></section><section class=\"expert-work-item\"><h3>E-14 – Hvornår er det let at søge?</h3><p><strong>I dag:</strong> Waders bruger vind og blødt bølgefradrag; strand har ikke wadersloftet. RavScore er ikke en sikkerhedsgodkendelse.</p><p><strong>Spørgsmål:</strong> Hvordan påvirker sigt, mørke, bund og lokalt læ søgeeffektiviteten?</p></section><section class=\"expert-work-item\"><h3>E-15 – Beskriver kystdelene stedet?</h3><p><strong>I dag:</strong> 210 zoner og 673 kystdele bruger fælles ranglistekontrakt uden at give fler-del-zoner urimelig fordel.</p><p><strong>Spørgsmål:</strong> Matcher delene og retningerne de steder, hvor der faktisk søges?</p></section><section class=\"expert-work-item\"><h3>E-16 – Kan næsten parallel strøm føre rav ind?</h3><p><strong>I dag:</strong> Næsten parallel gridstrøm giver kun en lille kystnormal komponent.</p><p><strong>Spørgsmål:</strong> Hvornår gør bølgedrevet langskyst transport den god, neutral eller dårlig?</p></section><section class=\"expert-work-item\"><h3>E-17 – Hvor meget skal historikken tælle?</h3><p><strong>I dag:</strong> Gridstrøm vægtes 24/48 timer; bølger bruger et særskilt 4/48-forløb med stram missingregel.</p><p><strong>Spørgsmål:</strong> Hvornår fastholder modellen en gammel hændelse for længe eller for kort?</p></section><section class=\"expert-work-item\"><h3>E-18 – Er gridstrømmen den strøm ravet mærker?</h3><p><strong>I dag:</strong> RavRadar bruger dokumenteret DMI-, Copernicus- eller godkendt proxyproveniens ved havpunktet.</p><p><strong>Spørgsmål:</strong> Hvor repræsenterer gridværdien den kystvendte transport rimeligt, og hvor afviger bundnær strøm og surfzone?</p></section><section class=\"expert-work-item\"><h3>E-19 – Skal kysttyper have forskellige priorer?</h3><p><strong>I dag:</strong> 20/50/30, 0,03/0,15 og +10/-8 bruges landsdækkende med lokale kystretninger.</p><p><strong>Spørgsmål:</strong> Hvilke målbare regionale forskelle kan efterprøves og modbevises?</p></section><section class=\"expert-work-item\"><h3>E-20 – Hvordan efterprøver vi modellen?</h3><p><strong>I dag:</strong> Mekanik og regressioner er testet, men modellen er ikke dokumenteret empirisk mere fundpræcis.</p><p><strong>Spørgsmål:</strong> Hvilke repræsentative fund, nul-fund og feltforsøg bør bruges senere?</p></section><section class=\"expert-work-item\"><h3>E-21 – Hvad skal registreres ved en tur?</h3><p><strong>I dag:</strong> Ture kan gemme zone, kystdel, jagtform, tid, indsats, fund/nul-fund, dataminimeret snapshot og modelbinding; GPS og rute gemmes ikke.</p><p><strong>Spørgsmål:</strong> Hvilke få ekstra oplysninger giver mest læring uden at skade deltagelse eller privatliv?</p></section><section class=\"expert-work-item\"><h3>E-22 – Hvordan virker genmobilisering?</h3><p><strong>I dag:</strong> Ét bølgeforløb dækker både mulig ny frigivelse og genmobilisering; modellen kender ikke lagerets oprindelse.</p><p><strong>Spørgsmål:</strong> Hvilke tegn skelner genmobilisering, geneksponering og ny frigivelse?</p></section>"},{"id":"scenarier","title":"31. Gennemregnede faglige scenarier","summary":"Eksempler der viser modelens styrker og svagheder.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Eksemplerne viser både den integrerede kandidats styrker og dens kendte begrænsninger. De er ikke fundgarantier.</div><h4>Scenario A – stærk indgående gridstrøm efter høj bølgeenergi, roligt nu</h4>\n<p>Tidligere høje bølger har bygget mobilisering op. Gridstrømmen har derefter en tydelig komponent mod kystzonen og bygger transportbeviset. Lav vind giver gode waders-søgeforhold. Modellen rangerer denne dokumenterede rækkefølge højt uden at påstå kendt lager eller sidste-mile-levering.</p>\n<h4>Scenario B – høj bølgeenergi nu, gridstrøm væk fra land</h4>\n<p>Rav kan være sat i bevægelse, mens waders-søgeforholdene falder. Udadgående gridstrøm reducerer transportbeviset med op til otte point pr. effektiv time. Et langt stærkt udgående forløb kan gøre transportleddet 0, men nulstiller ikke hele RavScore og beviser ikke, at alt rav er væk.</p>\n<h4>Scenario C – roligt vejr uden nylig bølgeenergi</h4>\n<p>Søgeforholdene kan være gode, men mobilisering og transport lave. Der kan stadig ligge gammelt rav; modellen observerer ikke lageret.</p>\n<h4>Scenario D – skrå strøm ved en odde</h4>\n<p>Den lokale komponent mod land kan være lille, selv om materiale transporteres langs kysten. Hvis det samles på læsiden, kan modellen undervurdere stedet; hvis det passerer odden, kan den overvurdere det. Gridstrømmen er ikke den bølgedrevne langskyststrøm.</p>\n<h4>Scenario E – gammel browsercache</h4>\n<p>Data ældre end friskhedsgrænsen må ikke vises som aktuelle. Siden skal hente friske data eller vise tydelig utilgængelighed.</p>\n<h4>Scenario F – faldende vand ved en revlekyst</h4>\n<p>Faldende vand bestemmer ikke strømretningen, men kan falde sammen med verificeret søværts gridstrøm og mulig søværts transport af noget mobilt rav. Lavere vand kan samtidig blotlægge rav, som allerede er afleveret eller fastholdt bag revlen, uden at bevise fysisk koncentration. Uden lokal batymetri og surfzonemodel giver vandstand ingen scorepoint.</p>\n<h4>Scenario G – tidligere indskyllet rav sættes i bevægelse igen</h4>\n<p>Der behøver ikke have været en ny stor storm. Moderate bølger kan bygge mobilisering igen, mens gunstig gridstrøm bygger transportbevis mod kystzonen. Det er en faglig mulighed, ikke et lagerbevis.</p>"},{"id":"kilder","title":"32. Faglige hovedkilder, analogier og læsevej","summary":"Kilder bag procesforståelsen og deres begrænsninger.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Kilder bag procesforståelsen og deres begrænsninger. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p>Følgende kilder understøtter den generelle procesforståelse. De validerer ikke automatisk RavRadars numeriske tærskler:</p>\n<ul>\n<li>Chubarenko, I. m.fl. (2017), *Microplastics in sea coastal zone: Lessons learned from the Baltic amber*. Environmental Pollution 224, DOI <a href=\"https://doi.org/10.1016/j.envpol.2017.01.085\">10.1016/j.envpol.2017.01.085</a>. Ravspecifik kilde om mulig gentagen migration mellem strand og undervandsskråning; forfatterne fremhæver, at systematisk ravmonitorering mangler. Den fastsætter ingen dansk tærskel eller universel retningseffekt.</li>\n<li>Aagaard, T., Black, K.P. &amp; Greenwood, B. (2002), <em>Cross-shore suspended sediment transport in the surf zone: a field-based parameterization</em>. Marine Geology 185, DOI <a href=\"https://doi.org/10.1016/S0025-3227(02)00193-7\">10.1016/S0025-3227(02)00193-7</a>. Viser land- og søværts nettotransport som funktion af lokal bølge-, strøm-, dybde- og hældningsdynamik; ingen ravfaktor.</li>\n<li>Jalón-Rojas, I. m.fl. (2025), <em>A wave-resolving two-dimensional vertical Lagrangian approach to model microplastic transport in nearshore waters</em>. GMD 18, DOI <a href=\"https://doi.org/10.5194/gmd-18-319-2025\">10.5194/gmd-18-319-2025</a>. Mekanistisk analogi for Stokes-drift, undertow og partikelposition; ikke ravkalibrering.</li>\n<li>Lofty, J. m.fl. (2023), <em>Microplastic and natural sediment in bed load saltation: Material does not dictate the fate</em>. Water Research 243, DOI <a href=\"https://doi.org/10.1016/j.watres.2023.120329\">10.1016/j.watres.2023.120329</a>. 5 mm-rav omkring 1 041 kg/m³ blev målt som lavdensitets bedload/saltation i åbent kanalflow; ikke dansk surfzonevalidering.</li>\n<li>Davidson, B. m.fl. (2023), *Beaching model for buoyant marine debris in bore-driven swash (bølgeopskyl på stranden)*. Flow. Laboratorie-/modelarbejde om partikelstranding i swash og betydningen af partikelinerti og indgangsbetingelser. https://www.cambridge.org/core/journals/flow/article/beaching-model-for-buoyant-marine-debris-in-boredriven-swash/DBBD345FD31CCA10CC21F29744EA1A57</li>\n<li>Isachenko, I. m.fl. (2023), *Beach-cast appearance on the tide-less sea shore*. Estuarine, Coastal and Shelf Science. Relevant for post-storm beach-cast i det sydøstlige Østersøområde. https://www.sciencedirect.com/science/article/abs/pii/S0272771423000094</li>\n<li>Kim, S. m.fl. (2024), *Short-term buoyant microplastic transport patterns driven by surf zone processes*. Marine Pollution Bulletin. Understøtter betydningen af brydning, orbitalbevægelse og surfzoneprocesser for lavdensitetspartikler. https://www.sciencedirect.com/science/article/abs/pii/S0025326X2400225X</li>\n<li>Kerpen, N.B. m.fl. (2024), *Microplastic retention (tilbageholdelse) in marine vegetation canopies under oscillatory flow*. Science of the Total Environment. Analogikilde for retention i vegetation. https://www.sciencedirect.com/science/article/pii/S004896972307910X</li>\n<li>Chen, W. m.fl. (2023), *A review of practical models of sand transport in the swash zone*. Coastal Engineering. Oversigt over swashturbulens, sedimentadvektion, infragravitetsbølger, infiltration og strandhældning. https://research.utwente.nl/en/publications/a-review-of-practical-models-of-sand-transport-in-the-swash-zone/</li>\n<li>USGS, *Sediment Transport in Coastal Environments*. Officiel oversigt over bølge-, strøm- og strukturpåvirket kysttransport. https://www.usgs.gov/centers/pcmsc/science/sediment-transport-coastal-environments</li>\n<li>USGS glossary, definition af longshore current/transport. https://pubs.usgs.gov/of/2008/1206/html/glossary.html</li>\n</ul>\n<p>Kilder om plast bruges kun som mekanistisk analogi. Ravets egen transport skal så vidt muligt valideres med ravspecifik litteratur og lokale feltobservationer.</p>"},{"id":"ordbog","title":"33. Ordbog og faste begreber","summary":"Centrale ord, som skal bruges ens i UI, kode og ekspertkommunikation.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Centrale ord, som skal bruges ens i UI, kode og ekspertkommunikation. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><ul>\n<li><strong>alignment (vinkel mellem strømmen og retningen ind mod land):</strong> matematisk mål for hvor godt en bevægelsesretning passer med lokal pålandsretning.</li>\n<li><strong>Canonical UTC-time:</strong> fast time uden minutforskydning, brugt ved merge.</li>\n<li><strong>Cap/loft:</strong> maksimal tilladt delscore ved en begrænsende tilstand.</li>\n<li><strong>Fallback:</strong> sekundær datakilde ved manglende/ugyldig primær kilde.</li>\n<li><strong>Frigivelse:</strong> mobilisering fra bund, sediment, vegetation eller depot.</li>\n<li><strong>Jagtbarhed:</strong> praktisk mulighed for at finde rav.</li>\n<li><strong>OnshoreDirectionDeg:</strong> lokal retning fra hav mod land.</li>\n<li><strong>Observation:</strong> faktisk måling.</li>\n<li><strong>Prognose:</strong> modelberegnet fremtidig værdi.</li>\n<li><strong>Cache:</strong> tidligere hentet data, som stadig er dokumenteret gyldig.</li>\n<li><strong>retention (tilbageholdelse):</strong> midlertidig eller længerevarende fastholdelse.</li>\n<li><strong>RDKS:</strong> RavRadar Decision & Knowledge System.</li>\n<li><strong>swash (bølgeopskyl på stranden):</strong> området der gentagne gange overskylles og tørlægges af bølgeopskyl.</li>\n<li><strong>undertow (returstrøm under bølgerne):</strong> nettoudadgående returstrøm under bølger i surfzonen.</li>\n<li><strong>Override:</strong> administratorens bevidste erstatning af automatik.</li>\n<li><strong>Regression:</strong> tidligere løst fejl, som vender tilbage.</li>\n</ul>"},{"id":"fluidmekanik","title":"34. Fluidmekanisk grundlag: kræfter, skærspænding og turbulens","summary":"De fysiske størrelser, der forbinder vejrdata med mulig partikelbevægelse.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> De fysiske størrelser, der forbinder vejrdata med mulig partikelbevægelse. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p>RavRadar bruger i dag empiriske scoregrænser. For at kunne forbedre dem skal man forstå de underliggende kræfter.</p>\n<h3>34.1 Neddykket vægt</h3><p>Den nedadrettede effektive vægt bestemmes af forskellen mellem partiklens og vandets densitet. For rav er denne forskel lille sammenlignet med mineralsk sand. Derfor kan en mindre hydrodynamisk kraft være tilstrækkelig til at reducere bundkontakten, men form og mekanisk indlejring kan dominere.</p>\n<h3>34.2 Drag og løft</h3><p>Strøm omkring en partikel giver drag i strømmens retning og kan give løft gennem trykforskelle og turbulente impulser. Kræfterne afhænger omtrent af vandets densitet, det projicerede areal og hastigheden i anden. En fordobling af lokal hastighed kan derfor give en langt større belastning end en lineær score antyder.</p>\n<h3>34.3 Bundskærspænding</h3><p>Bundskærspænding er den tangentiale belastning, som vandbevægelsen overfører til bunden. Ved kombinerede bølger og strøm kan den maksimale belastning være væsentligt større end bidragene hver for sig. En fysisk mobiliseringsmodel bør sammenligne den kombinerede belastning med en kritisk værdi for den relevante partikel og bundtilstand.</p>\n<h3>34.4 Turbulens</h3><p>Turbulens skaber kortvarige vertikale og horisontale hastighedsfluktuationer. En timegennemsnitlig strøm på 0,2 m/s fortæller derfor ikke, hvor store de enkelte løfteimpulser er. Bølgebrydning og vortices ved revler kan være afgørende.</p>\n<div class=\"model-gap\"><strong>Modelhul:</strong> RavRadar beregner ikke bundskærspænding, friktionshastighed eller turbulensintensitet. Disse er kandidater til en fremtidig fysisk delmodel, hvis nødvendige input kan skaffes robust.</div>"},{"id":"dimensionsloese-tal","title":"35. Partikelmekanik og dimensionsløse tal","summary":"Hvordan Shields-, Reynolds- og Rouse-tænkning kan bruges uden at foregive falsk præcision.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Hvordan Shields-, Reynolds- og Rouse-tænkning kan bruges uden at foregive falsk præcision. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><h3>35.1 Shields-parameteren</h3><p>Shields-parameteren sammenholder bundskærspænding med partiklens neddykkede vægt og størrelse. Den bruges normalt til mineralsk sediment. For rav kan den give en struktureret ramme, men standardkurverne er ikke direkte valideret for uregelmæssige, lavdensitetsstykker.</p>\n<h3>35.2 Partikel-Reynolds-tal og dragregime</h3><p>Dragkoefficienten afhænger af strømregimet omkring partiklen. Små glatte stykker og store uregelmæssige stykker kan derfor ikke antages at have samme respons, selv når deres densitet er ens.</p>\n<h3>35.3 Synkehastighed og Rouse-lignende tænkning</h3><p>For sediment bruges forholdet mellem synkehastighed og turbulent blanding til at vurdere, om partikler holdes i suspension. Ravets lave synkehastighed kan gøre kortvarig suspension sandsynlig, men der mangler systematiske målinger fordelt på størrelse, form, saltindhold og biofilm.</p>\n<h3>35.4 Praktisk anvendelse i RavRadar</h3><p>Disse tal skal i første omgang bruges til at formulere testbare hypoteser og laboratorieforsøg – ikke til at erstatte scoremotoren med uprøvede formler. En ny fysisk parameter må først aktiveres, når den kan beregnes stabilt og giver bedre hold-out-resultater.</p>\n<div class=\"callout\"><strong>Supplerende spørgsmål til E-01:</strong> Definér et realistisk forsøgsprogram for kritisk mobilisering og synkehastighed for repræsentative ravklasser.</div>"},{"id":"boelgespektrum","title":"36. Bølgespektrum, periode, retning og varighed","summary":"Hvorfor signifikant bølgehøjde alene kan skjule væsentlige forskelle.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Signifikant bølgehøjde alene skjuler periode, retning, varighed og lokal brydning.</div><p>En havtilstand består af mange bølgekomponenter. Signifikant bølgehøjde opsummerer højden, men ikke hele spektret.</p>\n<h3>36.1 Periode</h3><p>Lange bølger påvirker typisk bunden på større dybde og kan skabe en anden surfzone end korte vindbølger. Den integrerede model bruger derfor både bølgehøjde og periode i den timevise <code>Hs² × T</code>-proxy.</p>\n<h3>36.2 Retning og kysteksponering</h3><p>Bølgeretning skal fysisk sammenholdes med kystnormal, revler og læ, men en offshore modelretning kan refrakteres før stranden. RavRadar giver derfor ikke bølgeretning sidste-mile-point.</p>\n<h3>36.3 Fetch og varighed</h3><p>Lokal vind over kort fetch kan give stejle, korte bølger, mens fjern swell kan ankomme efter vindfald. Mobilisering bygges med cirka fire timers og aftager med cirka 48 timers halveringstid, så en kort spids ikke bliver lig med vedvarende energi.</p>\n<h3>36.4 Begrænsning</h3><p>RavRadar bruger ikke hele spektret og modellerer ikke lokal refraktion, revlebrydning eller bundbelastning. En mere detaljeret model kræver robuste input, lokal batymetri og hold-out-evidens; den må ikke indføres som falsk landsdækkende præcision.</p>"},{"id":"strandtilstande","title":"37. Strandprofiler, revler og morfodynamiske tilstande","summary":"Hvordan bundformen kan ændre den samme vejrprognoses virkning.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Hvordan bundformen kan ændre den samme vejrprognoses virkning. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p>Strande er ikke statiske skrå flader. Revler, render, cusps, erosionskanter og strandhældning ændres under storme og rolige perioder.</p>\n<h3>37.1 Revler som både lager og barriere</h3><p>En revle kan lagre let materiale, bryde bølger og skabe en roligere landværts zone. Et brud i revlen kan koncentrere udadgående strøm. Derfor kan samme revle både fremme aflejring og skabe eksport afhængigt af placering.</p>\n<h3>37.2 Erosiv og akkretiv profil</h3><p>Højenergiforhold kan flytte sand offshore og danne eller forstærke revler; roligere bølger kan føre sediment landværts. Rav behøver ikke følge sandets nettotransport, men bundprofilens ændring bestemmer, hvilke gamle lag og lommer der åbnes.</p>\n<h3>37.3 Databehov</h3><p>RavRadar har i dag statisk kystgeometri og generelle kystegenskaber. Dynamisk bathymetri er ikke tilgængelig i prognoseopløsning. Brugerobservationer af nye render, erosionskanter og tanglinjer kan derfor være værdifulde som kortlivede zonetilstande.</p>\n<div class=\"callout\"><strong>Uddybning af E-11:</strong> Angiv hvilke morfologiske observationer en ravjæger realistisk kan registrere, og hvor længe de bør påvirke modellen.</div>"},{"id":"kildelager-model","title":"38. Kildelager, udtømning og genopfyldning","summary":"En konceptuel model for noget den nuværende score ikke kan se.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En konceptuel model for noget den nuværende score ikke kan se. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p>Vejr beskriver transportkapacitet, men fund kræver tilgængeligt rav. Derfor bør RavRadar på sigt skelne mellem en hurtig hydrodynamisk tilstand og et langsomt latent kildelager.</p>\n<h3>38.1 Mulige lagre</h3><ul><li>Geologiske ravførende lag og eroderende klinter.</li><li>Ældre strandaflejringer og stormvolde.</li><li>Undervandslommer med tørv, træ og organisk materiale.</li><li>Revler og render, som midlertidigt opsamler lette partikler.</li><li>Langskyst tilførsel fra naboceller.</li></ul>\n<h3>38.2 Udtømning</h3><p>Et område kan levere godt efter første storm og dårligt efter næste, selv om vejret ligner, fordi det lettilgængelige lager er tømt. Gentagne fund og nul-fund skal derfor tolkes som information om både model og lager.</p>\n<h3>38.3 Forsigtig implementering</h3><p>En lagerindikator bør være probabilistisk og langsomt skiftende. Den må ikke skjule dårlig hydrodynamik eller skabe en permanent favoritliste. Den bør opdateres af kvalitetssikrede observationer med negativ-evidens-vægtning, der tager højde for søgeindsats og sigt.</p>\n<div class=\"callout\"><strong>Uddybning af E-02:</strong> Vurder om en latent lagerfaktor er fagligt meningsfuld, og hvilke observationer der kan opdatere den uden cirkelslutning.</div>"},{"id":"organisk-opskael","title":"39. Tang, ålegræs og beach-cast som fysisk system","summary":"Organisk opskyl kan transportere, fange og skjule rav – men er ikke et entydigt signal.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Organisk opskyl kan transportere, fange og skjule rav – men er ikke et entydigt signal. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><h3>39.1 Samtransport</h3><p>Rav og organisk materiale kan begge have lav effektiv neddykket vægt og optræde i samme strandingshændelse. Det gør frisk tang til en plausibel indikator. Men tangens store fleksible form, opdrift og overfladeorientering betyder, at den kan reagere meget anderledes end et kompakt ravstykke.</p>\n<h3>39.2 retention (tilbageholdelse)</h3><p>Vegetationsmåtter og tangvolde reducerer lokale hastigheder, øger ruhed og skaber hulrum. Laboratorieforskning på lavdensitetspartikler viser, at vegetation kan tilbageholde partikler under bølger. Overførbarheden til rav afhænger af skala, vegetationstype og hvor materialet befinder sig i vandsøjlen.</p>\n<h3>39.3 Tidsalder</h3><p>Frisk, våd tang ved den aktive opskylslinje er et andet signal end tør tang flyttet af vind. RavRadar bør derfor ikke nøjes med en permanent zoneegenskab; feltobservationer bør indeholde friskhed, højde på stranden, dominerende materiale og tidspunkt.</p>\n<div class=\"callout\"><strong>Uddybning af E-09 og E-10:</strong> Definér en praktisk klassifikation af opskyl, som kan bruges konsistent af ikke-eksperter.</div>"},{"id":"regional-oceanografi","title":"40. Dansk regional oceanografi og hvorfor én landsregel er utilstrækkelig","summary":"Nordsø, Skagerrak, Kattegat, Bælter, Øresund og Vadehav har forskellige dynamikker.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Nordsø, Skagerrak, Kattegat, Bælter, Øresund og Vadehav har forskellige dynamikker.</div><p>Den integrerede kandidat bruger samme arbejdspriorer i hele landet, men sammenholder gridstrømmen med hver lokal kystretning. RavRadar har ingen automatiske regionale scoreprofiler.</p>\n<h3>40.1 Åbne vestkyster</h3><p>Stor fetch, bølgeenergi, stormsurge og profilændring gør mobilisering central. Bølgeretning og periode kan være vigtigere end lokal vind i øjeblikket.</p>\n<h3>40.2 Skagerrak og Kattegat</h3><p>Tæthedsstrømme, vindstuvning og geometri kan skabe forskel mellem overflade-, grid- og bundnær strøm.</p>\n<h3>40.3 Indre farvande</h3><p>Bælter, fjorde og passager kan være strømstyrede og afhænge af lokale indløb. Et groft grid kan overse hvirvler og konvergens.</p>\n<h3>40.4 Vadehavet</h3><p>Tidevand, render, vadeflader og hurtig vandstandsændring kan gøre landspriorer mindre præcise. Det er en faglig hypotese, ikke en aktiv særregel. Regionale forskelle kræver målbar beskrivelse og repræsentativ hold-out-test.</p>\n<div class=\"callout\"><strong>Uddybning af E-19:</strong> Beskriv målbare regionale forskelle og observationer, der kan afkræfte dem.</div>"},{"id":"datamaaling-usikkerhed","title":"41. Måleusikkerhed, modelopløsning og repræsentativitet","summary":"Hvorfor præcise tal ikke nødvendigvis er præcise beskrivelser af stranden.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Hvorfor præcise tal ikke nødvendigvis er præcise beskrivelser af stranden. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><h3>41.1 Gridpunkt versus zone</h3><p>Vejr- og havmodeller giver værdier for en celle eller interpoleret position. En RavRadar-zone strækker sig langs en uregelmæssig kyst og kan rumme flere revler, læzoner og orienteringer. Dataene skal derfor opfattes som repræsentative signaler med usikkerhed.</p>\n<h3>41.2 Tidsopløsning</h3><p>Timeværdier kan skjule korte bølgegrupper, vindstød, tidevandsvendinger og ripstrømme. Omvendt kan en kort lokal hændelse være for lille til at have betydning for hele zonen.</p>\n<h3>41.3 Prognosefejl og kildeblanding</h3><p>En fysisk model kan være god, men prognosen forkert. RavRadar skal derfor skelne mellem modelusikkerhed, datakvalitet og faglig scoreusikkerhed. Kildeskift inden for samme tidsserie kan skabe kunstige spring og skal undgås.</p>\n<h3>41.4 Visning til brugeren</h3><p>En score bør ledsages af datadækning, alder og centrale usikkerheder. Et tal uden forklaring kan skabe større falsk sikkerhed end en mere forsigtig kvalitetsklasse.</p>"},{"id":"hypoteseregister","title":"42. Hypoteseregister: hvad RavRadar antager lige nu","summary":"Et falsificerbart register over de vigtigste arbejdshypoteser.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Registeret beskriver de vigtigste antagelser i den integrerede model og hvad der kan vise, at de er forkerte.</div><div class=\"handbook-table-wrap\"><table><tr><th>ID</th><th>Hypotese</th><th>Nuværende implementering</th><th>Kan afkræftes ved</th></tr><tr><td>H-01</td><td><code>Hs² × T</code> kan beskrive relativ mobilisering af tilgængeligt rav.</td><td>Ét forløb med cirka fire timers opbygnings- og 48 timers aftrapningshalveringstid.</td><td>Komplette ture viser et systematisk andet energi- eller tidsforløb.</td></tr><tr><td>H-02</td><td>Kystnormal gridstrøm er brugbart relativt tilførselsbevis frem mod kystzonen.</td><td>0,03/0,15 m/s, +10/-8 og fuld 24-timers vægt med dæmpning til 48.</td><td>Felt- eller funddata peger på andre grænser, dybder eller kysttyper.</td></tr><tr><td>H-03</td><td>Udgående gridstrøm reducerer tilførselsbeviset, men beviser ikke et tømt ravlager.</td><td>Op til -8 pr. effektiv time; komponenten kan nå 0 uden helscore-gate.</td><td>Kontrollerede forløb eller lokal surfzoneevidens viser en anden virkning.</td></tr><tr><td>H-04</td><td>Direkte vindpoint vil dobbeltregne vindens virkning.</td><td>Ingen direkte vindpoint i transport eller mobilisering.</td><td>Sammenlignelige ture viser en selvstændig effekt efter kontrol for bølger, strøm og jagtform.</td></tr><tr><td>H-05</td><td>Waders-søgning bliver gradvist sværere med kraftigere vind.</td><td>Fuld score til 6 m/s og 0 ved 15 m/s med blødt bølgefradrag.</td><td>Observationer viser et andet forløb eller regionale forskelle.</td></tr><tr><td>H-06</td><td>Et komplet 48-timers vindue fjerner betydningen af maskinens startværdi.</td><td>Fast nulrand og deterministisk aldersvægtning.</td><td>Samme komplette forløb giver forskellige sluttilstande.</td></tr><tr><td>H-07</td><td>Grove statiske steddata er for usikre til landsbonusser.</td><td>Ingen scorepoint fra rev, lavt vand, tang eller ålegræs.</td><td>Repræsentative ture viser stabil merværdi uden kendte lokale fejl.</td></tr><tr><td>H-08</td><td>Lokale kystdele beskriver retningen bedre end én grov zonelinje.</td><td>Hver del vurderes lokalt; zonens bedste synlige score vises.</td><td>Små eller irrelevante dele overvurderer systematisk zonen.</td></tr><tr><td>H-09</td><td>Rav kan genmobiliseres uden en ny stor storm, men lageret kan ikke observeres.</td><td>Én bølgeenergistyret tilstand; intet lagerpoint.</td><td>Data kan skelne stabilt mellem nærkystlager og ny mobilisering.</td></tr><tr><td>H-10</td><td>Offshore bølgeapproach kan afgrænset dæmpe delivery, men løser ikke surfzone, revler eller strandflade.</td><td>Kausal energivægtet <code>W/N/T</code>-EWMA med fire timers halveringstid og en ældre hale, <code>factor=0,85–1,00</code> og <code>delivery=supply×factor</code> én gang; fysisk levering forbliver uopløst.</td><td>Dynamisk lokal batymetri/surfzonemodel eller repræsentative fund/nul-fund giver en validerbar funktion.</td></tr></table></div><p>En afvist hypotese slettes ikke. Den arkiveres med resultat, version og evidens.</p>"},{"id":"valideringsdesign","title":"43. Faglig validering: fra anekdote til test","summary":"Hvordan RavRadar kan lære uden at overtilpasse til enkelte ture.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Hvordan RavRadar kan lære uden at overtilpasse til enkelte ture. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><h3>43.1 Prospektiv registrering</h3><p>Den stærkeste test er at gemme prognosen, før udfaldet kendes. Efterfølgende registreres søgetid, dækket strækning, metode, sigt, fundmængde og kvalitet. Det forhindrer, at modellen omskrives ud fra hukommelse alene.</p>\n<h3>43.2 Negative observationer</h3><p>Et nul-fund er kun informativt, hvis der faktisk blev søgt tilstrækkeligt og forholdene var observerbare. Ti minutters søgning i uklart vand bør ikke vægte som to timers systematisk søgning.</p>\n<h3>43.3 Hold-out og geografisk generalisering</h3><p>Nye tærskler skal vurderes på perioder og zoner, som ikke blev brugt til at udlede dem. Ellers kan modellen lære lokale tilfældigheder.</p>\n<h3>43.4 Kalibrering</h3><p>En score på 80 behøver ikke betyde 80 % fundchance. Scoren er en relativ indeksværdi. På sigt kan man undersøge kalibrering: hvor ofte og hvor meget rav findes ved forskellige scoreintervaller, betinget af søgeindsats.</p>\n<h3>43.5 Før/efter-test af regler</h3><p>En ekspertregel bør have en tydelig forventet effekt, testperiode samt på forhånd fastlagte accept- og afvisningskriterier. Ændringer skal versionsmærkes, så forbedring kan adskilles fra ændret datakvalitet. Den aktive score ændres kun i kildekode efter RDKS-beslutning, målrettede tests og produktionskontrol.</p>"},{"id":"feltprotokol","title":"44. Feltprotokol for ravjægere og eksperter","summary":"Et minimumsdatasæt, der kan gøre observationer brugbare for modellen.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Et minimumsdatasæt, der kan gøre observationer brugbare for modellen. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><p>Feltdata bør registreres ensartet. Følgende minimum foreslås:</p><ul>\n<li>Præcis zone og start/sluttid.</li><li>Jagtform: strand, vandkant, waders, UV nat.</li><li>Aktiv søgetid og omtrentligt dækket strækning.</li><li>Antal og samlet masse af rav; eventuelt størrelsesklasser.</li><li>Friskhed og placering af tang/ålegræs/andet opskyl.</li><li>Observeret bølgehøjde, uklarhed, strømretning og sikkerhedsforhold.</li><li>Ny erosionskant, revle, rende, udløb eller anden morfologisk ændring.</li><li>Fotodokumentation med frivillig positionssløring.</li></ul>\n<p>Observationen skal markere, om vurderingen er direkte set, estimeret eller hentet fra appen. Ellers risikerer man at bruge modellens egen prognose som uafhængig bekræftelse.</p>\n<div class=\"callout\"><strong>Ekspertpunkt E-21:</strong> Gennemgå protokollen og fjern felter, der ikke kan registreres pålideligt i praksis.</div>"},{"id":"fejlscenarier","title":"45. Kendte fejlscenarier og hvordan de skal opdages","summary":"Konkrete situationer hvor en høj eller lav score kan være misvisende.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Konkrete situationer hvor en høj eller lav score kan være misvisende.</div><h3>45.1 Høj score, intet lager</h3><p>Vejret kan være ideelt, selv om området er udtømt eller har lav ravtilstedeværelse. RavRadar modellerer ikke lagerets størrelse.</p><h3>45.2 Ikke-nul score ved udgående gridstrøm</h3><p>Den integrerede model reducerer transportbeviset fra første effektive udgående time, og komponenten kan nå 0. Hele scoren nulstilles ikke, fordi modellen ikke observerer ravlageret eller surfzonen og derfor ikke kan bevise, at alt rav er fjernet. Forklaringen viser det lave transportled og den strukturelle sidste-mile-usikkerhed.</p><h3>45.3 God lokal lomme skjult af grov geografi</h3><p>En lille bugt eller læside kan være god, selv om modelpunktet er middelmådigt. Det taler for lokalt review, men også mod automatisk overfortolkning.</p><h3>45.4 Datakildeskift</h3><p>Skift mellem kilder kan skabe kunstige spring. Kontinuitet og proveniens kontrolleres før scoring.</p><h3>45.5 Gammel browsercache</h3><p>Gamle prognoser må ikke fremstå som aktuelle; for gammel cache skal give tydelig utilgængelighed.</p>"},{"id":"kodematrix","title":"Historisk 46. State-5-sporbarhed til kode og data","summary":"Historisk aldrig-offentlig state-5-matrix; gældende state-6-forbrugere står i kapitel 89.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Her findes den konkrete integrerede implementering og dens målrettede kontrol.</div><div class=\"callout\"><strong>Releasekandidat:</strong> <code>RRS-COASTAL-PROCESS-INTEGRATED-1.1.0</code>, state <code>5.0.0</code>. Candidate G er fortsat den offentlige 4.0.310-model indtil DEC-0110-cutover og bliver derefter migrations-/offline-/rollback-orakel, ikke offentlig fallback.</div><div class=\"handbook-table-wrap\"><table><tr><th>Emne</th><th>Autoritativ kandidatfil</th><th>Kontrol</th></tr><tr><td>Integreret 20/50/30 og delivery</td><td><span class=\"file-ref\">js/core/ravscore-integrated.js</span></td><td><span class=\"file-ref\">scripts/test-ravscore-integrated-model.mjs</span></td></tr><tr><td>Gridstrøm 24/48 timer</td><td><span class=\"file-ref\">js/core/ravscore-current-supply-memory.js</span></td><td><span class=\"file-ref\">scripts/test-ravscore-current-supply-memory.mjs</span></td></tr><tr><td>Bølgemobilisering 4/48</td><td><span class=\"file-ref\">js/core/ravscore-wave-mobilisation-state.js</span></td><td><span class=\"file-ref\">scripts/test-ravscore-wave-mobilisation-state.mjs</span></td></tr><tr><td>Wave-approach-EWMA, fire timers halveringstid</td><td><span class=\"file-ref\">js/core/ravscore-wave-approach-state.js</span></td><td><span class=\"file-ref\">scripts/test-ravscore-wave-approach-state.mjs</span></td></tr><tr><td>State 5, migration og rollback</td><td><span class=\"file-ref\">js/core/ravscore-integrated-state-pipeline.js</span></td><td><span class=\"file-ref\">scripts/test-ravscore-last-mile-candidate-migration.mjs</span></td></tr><tr><td>Evidenstillid og nøddrift</td><td><span class=\"file-ref\">js/core/ravscore-evidence-trust-contract.js</span></td><td><span class=\"file-ref\">scripts/test-ravscore-public-runtime-contract.mjs</span></td></tr><tr><td>Offentlig model/runtime</td><td><span class=\"file-ref\">js/core/ravscore-public-runtime-contract.js</span></td><td><span class=\"file-ref\">scripts/test-ravscore-public-data-service-binding.mjs</span></td></tr><tr><td>Vejr og scoregenerator</td><td><span class=\"file-ref\">scripts/update-weather.mjs</span></td><td><span class=\"file-ref\">scripts/test-ravscore-integrated-generator.mjs</span></td></tr><tr><td>Privat runtime og checkpoint</td><td><span class=\"file-ref\">scripts/private-production-runtime-bundle.mjs</span></td><td><span class=\"file-ref\">scripts/test-private-production-runtime-bundle.mjs</span></td></tr><tr><td>Håndbog</td><td><span class=\"file-ref\">docs/handbook/content.json</span></td><td><span class=\"file-ref\">scripts/release-gate.mjs</span></td></tr></table></div><p>Legacy score- og regelfiler er historik eller kontrolleret oracle; de er ikke samtidige offentlige scoreveje.</p>"},{"id":"kildekritik-detaljer","title":"47. Kildekritik og overførbarhed til rav","summary":"Hvordan litteratur fra sand, plast og vegetation må – og ikke må – bruges.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Hvordan litteratur fra sand, plast og vegetation må – og ikke må – bruges. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><h3>47.1 Direkte ravlitteratur</h3><p>Den mest relevante litteratur beskriver baltisk rav som svagt negativt flydende materiale, der kan cirkulere mellem undervandsskråning og strand og vaskes op efter stormforløb. Studierne er geografisk koncentreret i den sydøstlige Østersø. De giver mekanistisk støtte, men ikke direkte danske tærskler.</p>\n<h3>47.2 Sedimentlitteratur</h3><p>Kystingeniørviden om bølger, strøm, skærspænding, bedload, suspension og morfologi er veletableret. Rav er dog ikke et standard-sandkorn. Formler kan bruges til struktur og størrelsesorden, men kræver nye partikelparametre og validering.</p>\n<h3>47.3 Plast som analogi</h3><p>Visse plasttyper har densitet tæt på rav og kan vise, hvordan lavdensitetspartikler strander, recirkulerer eller tilbageholdes i vegetation. Plast varierer imidlertid ekstremt i form, fleksibilitet, biofilm og størrelse. Derfor må plaststudier aldrig alene fastsætte en ravregel.</p>\n<h3>47.4 Praktisk ravjægerviden</h3><p>Langvarig lokal erfaring kan opdage mønstre, som modeller og publikationer overser. Den kan samtidig være påvirket af selektiv hukommelse, skiftende søgeindsats og skjulte variable. RavRadar behandler den som værdifuld ekspertobservation, der skal operationaliseres og testes.</p>"},{"id":"bibliografi","title":"48. Annoteret faglig bibliografi","summary":"Kilderne bag den nuværende forståelse og præcis hvad de kan støtte.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Kilderne støtter procesforståelse og datakontrakter, men fastsætter ikke en universel dansk ravformel.</div><ol class=\"bibliography\"><li><strong>Chubarenko &amp; Stepanova (2017), DOI 10.1016/j.envpol.2017.01.085.</strong> Baltisk rav som analogi for lavdensitetspartiklers mobilisering og recirkulation; ingen danske tærskler.</li><li><strong>Isachenko m.fl. (2023), Estuarine, Coastal and Shelf Science 281, 108219.</strong> Sammenhæng mellem beach-cast og de foregående dages ydre bølgeforhold; ikke lokal strandingsopløsning.</li><li><strong>Chardón-Maldonado m.fl. (2016), DOI 10.1016/j.coastaleng.2015.10.008.</strong> Swashzonens komplekse transport og måleusikkerhed.</li><li><strong>Faria m.fl. (2000), DOI <a href=\"https://doi.org/10.1029/2000JC900084\">10.1029/2000JC900084</a>.</strong> Undertows rumlige struktur over en revlekyst og betydelig modelusikkerhed over revlen; gridstrøm er ikke lokal undertow.</li><li><strong>Reniers m.fl. (2009), DOI <a href=\"https://doi.org/10.1029/2008JC005153\">10.1029/2008JC005153</a>.</strong> Surfzoneretention kræver flere bevægelsesled; studiets cirka 20 % observerede exits er ikke en universel ravandel.</li><li><strong>Gallop m.fl. (2018), DOI <a href=\"https://doi.org/10.1016/j.margeo.2018.07.015\">10.1016/j.margeo.2018.07.015</a>.</strong> Revlebrydning kan ændre ripcirkulation, retention og udveksling på en dobbelt revlekyst.</li><li><strong>Haller m.fl. (2002), DOI <a href=\"https://doi.org/10.1029/2001JC000955\">10.1029/2001JC000955</a>.</strong> Laboratorieforsøg på en fast revlestrand med ripkanaler; dokumenterer morfologiafhængig feeder-/ripcirkulation, ikke lavvandsfeltbevis.</li><li><strong>MacMahan m.fl. (2010), DOI <a href=\"https://doi.org/10.1016/j.margeo.2009.09.011\">10.1016/j.margeo.2009.09.011</a>.</strong> Ripstrøm kan være recirkulerende frem for ren søværts eksport.</li><li><strong>Aagaard m.fl. (1997), DOI <a href=\"https://doi.org/10.1016/S0025-3227(97)00025-X\">10.1016/S0025-3227(97)00025-X</a>.</strong> Ét feltstudie viste stærk offshore rip-/sedimenttransport ved lavvande og samtidig landværts oscillerende transport uden for surfzonen; støtter stedafhængighed, ikke en landsregel.</li><li><strong>Mouragues m.fl. (2020), DOI <a href=\"https://doi.org/10.1029/2020JC016259\">10.1029/2020JC016259</a>.</strong> Treugers feltstudie med skiftende bølge-, vandstands- og morfologiafhængige strømregimer; støtter stedafhængighed, ikke en universel lavvandsregel.</li><li><strong>Aagaard, Black og Greenwood (2002), DOI <a href=\"https://doi.org/10.1016/S0025-3227(02)00193-7\">10.1016/S0025-3227(02)00193-7</a>.</strong> Nettoretningen over revler afhænger af undertow, bølgeskævhed, orbitalhastighed, relativ dybde og bundhældning; ingen ravspecifik faktor.</li><li><strong>Jalón-Rojas m.fl. (2025), DOI <a href=\"https://doi.org/10.5194/gmd-18-319-2025\">10.5194/gmd-18-319-2025</a>.</strong> Vertikal position og densitet ændrer Stokes-/undertoweksponering i en bølgeopløst 2DV-model; mikropartikler er analogi.</li><li><strong>Lofty m.fl. (2023), DOI <a href=\"https://doi.org/10.1016/j.watres.2023.120329\">10.1016/j.watres.2023.120329</a>.</strong> 5 mm-rav omkring 1 041 kg/m³ bevægede sig som lavdensitets bedload/saltation i et åbent-kanal-forsøg; ikke en dansk surfzonevalidering.</li><li><strong>Núñez m.fl. (2023), laboratoriestudie af tværkyst partikeltransport.</strong> Aflejring afhænger blandt andet af synkehastighed, form, densitet og bølgestejlhed; overførsel til rav kræver forsigtighed.</li><li><strong>Rainville m.fl. (2026), DOI <a href=\"https://doi.org/10.1029/2025JC022422\">10.1029/2025JC022422</a>.</strong> Nærkystdriftere viser, at brydende bølger kan strande flydende objekter; kun buoyant-object-analogi, aldrig ravkalibrering.</li><li><strong>USACE Coastal Engineering Manual.</strong> Autoritativ ramme for bølger, strøm, sedimenttransport og kystmorfologi.</li><li><strong>NOAA Ocean Service.</strong> Autoritativ forklaring af langskyst- og ripstrømme.</li><li><strong>DMI WAM/DKSS-dokumentation.</strong> Autoritativ for bølgeretningens <code>FROM</code>-semantik, input, lag og modelbegrænsninger; ikke ravfysik eller lokal surfzonelevering.</li><li><strong>Geodatastyrelsen, <a href=\"https://gst.dk/ansvarsomraader/soekort-og-marine-data/soeopmaaling-og-dybdedata/danmarks-dybdemodel\">Danmarks Dybdemodel</a>.</strong> Det officielle 50 m-grid er statisk kontekst, men opløser ikke dynamiske revler, ripkanaler eller bølgeopløst surfzone og er derfor ikke RavScore-input.</li></ol><p>Hver ny scoreantagelse skal have mekanistisk kilde eller tydelig hypotese-/ekspertmærkning. En ændring bliver først aktiv gennem den versionsstyrede model- og releaseproces.</p>"},{"id":"ekspertarbejdsgang","title":"49. Ekspertens review-arbejdsgang","summary":"Sådan omsættes faglig kritik til en sporbar og testbar ændring.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Sådan omsættes faglig kritik til en sporbar og testbar ændring.</div><ol><li>Find det relevante kapitel og angiv konkret påstand eller tærskel.</li><li>Vælg type: faglig fejl, usikker antagelse, ny forskning, forbedringsforslag eller manglende dokumentation.</li><li>Beskriv hvilke kyster, årstider og vejrforløb udsagnet gælder for.</li><li>Angiv forventet retning og størrelse på modelændringen.</li><li>Vedlæg kilde, data eller gentagne observationer.</li><li>Foreslå en test og et kriterium for accept eller afvisning.</li><li>Ejeren vurderer forslaget. Ved accept skrives en RDKS-beslutning, den autoritative modelkode ændres, regressioner og releasegates køres, og ændringen bliver først aktiv efter PR, merge, deploy og offentlig kontrol.</li></ol><p>En ekspertkommentar ændrer aldrig håndbogen eller scoremotoren direkte. Den gemmes centralt med versionshistorik og kan accepteres, afvises eller implementeres gennem den kontrollerede proces.</p>"},{"id":"ordliste","title":"50. Faglig ordliste","summary":"Ensartede definitioner af de vigtigste begreber.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Ensartede definitioner af de vigtigste begreber. <span>Fagord forklares i teksten eller i ordlisten. Det fremgår særskilt, hvad RavRadar gør i dag, og hvad der stadig er usikkert.</span></div><dl>\n<dt>Advektion</dt><dd>Transport med middelstrømmen.</dd><dt>backwash (vand der løber tilbage fra stranden)</dt><dd>Vandets tilbagestrømning ned ad strandfladen efter swash (bølgeopskyl på stranden).</dd><dt>Bedload</dt><dd>Partikler, der ruller, glider eller hopper tæt ved bunden.</dd><dt>Bundskærspænding</dt><dd>Den tangentiale belastning vandbevægelsen overfører til bunden.</dd><dt>Fetch</dt><dd>Den frie strækning vinden blæser over vandet og kan opbygge bølger på.</dd><dt>OnshoreDirectionDeg</dt><dd>RavRadars lokale retning fra hav mod land; bruges som reference for strøm og vind.</dd><dt>Refraktion</dt><dd>Drejning af bølger, når dele af bølgefronten bevæger sig i forskellig dybde.</dd><dt>ripstrøm (smal og ofte stærk strøm ud fra stranden)</dt><dd>Lokal, kanaliseret strøm væk fra stranden gennem surfzonen.</dd><dt>Saltation</dt><dd>Partikeltransport i gentagne hop nær bunden.</dd><dt>Setup</dt><dd>Forhøjet middelvandstand nær kysten forårsaget af bølgers momentumoverførsel.</dd><dt>Swash</dt><dd>Den vekslende op- og nedløbende vandbevægelse på strandfladen.</dd><dt>undertow (returstrøm under bølgerne)</dt><dd>Middelreturstrøm, ofte udadgående nær bunden under brændingszonen.</dd></dl>"},{"id":"flere-transportveje","title":"51. Flere veje til fundbart rav: primærlager, sekundærlager og genmobilisering","summary":"Hvorfor RavRadar ikke må gøre den fulde stormkæde til en absolut sandhed.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar må ikke gøre den fulde stormkæde til en absolut sandhed.</div><p>Rav kan flyttes gennem korte cyklusser mellem strand, swashzone, revle, rende, tang og lavt vand. Fagligt er det nyttigt at skelne mellem et <strong>primært lager</strong>, som kræver egentlig frigivelse, og et <strong>sekundært nærkystlager</strong>, hvor rav allerede er tilgængeligt. Den aktive model observerer eller klassificerer ikke lagrene.</p><h4>51.1 Genmobilisering</h4><p>Moderate bølger kan løfte eller rulle ravet, mens gridstrøm giver et relativt transportbevis. Faldende vand kan både føre noget materiale udad og blotlægge et depot bag en revle. Hændelsen behøver ikke opfylde en stormtærskel.</p><h4>51.2 Modelkonsekvens</h4><p>Den integrerede model bruger ét <code>Hs² × T</code>-styret mobiliseringsforløb og kan ikke afgøre, om ravet kom fra et primært eller sekundært lager. Den beregner heller ikke præcis aflejring eller retention. Det undgår dobbeltvægtning, men er en vigtig forenkling.</p><p>Mobilisering beregnes i <strong>js/core/ravscore-wave-mobilisation-state.js</strong> og samles i <strong>js/core/ravscore-integrated-state-pipeline.js</strong>.</p>"},{"id":"stroem-langs-kysten","title":"52. Strøm langs kysten – er “mod land eller væk” for simpelt?","summary":"Praktiske spørgsmål om strøm, bølger og transport, skrevet til ekspertreview i almindeligt dansk.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar måler gridstrømmens kystnormale komponent, men rav kan også flyttes langs stranden.</div><p>En næsten langskyst gridstrøm kan flytte materiale langt. Bølger kan samtidig drive en anden langskyststrøm inde i surfzonen, og odder, bugter, revler, høfder og havne kan skabe konvergens eller bypass. Gridstrøm, bølgeorbitaler, undertow, feeder-/langskyststrøm og ripstrøm er forskellige begreber.</p><h4>Sådan gør RavRadar</h4><p>Systemet beregner forskellen mellem verificeret gridstrøm og lokal hav→land-retning. Direkte indgående strøm bygger transportbevis mest, næsten parallel strøm giver en lille kystnormal komponent, og udgående strøm nedbryder det rullende bevis. Modellen følger ikke et netværk mellem nabozoner og foregiver ikke at opløse surfzonen.</p><h4>Spørgsmål til eksperten</h4><ul><li>Hvornår ankommer rav langs kysten trods lille kystnormal gridstrøm?</li><li>Hvornår fanges det ved læ, revler eller konstruktioner, og hvornår passerer det forbi?</li><li>Hvilke målbare data kan skelne de forløb uden lokal falsk præcision?</li></ul><p>Den aktive score findes i <strong>js/core/ravscore-integrated.js</strong> og <strong>js/core/ravscore-integrated-state-pipeline.js</strong>. Retningen auditeres særskilt.</p>"},{"id":"diagnostisk-sandhed","title":"53. Fejl, advarsler, cache og manglende målinger","summary":"RavRadar skal skelne mellem en reel fejl, en advarsel og en forventet mellemtilstand.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Her forklares forskellen på en rigtig fejl, en advarsel og en normal mellemtilstand. <span>Formålet er, at administratoren kan se præcis, om noget er gået i stykker, blot er langsomt eller bruger gyldige cachedata som planlagt.</span></div><p>En rigtig fejl betyder, at en nødvendig fil, databasehandling eller brugerfunktion ikke virker. En advarsel betyder, at funktionen virker, men eksempelvis er langsom. En forventet mellemtilstand kan være en verificeret browsercache eller en bevidst sprunget DMI-observationskørsel.</p><p>Vandstandsstationers registerstatus, seneste observation, cachegyldighed og samlede anvendelighed vises hver for sig. En kørsel uden ny observationshentning må ikke ændre en tidligere leverende station til “aldrig leveret”.</p><p>Den samlede funktionstest navngiver den konkrete fejl eller langsomme ressource og viser Bestået, Advarsel og Fejl særskilt.</p>"},{"id":"how-ravradar-decides-amber-arrival","title":"Historisk 54. Den aldrig-offentlige state-5-score","summary":"Historisk state-5-beskrivelse; kapitel 89 beskriver den gældende lokale state-6-score og dens bounds.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Den integrerede releasekandidat kombinerer søgeforhold, levering baseret på verificeret gridstrøms-supply og afgrænset bølgeapproach samt bølgemobilisering. Scoren er ikke en fundchance eller bevis for fysisk landing.</div><h3>54.1 Vægtning</h3><p><strong>20 % søgeforhold, 50 % delivery og 30 % rav i bevægelse.</strong> Vægtene er en faglig produktprior, ikke fundkalibrering.</p><p><strong>Søgeforhold:</strong> Waders bruger vindkurven 100 til 6 m/s og 0 ved 15 m/s med et blødt bølgefradrag; slutscoren kan ikke overstige søgeforholdene. Strand bevarer sine kurver.</p><p><strong>Supply:</strong> 0,03 m/s er dødzone, 0,15 m/s fuld styrke, indgående giver +10 og udgående -8 pr. effektiv time. Evidens vægtes fuldt i 24 timer og cosinusdæmpes til nul ved 48. Der er ingen 13-timers helscore-gate.</p><p><strong>Mobilisering:</strong> <code>Hs² × T</code> bygger én tilstand med cirka fire timers og aftager med cirka 48 timers halveringstid.</p><h3>54.2 Sidste mile og vandstand</h3><p>En kausal energivægtet bølgeapproach med fire timers halveringstid og en ældre hale danner <code>W/N/T</code>. DMI-WAM <code>FROM</code> roteres én gang +180° til <code>TOWARD</code> mod uændret kystnormal. <code>normalAlignment</code> er det energivægtede normalmoment divideret med aktivitet, og <code>approach=clamp((normalAlignment+0,25)/1,25,0,1)</code>. <code>factor=clamp(1-0.15×W×(1-approach),0.85,1)</code>, og <code>delivery=supply×factor</code> bruges én gang. Bølger skaber eller øger aldrig supply; højst 7,5 rå totalscorepoint fjernes før slutafrunding; vist RavScore kan derfor ændres 8 point. Aktiv direction-missing fejler lukket. Kun <code>waveHeightM=0</code> er eksakt calm og neutral; <code>wavePeriodS</code> skal stadig være finit og ikke-negativ. <code>waveHeightM&gt;0</code> med <code>wavePeriodS=0</code> er <code>INVALID</code> og fejler lukket.</p><p>Fysisk levering forbliver uopløst: <code>physicalDeliveryResolved=false</code> og interval <code>null</code>. DDM 50 m er statisk kontekst, ikke dynamisk revle-/surfzonemodel eller scoreinput. Rainville 2026 er kun buoyant-object-analogi. Ingen geometri eller land-/vandpunkter flyttes.</p><p><code>waterLevelTrendCm3h</code> er fremadrettet modelændring, ikke ebbe/flod. Faldende vand kan både ledsage udtransport og blotlægge eller gøre fastholdt rav bag revler lettere at afsøge. Vandstand er score-neutral kontekst og tie-break, ikke bevis for mere eller mindre rav.</p><h3>54.3 Migration, state og nøddrift</h3><p><code>candidate-g-schema2-signed-current-reweight-bounded40h-wave-approach-to-integrated-schema5-v4</code> genvægter kun signeret, allerede afledt kystnormal Candidate G-currentevidens; rå U/V læses eller kopieres ikke, og der påstås ingen rå genberegningslighed. Wave-approach bruger 40 private præ-target-positioner fra ét sammenhængende DMI WAM-run pr. anvendt collection med same-cell native provenance. Kun et WAM-gap på højst fire timer må interpoleres, og kun i samme run, collection, gitter og celle. Udeladt EWMA-hale er højst <code>1/1024</code>, og konservativ rå-scorefejl er højst <code>0,01171875</code> før afrunding.</p><p>Præcis 673 gyldige schema-2-states skal give ét fælles target; ellers stopper skiftet, og Candidate G forbliver offentlig. Der dannes ingen syntetisk eller offentlig historik. Ægte cold start kræver særskilt præcis 48 sammenhængende private, verificerede timepositioner plus reel target. Kun same-model atomisk nøddrift højst 72 timer er tilladt, uden cross-model fallback eller interpolation; WAM-bootstrapinterpolation gælder ikke nøddrift. Kun <code>VERIFIED_ONLY</code> er kalibreringsegnet; reconstructed/emergency og ture er ikke kalibreringsgrundlag.</p><div class=\"callout\"><strong>Vigtigt:</strong> Modellen er fysisk motiveret og mekanisk regressionstestet. Den må ikke kaldes empirisk mere fundpræcis uden et repræsentativt fund-/nul-fundgrundlag.</div>"},{"id":"public-runtime-pipeline","title":"Historisk 55. Den aldrig-offentlige state-5-runtime","summary":"Historisk state-5-runtime; aktiv lokal runtime/cache/checkpoint er schema 6 som beskrevet i kapitel 89.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Browseren får præcis fire schema-4-livefiler; fuld runtime og state-5-fortsættelse forbliver private. Kontrakten er implementeret lokalt og bliver først offentlig ved DEC-0110-cutover.</div><p>Manifestet binder dataset-id, model/state, kontrakter, størrelser og kryptografiske fingeraftryk. Browseren accepterer kun samme datasæt og samme modelbinding. Fuld conditions, DMI-caches, forseglet Copernicus-range-cache, historik og diagnostik ligger i den private atomiske bundle; Pages- og supportaudits afviser private filer.</p><p>Migration <code>candidate-g-schema2-signed-current-reweight-bounded40h-wave-approach-to-integrated-schema5-v4</code> genvægter kun Candidate G''s signerede, allerede afledte kystnormale currentevidens; den læser eller kopierer ikke rå U/V og påstår ikke lighed med en rå genberegning. Wave-approach bruger 40 private præ-target-positioner fra ét sammenhængende DMI WAM-run pr. anvendt collection med same-cell native provenance. Kun et WAM-gap mellem native endepunkter højst fire timer fra hinanden i samme run, collection, gitter og celle må interpoleres. Udeladt EWMA-hale er højst <code>1/1024</code>, og konservativ rå-scorefejl er højst <code>0,01171875</code> før afrunding.</p><p>Præcis 673 gyldige schema-2-states skal passe til det uforanderlige kystdelsregister og give ét fælles kanonisk target. Mixed target, manglende/ugyldig state eller utilgængeligt coherent WAM-run stopper fail-closed, så Candidate G forbliver offentlig; syntetisk eller offentlig historik dannes ikke. Ægte cold start er særskilt og kræver præcis 48 sammenhængende private, verificerede timepositioner plus reel target. Candidate G-rollback <code>integrated-schema5-to-candidate-g-schema2-v2</code> bruger samme targettid uden dobbelt recovery-credit.</p><p>Et beskyttet state-5-checkpoint kan kun levere same-model, komplet, atomisk og hashbundet nøddrift i højst 72 timer eller kortere forecastudløb. Cross-model fallback og interpolation er forbudt; den kontrollerede WAM-bootstrapregel gælder ikke nøddrift. Kun <code>VERIFIED_ONLY</code> er kalibreringsegnet; reconstructed/emergency og ture er ikke kalibreringsgrundlag. Den planlagte fiktive udførelse af morgenhullet blev opgivet før descriptor, apply, mutation eller offentliggørelse. Workflow-inputs/job, incidentpolicy og mutator er fjernet; en negativ gate forhindrer genåbning, mens historiske kvalitetsmarkører stadig læses konservativt. DEC-0109 er kun dokumentation.</p><p><code>20260829010000_ravscore_operational_documents_no_history.sql</code> etablerer privat runtimefundament før <code>20260829020000_integrated_trip_calibration_binding.sql</code>. Protected readiness, exact-head, Edge-<code>409</code>, 210/673 og controllerens source/PENDING/target/reconcile holder Candidate G offentlig, indtil den integrerede Pages-binding og centrale profil kan aktiveres atomisk.</p><p>Candidate G er et privat migrations-/offline-/rollback-orakel, aldrig samtidig eller automatisk offentlig nødmodel. En senere manuel hel rollback kan først gøre den offentlig igen efter den særskilte kontrol nedenfor.</p>"},{"id":"operational-candidate-g-rollback-2026-08-29","chapter":"55","title":"Historisk 55.1 State-5-plan for Candidate G-helrollback","summary":"Historisk aldrig-offentlig state-5-plan; state 6 bruger rollback-id''et i kapitel 89 og samme manuelle CAS-grænse.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Rollback er en særskilt manuel release. Candidate G er aldrig offentlig shadowmodel eller automatisk fallback, og central profil skifter først sammen med aktiv status efter offentlig Pages-verifikation.</div><p>Rollback-id''et er <code>integrated-schema6-to-candidate-g-schema2-v3</code>, og overgangstypen er <code>CANDIDATE_G_ROLLBACK</code>. Projektionen bygges fra samme targettid som den integrerede state uden dobbelt recovery-credit. Controlleren ligger under <code>ravscore-operational-model-activation</code> med schema <code>ravscore-operational-model-activation-v4</code>, fire statusser, seks overgangstyper og præcis 30 felter, inklusive source/requested implementation-closure-hashes.</p><p>Controlleren observerer den integrerede offentlige kilde, skriver <code>CANDIDATE_G_PENDING</code> og bevarer integreret central profil, mens Candidate G-Pages deployes. Først efter eksakt implementation- og 210/673-verifikation sætter én beskyttet handling samtidigt <code>CANDIDATE_G_ACTIVE</code> og central Candidate G-profil. En senere manuel tilbagevenden bruger <code>INTEGRATED_RETURN</code> og <code>INTEGRATED_PENDING</code>.</p><p>Crash/retry validerer requested/source/third manifest fail-closed sammen med implementation closure. Scheduleren kan kun udføre Candidate G-refresh; den kan hverken førstegangsaktivere, rollbacke eller returnere en model. Fra rowless legacy vedligeholder scheduler/manuelt vejr gennem <code>LEGACY_CANDIDATE_G_REFRESH_BEFORE_INITIAL_CUTOVER</code>; efter et afbrudt integreret cutover bruges den særskilte <code>CANDIDATE_G_REFRESH_BEFORE_INITIAL_CUTOVER</code>, mens almindelig aktiv drift bruger <code>CANDIDATE_G_REFRESH</code>. Ingen vedligehold skriver <code>INTEGRATED_PENDING</code>. Direct rowless first cutover bruger version 0/legacy source; efter bridge-complete bruges exact current Candidate-marker og aktuel CAS-version. Der deployes ingen Candidate G-assistent-Edge; integreret Edge afviser Candidate G-bindingen med HTTP <code>409</code>, hvorefter klienten bruger lokale DA/DE/EN-svar. Candidate G-bundne ture er <code>calibration_eligible=false</code>.</p><p>Candidate G har egne kontrakt- og bundlefingeraftryk, som fastsættes på afsluttet head. Dermed er rollback varm og kontrollerbar uden at gøre den til en samtidig offentlig model.</p>"},{"id":"current-arrow-scientific-provenance","title":"56. Hvor står strømpilene, og hvilken vej peger de?","summary":"Forklarer hvordan RavRadar placerer strømpile ved de faktiske modelpunkter og kontrollerer retning og hastighed fra rå strømkomponenter.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En strømpil skal stå ved det sted, som leverede strømdataene, og pege den vej vandet bevæger sig. <span>Ved indzoomning vises flere pile, men kun når der findes flere faktiske DMI-gitterpunkter.</span></div><p>En strømpil er ikke pynt. Den skal vise en bestemt beregnet vandbevægelse ved et bestemt sted. Når strømmen kommer direkte fra DMI, placeres pilen ved det modelgitterpunkt, hvor DMI leverede både den østlige og den nordlige strømkomponent. Hvis punktet ikke kan dokumenteres, vises der ikke en direkte DMI-strømpil.</p><h3>56.1 Sådan beregnes retningen</h3><p>Strømretningen fortæller, hvor vandet bevæger sig hen. 0° betyder mod nord, 90° mod øst, 180° mod syd og 270° mod vest. RavRadar beregner retningen ud fra den østlige og nordlige komponent og lader strømpilen pege direkte i denne retning. Vinddata er en fra-retning og vendes derfor 180° i kortvisningen.</p><h3>56.2 Sådan kontrolleres zoneværdien</h3><ol><li>Øst-/vest- og nord-/syd-komponenten skal komme fra samme modelpunkt.</li><li>Den viste hastighed skal svare til de to komponenters samlede længde.</li><li>Den viste retning og kortpil skal svare til komponenternes faktiske bevægelsesretning.</li></ol><p>I 4.0.76 blev 23.049 prognosetimer kontrolleret på denne måde. 197 af 209 aktive zoner havde et direkte dokumenteret DMI-marinepunkt i den medfølgende modelcache. Zoner uden dokumenteret DMI-punkt må ikke vise en direkte DMI-pil. Fallback kan kun vises ved det marine punkt, som fallbackudbyderen faktisk blev forespurgt på.</p><h3>56.3 Hvad betyder pilens sted ikke?</h3><p>Pilen viser modelværdien på modelgitteret. Den beviser ikke, at strømmen er identisk helt inde ved stranden, bag en mole, i en smal rende eller på den anden side af en revle. Lokale bundforhold kan afvige, og eksperten bør derfor pege på steder, hvor modelpunktet ikke repræsenterer den lokale kyst godt nok.</p><h3>56.4 Flere ægte pile ved indzoomning</h3><p>På landsoversigten vises fortsat ét repræsentativt vind- og strømpunkt pr. hovedzone. Fra zoomniveau 9 kan kortet også vise lokale kystdeles egne pile. En lokal strømpil kræver strøm-U og strøm-V på præcis samme DMI-koordinat, og en lokal vindpil kræver tilsvarende vind-U og vind-V. Vindpunktet kan komme fra DMI''s atmosfæremodel eller havmodellens vindserie, alt efter hvilken serie prognosen faktisk bruger; kildemærket bevarer forskellen.</p><p>Fallbackankre, ufuldstændig provenance og kopier eller forskydninger af en eksisterende pil bruges ikke som ekstra pile. Den hurtige startpakke viser de aktuelle vinderdeles punktgrundlag; når den fulde detaljepakke ankommer, opdateres kortet automatisk med alle dokumenterede lokale punkter i udsnittet.</p><p>Ændringen påvirker kun visningen. DMI-værdier, prognoser, RavScore, historik og land-/vandpunkter er uændrede.</p>","content":"\n\nPilene installeres efter rangliste og femdøgnsprognose, men som en garanteret og målbar opgave. Sitetesten kræver faktiske vindpile og verificerede strømpile samt en entydig ready-status."},{"id":"public-performance-4-0-82","title":"57. Hvorfor kan en langsom enhed stadig vise dagens resultat?","summary":"Forklarer hvordan dagens rangliste vises før den tunge femdøgnsberegning, og hvordan beregningen deles op for at undgå en fastlåst side.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Dagens rangliste vises først. <span>Femdøgnsberegningen fortsætter derefter i små bidder med synlig fremdrift.</span></div><p>RavRadar skal vurdere mange zoner og timer for at finde de bedste områder i fem døgn. Tidligere blev hele arbejdet udført i én ubrudt beregning. Browseren kunne derfor ikke nå at tegne dagens rangliste, selv om den teknisk var skrevet til siden.</p><h3>57.1 Hvad ændrede 4.0.83?</h3><p>Browseren får nu lov til at tegne dagens rangliste, før femdøgnsberegningen starter. Derefter beregnes prognosen i små bidder, og siden viser procentvis fremdrift. Skift af jagtform stopper en ældre beregning, så to beregninger ikke konkurrerer.</p><h3>57.2 Påvirker det RavScore?</h3><p>Nej. Data, RavScore-regler og valg af bedste tidspunkt er uændrede. Kun rækkefølgen og fordelingen af browserarbejdet er ændret.</p>"},{"id":"complete-admin-workflows-4-0-86","title":"58. Fra kode til brugbar funktion","summary":"En funktion er først færdig, når den kan findes, gennemføres og genfindes i den aktive admin.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En funktion er først færdig, når ejeren kan finde den, gennemføre den og finde resultatet igen.</div><p>RavRadar kræver en komplet brugerrejse: synlig indgang, forståelig proces, sand kvittering og genfindeligt resultat.</p><h3>Håndbogsreview</h3><p>Reviewkøen findes på Håndbog-fanen. Den centrale håndbog læses tilbage, før review markeres implementeret. Lokale nødkladder kan gensendes, eksporteres eller slettes.</p><h3>Dokumentation og kalibreringsgrundlag</h3><p>Dokumentationscenteret åbner RDKS-kernen. Kalibreringssiden er skrivebeskyttet og viser kun, om ture på sigt kan bruges i en kontrolleret analyse. Den kan ikke ændre model-id, state, profil, den offentlige RavScore eller lokal scorekode.</p><h3>Sitetest</h3><p>Deploykontrollen skelner 404, timeout, netværksfejl og HTTP-fejl. Opstart opdeles i netværk/data, beregning og rendering.</p>"},{"id":"admin-zone-deletion-4-0-89","title":"Sletning af kystdele og hele zoner","summary":"Sådan virker central sletning og forplantning til hele RavRadar.","body":"<aside class=\"reader-guide\"><b>Sådan læses kapitlet:</b> Først forklares forskellen på at slette en kystdel og en hel zone. Derefter beskrives, hvordan ændringen bliver gemt centralt og ført ud i hele systemet.</aside><p>I <b>Retning hav-land</b> kan ejer enten slette den valgte kystdel eller hele zonen. Kystdelssletning bevarer zonen og dens øvrige retninger. Zonesletning kræver dobbelt bekræftelse.</p><p>Ændringen gemmes centralt og læses tilbage. Ved næste deployment anvendes den på den autoritative zonefil før vejrdata og offentlig runtime bygges. Kort, RavScore, rangliste, forecast, debug og routing bruger dermed samme aktive zonedefinition.</p><p>Review- og systemtestposter kan soft-slettes, så de forsvinder fra arbejdslisten, mens auditsporet bevares.</p>"},{"id":"state-model-handoff-4-0-112","title":"60. Historisk tilstandsmodel og sikker videreudvikling","summary":"RavRadar validerer en score-neutral historisk tilstand på faste referencezoner, før den får numerisk virkning.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar validerer en score-neutral historisk tilstand på faste referencezoner, før den får numerisk virkning. <span>Fagord forklares i teksten, og planlagte funktioner adskilles tydeligt fra det, der virker i dag.</span></div><p>RavRadar skal beskrive et forløb og ikke kun den aktuelle time. Pipelinen beregner varighed af ind- og udadgående strøm, mobilisering, nærkystpotentiale og procesfase. I 4.0.112 er modellen fortsat score-neutral.</p><p>Der bruges ingen generelle strømbånd, og almindelig indtransport får ikke en universel 3–5-timers kontakt. Eksisterende dokumenteret morfologi bevares; manglende morfologi er neutralt.</p><p>Fire faste referencezoner bruges til automatisk validering. Als Odde og Helberskov er åben kyst nord for Mariager Fjord og ikke fjordzone.</p><p>Brugerfund skal senere kræve valgt zone, mens GPS kun er plausibilitetskontrol. Historik beregnes i pipeline, så den offentlige opstart forbliver hurtig.</p><div class=\"callout\"><strong>Ny projektchat:</strong> Læs RDKS-overleveringen før kodeændringer og brug den seneste projekt-ZIP som teknisk baseline.</div>"},{"id":"production-shadow-validation-4-0-113","title":"Historisk 4.0.113: produktionskontrol af skyggetilstand","summary":"Historisk revisionsspor for den score-neutrale skyggetilstand, som gik forud for Candidate G.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> I 4.0.113 var tilstandsmodellen endnu score-neutral og blev kun kontrolleret på fire referencezoner. Det er ikke den aktive arkitektur.</div><p>Dengang krævede en frisk produktion verificeret DMI-strøm og <code>stateModelMode: shadow-v2</code> for referencezonerne. Candidate G blev senere den offentlige scoremodel og bruger nu sin egen dokumenterede 48-timers strømtilstand og bølgeenergistyrede mobiliseringstilstand på de aktive kystdele.</p><p>Workflowet loggede datasæt-id, strømstatus og kompakte historiske felter, så produktionstimer kunne sammenlignes uden manuelle screenshots.</p><h3>GRIB-cache mellem kørsler</h3><p>GitHub-caches kan ikke overskrives under samme nøgle. Derfor blev hver gennemført kørsels rå DMI-cache gemt under en unik nøgle, mens næste kørsel gendannede den seneste kompatible cache.</p><p>Den historiske ændring reducerede gentaget marine warmup uden at svække collections, horisont, proveniens eller audits.</p>"},{"id":"state-shadow-v2","chapter":"Historisk tilstand","title":"Historisk: verificeret strømhistorik før state 6","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Dette afsnit beskriver den historiske <code>shadow-v2</code>-forløber, som blev afløst af Candidate G. Den aktive lokale integrerede kontrakt står i kapitel 89.</div><h3>Det historiske forsøg</h3><p><code>inboundCurrentDurationHours</code>, <code>outboundCurrentDurationHours</code> og <code>activeCurrentRegime</code> afprøvede sammenhængende verificeret strøm uden at gøre missing til nul.</p><h3>Gældende lokal kontrakt</h3><p>Den integrerede 1.1-kandidat bruger state <code>6.0.0</code>. Gridstrøm vægtes fuldt i 24 timer og cosinusdæmpes til nul ved 48 timer. Direkte inputmangel er <code>UNAVAILABLE</code>; manglende historik omsluttes med en konservativ lower/upper-score uden at opfinde målinger. Candidate G forbliver den eneste offentlige model i 4.0.316, indtil state 6 er exact-head-, produktions- og browserverificeret; <code>shadow-v2</code> er aldrig en sideløbende offentlig model.</p>"},{"id":"dmi-vector-null-safety-4-0-116","chapter":"Data og prognoser","title":"DMI-vektorer og manglende vejrfelter","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Strøm og vind må kun dannes af U/V-komponenter fra samme fysiske DMI-gitterpunkt. Manglende vind eller bølger vises som <strong>Mangler</strong> og må ikke blive til 0,0.</div><h3>Samme punkt for begge komponenter</h3><p>En strøm- eller vindvektor består af U og V. RavRadar søger efter det nærmeste fysiske DMI-gitterpunkt, hvor begge komponenter er gyldige. Hvis der ikke findes et fælles punkt inden for den tilladte afstand, bruges ingen konstrueret vektor.</p><h3>Vandstandskilder er ikke forecastzoner</h3><p><code>SOURCE::</code>-punkter bruges kun til DKSS-vandstand. De samples ikke for strøm, vind, bølger eller vandtemperatur og tæller ikke i forecastzonernes komponentdækning.</p><h3>Mangler er ikke nul</h3><p><code>null</code>, tomme og ikke-numeriske værdier betyder manglende data. De må ikke blive til vindstille, fladt hav eller retning 0°. En eksplicit numerisk 0-værdi fra datakilden er derimod gyldig og bevares.</p>"},{"id":"dmi-first-wind-tail-4-0-118","chapter":"Data og prognoser","title":"DMI-first vind gennem fem døgn","summary":"HARMONIE bruges først, og DKSS forlænger vinden uden at blande modellerne. Fra 4.0.120 bevares den komponentvise fallback under vandstandsrouting, og fallback henter 120 fremtidige timer.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> HARMONIE er primær vindkilde. Når dens valide horisont slutter, kan DKSS'' separate 10-meter U/V-vind forlænge serien mod fem døgn.</div><p>HARMONIE vinder altid i overlap. Interpolation sker kun inden for den enkelte model og aldrig på tværs af modelgrænsen. Hver færdig vindtime angiver HARMONIE, DKSS eller fallback som kilde.</p><p>Open-Meteo bruges kun ved manglende DMI-timer og leverer entydige UTC-tider. RavRadar er gratis og ikke-kommerciel, men fair use, caching og kreditering gælder stadig. Frisk produktion skal bevise den faktiske femdøgnsdækning.</p>"},{"id":"dmi-hourly-provenance-4-0-125","chapter":"Data og prognoser","title":"Sådan spores en DMI-time tilbage til modellen","summary":"Collection, modelkørsel og native kildetider følger hver intern DMI-komponenttime.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En DMI-værdi gemmes sammen med identiteten på den modelkørsel og det forecasttrin, der leverede den.</div><p>RavRadar fører collection, modelkørsel og native gyldighedstid videre separat for vind, bølger, strøm, vandstand og vandtemperatur. Lead time viser afstanden fra modellens start til prognosetimen, og prognosealderen viser modellens alder ved datasætbygningen.</p><p>En interpoleret time henviser til begge native kildetidspunkter. Trin fra forskellige modelkørsler må ikke blandes; uden en dokumenteret sammenhængende serie forbliver værdien manglende. Sporbarheden ligger i den beskyttede diagnosefil, mens brugerfilen forbliver lille. RavScore er uændret.</p>"},{"id":"systemic-4-0-117-codex","chapter":"61","title":"4.0.117 – systemisk drift, DMI-dybdelag og Codex-overgang","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> 4.0.117 viser, hvordan RavRadar skal fejlrettes som et samlet system, hvordan DMI-dybdelag håndteres, og hvordan Codex skal arve projektets viden.</div><h3>Hvorfor hele kæden skal undersøges</h3><p>En rød zone eller en fejlet test er et symptom, indtil det er bevist hvor den korrekte information bliver forkert eller forsvinder. RavRadar skal derfor følges fra central adminopsætning og DMI-kilde gennem scheduler, cache, parser, provenance, score og public runtime helt til test og deployment.</p><h3>DMI-current i flere vertikallag</h3><p>DKSS kan levere strøm-U og strøm-V i flere dybdelag. En gyldig RavRadar-vektor kræver samme forecasttid, samme fysiske gitterpunkt og samme vertikallag. Fra 4.0.117 holdes kandidater adskilt pr. lag, og parsergeneration 11 genbehandler assets med denne kontrakt.</p><h3>Administratorens geometri er produktionsdata</h3><p>Kystlinje, land-/havpunkt og retning kan ændre DMI-opslag og lokal kystretning. Når administratoren gemmer en gyldig central ændring, skal den bruges før vejrproduktionen. I den friske #1750-kørsel blev de seneste Limfjord-geometriændringer hentet og anvendt korrekt. Tests skal beskytte propagation og integritet, ikke gamle koordinater.</p><h3>Stabilitet</h3><p>Lokalt valideret, CI-valideret og produktionsverificeret er forskellige niveauer. En DMI-/Supabaseændring kaldes ikke stabil på baggrund af lokale tests alene. 4.0.117 commit 6c1dece… med grønne #1749 og #1750 er dokumenteret overgangsbaseline.</p><h3>Forecastkant og manglende data</h3><p>Manglende værdier i yderste forecasttimer er ukendte. De må ikke forlænges med sidste værdi eller gøres til nul. Dækningshuller undersøges separat i kilde, scheduler, merge og horisont.</p><h3>Codex</h3><p>Codex starter i docs/ai/CODEX_START_HERE.md. RDKS, håndbogen, AGENTS, tests og Git-historik er den persistente projekthukommelse; chatarkivet er historisk begrundelse. En ændring er først færdig, når implementering og dokumentation er synkroniseret.</p><h3>Korrektion ved Codex-overgangen: falsk grøn deployment</h3><p>#1760 demonstrerede den tidligere falsk grønne overgangstilstand. Bypasset er nu lukket: enhver positiv produktions-preflight kræver begge gates før artifactet, mens negativ preflight kan stoppe uden build og deploy. #1769 viste korrekt stop ved fejlet validate, og #1772 gennemførte central sync, frisk produktionskæde, begge gates, artifact og Pages-deploy som success. Baseline er derfor produktionsverificeret.</p>"},{"id":"coastal-geometry-v2-pilot-4-0-126","chapter":"62","title":"Kystgeometri v2: gratis GeoDanmark-pilot uden produktionsændring","summary":"En parallel pilot forbedrer kystlinjer og zoner uden at ændre score eller overskrive centrale adminrettelser. Pilot og vejrproduktion har adskilte køer.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar undersøger nu bedre dansk kystgeometri i en lukket pilot. Den offentlige score og de aktive zoner ændres ikke af pilotkørslen.</div><p>Den nuværende zonegeometri har overlap, for grove kystlinjer og enkelte geografisk misvisende navne. Kystgeometri v2 bygger derfor et parallelt forslag fra gratis GeoDanmark-kildedata. Kystlinjen beskriver relevante ravstrande og kan springe over havne, åudløb og andre ikke-søgbare strækninger. Alle indre fjorde udelukkes undtagen Limfjorden.</p><p>Piloten henter først ejerens centralt gemte zonenavne, kystlinjer, land-/havpunkter, retningsankre og slettede zoner. Et automatisk forslag må derfor ikke genoplive en slettet zone eller tavst erstatte en manuel rettelse. Konflikter bliver en reviewopgave i admin.</p><p>GeoDanmark hentes kun ved en bevidst manuelt valgt pilotkørsel, ikke i RavRadars hyppige vejrloop. API-adgangen ligger kun som en GitHub-secret og gemmes ikke i kode, logs, dokumentation eller offentlige artifacter. Rå pilotdata forbliver private. Pilot og vejrproduktion har separate GitHub Actions-køer, så rutinevejret ikke kan annullere geometrikørslen. Aktuelle bitemporale objekter vælges kun fra det præcise <code>_current</code>-lag; historiklaget <code>_hist</code> bruges ikke. Store lag hentes sidevis, og rapporten kræver dokumenteret komplethed frem for at acceptere serverens 10.000-featureloft.</p><p>En bugtet zone kan få flere navngivne kystdele med egne land- og vandpunkter. De bliver først reelle selvstændige vejrmålepunkter, når DMI-sampling, provenance, score og brugerflade er bygget og kontrolleret for hver del. Høfder og lignende mulige ravfælder registreres foreløbig som score-neutrale hypoteser; de giver ikke point uden senere faglig validering.</p><p>#1941 verificerede privat source-QA og kort. 4.0.131 klassificerer nu hvert fysisk kildestykke som tæt match, delvist match eller semantisk/grænsemæssigt review. Zonenavne sammenholdes geografisk med Danmarks officielle stednavneregister via en nøglefri offentlig kilde. Navne og rå kyststykker er kun reviewmateriale og kan ikke aktiveres automatisk.</p><div class=\"callout\"><strong>Status:</strong> Blåvand ligner geometriopretning; Rømø og Thisted kræver semantisk flyttereview; seks øvrige pilotzoner kræver grænse-/partitionsreview. Næste fase samler kontrollerede stykker til kystdelsforslag med eksplicitte havn-, å- og fjordfravalg. En landsdækkende ændring kræver senere et særskilt go/no-go.</div>"},{"id":"national-local-part-names-4-0-154","chapter":"62","title":"Officielle navneforslag til hele den lokale kystbestand","summary":"Den friske nationale opdeling giver 783 private lokale kystdele med revisionsbare officielle navneforslag uden automatisk aktivering.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar har nu et officielt, revisionsbart navneforslag til hver af de 783 private lokale kystdele.</div><p>#2107 verificerede den friske centralt hydrerede nationale kilde-, topologi-, kystdels-, stednavne- og lokalitetskæde. De 28 for grove dele erstattes af 56 kortere forslag; ingen forbindelseslinjer tegnes over fysiske spring.</p><p>4.0.154 vælger navneforslag fra Danmarks officielle stednavneregister med kandidat-ID, afstand, relevansklasse og alternativer. Strand- og kystnavne samt nære lokale bebyggelser prioriteres; havne er kun kontekst. Den tidligere ankermanglende Hou/Bisnap-del får lokal evidens ved Hou i stedet for et opdigtet navn.</p><div class=\"callout\"><strong>Afgrænsning:</strong> Navnene er private forslag. De ændrer ikke central admin, aktiv geometri, DMI-sampling, state, offentlig brugerflade eller RavScore.</div>"},{"id":"national-local-part-points-4-0-155","chapter":"62","title":"Lokale land- og vandpunkter med modsat-side-bevis","summary":"774 af 783 private lokale kystdele har et første sikkert punktpar; ni forbliver blokeret til native DMI-gridreview.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar kopierer ikke længere tankemæssigt ét gammelt zonepunkt ud på alle bugtede kystdele.</div><p>4.0.155 beregner en lokal kystnormal ved hver del. Et land-/vandpunktpar foreslås kun, når et officielt landvidne og enten et officielt Farvand-vidne eller zonens centralt hydrerede marinepunkt ligger på modsatte sider. 774 af 783 dele består denne første port.</p><p>Ni dele har modstridende eller utilstrækkelig sideevidens. De får null som punktpar og præcis to neutrale normalalternativer til næste native DMI-gridkontrol. Et grønt teknisk gridpunkt er ikke i sig selv aktivering; provenance, lokale serier, state, UI og admin skal stadig valideres.</p><div class=\"callout\"><strong>Afgrænsning:</strong> Alle punktpar er private og score-neutrale. Vejrsampling og automatisk aktivering er fortsat slået fra.</div>"},{"id":"national-local-part-dmi-grid-4-0-158","chapter":"62","title":"Native DMI-gridgate for hele den lokale kystbestand","summary":"774 valgte vandpunkter har native havgridbevis; 752 har fuld WAM+DKSS-dækning, mens 22 har et eksplicit komponentgab.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Et vandgrid kan være gyldigt, selv om DMI ikke leverer alle modelkomponenter dér.</div><p>#2127 verificerede relevante modelområder for vest, øst og Limfjorden. 752 valgte punkter har både komplette bølge- og DKSS-familier. 18 har komplet DKSS uden WAM, og fire har komplet WAM uden DKSS. Alle 774 har dermed mindst én komplet native havmodelfamilie.</p><p>4.0.158 adskiller vand/gridbevis fra fuld vejrdækning. Manglende komponentfamilier registreres eksplicit og bliver aldrig nul. De ni tvivlsomme normalsider forbliver blokerede, fordi ingen kun har én entydigt gyldig side.</p><div class=\"callout\"><strong>Afgrænsning:</strong> Ingen rå vejrserie, geometri, admin-data, state, RavScore eller offentlig aktivering ændres.</div>"},{"id":"national-weather-shadow-4-0-159","chapter":"62","title":"Isolerede private serieidentiteter for hele landet","summary":"774 validerede kystdele får hver sin private serie- og historikidentitet uden sampling, fallback eller RavScore-påvirkning.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Hver lokal kystdel får sin egen tomme, låste vejrkanal, før der hentes egentlige tidsserier.</div><p>4.0.159 binder 774 gridvaliderede dele til hver sin serieidentitet, historiknøgle, samplingpoint og dokumenterede native gridproveniens. En del må ikke låne parent-zonens eller en nabodels data. De 22 kendte komponentgab forbliver missing, og de ni tvivlsomme dele får ingen kontrakt.</p><p>194 zoner har private delkontrakter; 14 zoner forbliver helt uændrede. Alle 208 eksisterende parent-zoner er fortsat eneste autoritative runtime-, historik- og RavScore-sandhed.</p><div class=\"callout\"><strong>Afgrænsning:</strong> Kontrakten sampler ikke vejr og ændrer ikke state, UI, admin eller score. Flertidsserie- og provenancegaten kommer bagefter.</div>"},{"id":"national-multi-step-series-4-0-160","chapter":"62","title":"Private native flertrinsserier for hele landet","summary":"Hver tilgængelig WAM-/DKSS-familie skal bestå mindst to native tidstrin uden fallback, rådata i artifact eller RavScore-påvirkning.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar kontrollerer nu, at hver lokal vejrkanal kan bære en rigtig tidsserie, før state eller score overhovedet må kobles til.</div><p>#2146 verificerede 774 marine serier og 9.156 komponentbeviser. #2152 verificerede derefter 770 isolerede shadow-historikker; fire WAM-only dele forbliver uden state og må ikke låne parentdata eller blive til nulstrøm.</p><p>#31448258035 verificerede hele den private nationale kæde: 774 native vindserier, 752 komplette shadow-scorer, 22 deldækkede og ni blokerede dele.</p><p>Den private shadow-score bruger den eksisterende scoremotor på eksakt tidsfælles lokale data. 7-pointreglen klassificerer hele zonen, kun én del, flere dele eller usikker dækning.</p><p>Den manuelle reviewside viser én kystdel ad gangen på et stort almindeligt kort eller luftfoto. Den valgte del har en kraftig blå linje og automatisk zoom; de 31 opmærksomhedsdele kommer først. Ejeren kan godkende, markere til rettelse, skrive en bemærkning og eksportere resultatet lokalt.</p><p>Et ægte native vandstandstidspunkt tre timer senere er påkrævet. Vindgaten henter præcis to vindfiler, hvoraf én matcher det gyldige tretimers havforløb.</p><p>Den centrale admin-roundtrip oprettede, læste, opdaterede og slettede tempkladden, mens beskyttede dokumenter forblev uændrede.</p><div class=\"callout\"><strong>Afgrænsning:</strong> Geometri, sampling, state, RavScore, admin og offentlig runtime er fortsat deaktiveret, indtil ejerens manuelle review og go/no-go er bestået.</div>"},{"id":"coastal-parts-private-4-0-132","chapter":"62","title":"Kontrollerede private kystdelsforslag","summary":"GeoDanmark-stykker samles konservativt med eksplicitte havn-, å- og fjordfravalg uden produktionsændring.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Piloten kan nu samle fysisk støttede kyststykker til review, men intet aktiveres automatisk.</div><p>Kun stykker, der følger eller delvist matcher den eksisterende kyst, kan indgå. Semantisk tvivlsomme stykker stoppes. Havne og faktiske kystskærende, synlige vandløbsmidter udskæres med dokumenterede afstandsbånd og deduplikeres. Nærliggende fysiske fragmenter kan tilhøre samme multipart-kystdel, men systemet tegner ingen opdigtet forbindelse over springet.</p><p>Fjordpolitikken er eksplicit pr. pilotområde: ydre vestkyst, Limfjorden bevidst inkluderet og indre fjorde/nor ved Lolland-Falster udelukket fra automatisk forslag. Prøven på det verificerede #1948-artifact gav 84 private reviewforslag. Rømø gav sikkert nul, fordi alle fire kildestykker kræver semantisk review.</p><div class=\"callout\"><strong>Afgrænsning:</strong> Forslagene vises orange på private kort. De ændrer ikke aktive zoner, admin, land-/vandpunkter, DMI-sampling, offentlig produktion eller RavScore.</div>"},{"id":"coastal-geographic-review-gate-4-0-133","chapter":"62","title":"Geografisk reviewgate og officielle fjordpolygoner","summary":"Private zonekort og officielle vandpolygoner stopper fejlplacerede zoner før DMI-punkter og produktion.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En skrevet fjordregel er ikke nok. Piloten håndhæver nu reglen geometrisk og vurderer hver zone separat.</div><p>Dataforsyningens nøglefri officielle stednavnekilde leverer Farvand-polygoner som GeoJSON. Undertypen fjord og nor udskæres overalt uden for Limfjorden. Maskerne gemmes privat med navn og kilde-ID og vises rosa. Den lokale prøve faldt fra 84 til 72 reviewdele.</p><p>Ni højopløselige zonekort viser nuværende linje, fysisk GeoDanmark-kyst, forslag, fravalg og officielle stednavne. Kun Blåvand er frigivet til næste private detailopretning. Rømø og Askø/Lilleø kræver semantisk flytning; seks andre zoner kræver grænse- eller partitionsredesign.</p><div class=\"callout\"><strong>Sikkerhed:</strong> Ingen zone er produktionsgodkendt. De otte strukturelt forkerte zoner må ikke få nye DMI-punkter, før geografi og migration er besluttet. Aktive zoner, admin og RavScore er uændrede.</div>"},{"id":"blaavand-private-detail-4-0-134","chapter":"62","title":"Privat Blåvand-detailforslag","summary":"Blåvands Huk opdeler to retningsmæssige kystdele med kontrolleret landside, private punktpar og score-neutrale høfter.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Kun Blåvand er gået videre fra reviewgaten, og resultatet er stadig privat.</div><p>Den fysiske GeoDanmark-kyst splittes ved det officielle Blåvands Huk. Nordkysten og den sydøstgående strækning mod Hvidbjerg får hvert sit navn og sit eget lokale land-/vandpunktpar. Kystfragmenterne forskydes 15 meter mod den side, som de centralt verificerede adminankre dokumenterer som land.</p><p>Ni GeoDanmark-høfter registreres separat som mulige ravfælde-hypoteser. De indgår ikke i kystlinjen og ændrer ikke RavScore. Punktparrene har ingen vejrsampling.</p><p>#1982 gav ortofotogo, #1987 bekræftede forskellige DMI-celler, #1997 bekræftede komplette private flertidsserier, og #2004 bekræftede separat score-neutral historik.</p><div class=\"callout\"><strong>Privat UI-gate:</strong> #2009 verificerede, at 4.0.141 bevarer den aktive parent-zones RavScore-farvede kystlinje, score og rangering. De to delkonturer vises neutralt, stiplet og tydeligt som ikke aktive; delscore, scorefarve, \"bedste del\", klik og tooltip er forbudt. #2008 bestod fulde produktionsgates og deploy. Sampling, state, offentlig UI og admin-write er fortsat deaktiveret.</div><div class=\"callout\"><strong>Privat admin-gate:</strong> 4.0.142-kandidaten bruger kun en unik midlertidig kladde, som læses, opdateres og slettes. De autoritative kystlinje- og retningsdokumenters hash og version skal være uændrede. Dette er rollbackbevis, ikke aktivering.</div>"},{"id":"national-geometry-source-plan-4-0-143","chapter":"62","title":"National kildeplan for hele Danmark","summary":"Den centralt effektive 208-zoners bestand opdeles automatisk i private officielle kildefliser med konfliktkontrol.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar har nu den første automatiske plan for hele Danmarks kyst, men ingen ny kyst er aktiveret.</div><p>Efter central adminhydrering og tombstones kræver planen præcis 208 aktive zoner. Kysten opdeles i reproducerbare GeoDanmark-fliser. Kendte geografiske fejl og enhver central ændring klassificeres som reviewkonflikter, så ejerens data ikke overskrives.</p><p>Et separat privat job henter gratis officielle kyst-, havne-, vandløbs-, høfde-, klit- og skræntlag og fjerner dubletter mellem fliser. Jobbet har ingen Pages-rettigheder og ændrer ikke geometri, admin, vejr, state eller RavScore.</p><div class=\"callout\"><strong>Status:</strong> 4.0.143 er kilde- og planlægningsgaten. Nationalt CI-artifact, topologi, lokale datapunkter og den fulde aktiveringskæde mangler fortsat.</div>"},{"id":"national-source-validation-4-0-144","chapter":"62","title":"National skalerings- og komplethedsgate","summary":"Begrænset parallel hentning, strenge filkontroller og rumligt indekseret QA beskytter den nationale kildekæde.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Den første nationale måling viste 101 fliser og 707 requests. 4.0.144 gør kæden hurtigere og kontrollerer resultatet strengere.</div><p>Højst fire fliser hentes samtidig, og hvert afsluttet trin logges. Før det private artifact accepteres, skal alle 208 zoner være dækket, alle eksponerede lag være komplette, filhash stemme, dubletter være målt og credentials være fraværende.</p><p>Derefter bruger RavRadar et rumligt indeks til at sammenholde officielle kystobjekter med alle zoner uden en langsom alle-mod-alle-sammenligning. Planens konfliktklasse følger med til review.</p><div class=\"callout\"><strong>Ingen aktivering:</strong> Kæden ændrer ikke aktiv kyst, admin, vejr, state, offentlig UI eller RavScore.</div>"},{"id":"national-compact-qa-artifact-4-0-145","chapter":"62","title":"Kompakt national QA-pakke","summary":"Plan, manifest og 208-zone-QA kan auditeres privat uden at hente hele råpakken.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> #2029 verificerede 208 zoner og den central-hydrerede plan med 100 fliser og 700 lagforespørgsler. Hentningen tog cirka 5 minutter og 15 sekunder, og både kildevalidator og rumlig QA bestod.</div><p>Det fulde private råartifact er 413 MB komprimeret og bevares som reproducerbart kildebevis. #2033 verificerede plan, manifest og begge QA-filer i en separat kompakt pakke på 6,8 MB. Det gør konflikter, dækning, featureantal og deduplikering hurtige at gennemgå uden at offentliggøre rådata.</p><div class=\"callout\"><strong>Fortsat read-only:</strong> Ingen aktiv geometri, admin-data, vejrsampling, state, offentlig UI eller RavScore ændres.</div>"},{"id":"national-topology-audit-4-0-146","chapter":"62","title":"National read-only topologiaudit","summary":"Officielle fjorde, havne og åmundinger samt kystrelevansevidens måles før nationale dele kan foreslås.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Kun 20 af 208 zoner er direkte referenceklare; 188 er flagget. Blind flytning til nærmeste kyst er derfor forkastet.</div><p>4.0.146 henter officielle fjord- og norpolygoner og maskerer dem uden for Limfjorden. GeoDanmark-havne, vandløb, klit, skrænt og høfter måles read-only.</p><p>#2055 verificerede 755 private multipart-dele og officielle stednavnekandidater til dem alle. 4.0.152 opdeler de 28 grove dele i 56 lokale forslag på højst 20 km. Nærliggende kildefragmenter grupperes uden at tegne over spring; kildelinjen bevares 1:1. Kandidaterne omdøber ikke automatisk.</p><div class=\"callout\"><strong>Ingen aktivering:</strong> Topologiauditen ændrer ikke centrale admin-data, aktiv geometri, DMI-sampling, state, offentlig UI eller RavScore.</div>"},{"id":"national-owner-inner-water-follow-up-4-0-172","chapter":"62","title":"Ejerafgørelser og målrettet kontrol af indre farvande","summary":"De 31 afgørelser bevares privat, og en streng landsaudit viser kun de resterende dele med flere uafhængige faresignaler.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Ejeren har gennemgået de 31 første kontrolpunkter. Klare sletninger, navnerettelsen og løse komponenter kan nu danne private forslag, mens præcise beskæringer ikke må gættes.</div><p>Den supplerende kontrol læser alle officielle Farvand-typer og havne samt måler afstand til officielt åbent hav og små lukkede ø-/søformer. Et navn eller en afstand kan aldrig stå alene. Nye dele vises kun, når mindst fire uafhængige tegn peger på indre farvand eller teknisk fejl, og identisk geometri vises kun én gang.</p><div class=\"callout\"><strong>Status:</strong> Efterkontrollen er reduceret til 23 unikke dele. Geometri, admin-data, vejrsampling, state, RavScore og offentlig runtime er fortsat uændrede.</div>"},{"id":"national-owner-review-complete-4-0-173","chapter":"62","title":"Afsluttet ejerreview og dubletkontrol","summary":"Den supplerende gennemgang er afsluttet, og samme fysiske kyst sendes ikke tilbage under et andet teknisk ID.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Ejeren har afgjort de sidste 23 kontrolpunkter: 15 sletninger, tre godkendelser og fem præcise rettelser.</div><p>En metrisk kontrol fandt 12 ekstra tekniske ID''er, der dækker allerede bedømte fysiske linjer. De arver afgørelsen; ved en beskæring beholdes kun den del, der følger den rettede kystlinje. Derfor er den resterende efterkontrol tom.</p><div class=\"callout\"><strong>Fortsat privat:</strong> Forslaget er visuelt kontrolleret, men ændrer endnu ikke admin-data, offentlig geometri, vejrsampling, state eller RavScore.</div>"},{"id":"national-once-only-final-coast-4-0-174","chapter":"62","title":"Én fysisk slutkyst og nye land-/vandpunkter","summary":"Nabozoners kopier samles til 603 unikke dele uden overlap, før punkter og DMI kontrolleres igen.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Slutkontrollen fandt 311 overlap mellem forskellige zoner. De 753 tilbageværende tekniske dele er samlet til 603 fysiske dele med nul overlap.</div><p>Hvert fælles kyststykke tildeles den zone, som er bedst forankret i den centralt gemte zonekyst og datapunktet. Hammer Odde har en eksplicit grænse ved nordspidsen. Land-/vandpunkter beregnes først efter denne samling; seks tydelige sider er dokumenteret kartografisk, så alle 603 dele lokalt har et punktpar.</p><p>4.0.175 retter den gamle 783-dels kontrol til den dokumenterede fordeling 758 komplette, 22 deldækkede og tre blokerede efter de seks godkendte sideafgørelser. Kystlinjer, punkter og RavScore ændres ikke af denne rettelse.</p><div class=\"callout\"><strong>Fortsat privat:</strong> Native DMI-grid, marine serier, state, vind og shadow-score skal bestå igen på slutbestanden. Ingen automatisk aktivering er tilladt.</div>"},{"id":"national-coastal-parts-activation-4-0-176","chapter":"62","title":"Aktive lokale kystdele i hele Danmark","summary":"Historisk 4.0.182-milepæl: 643 ejer-godkendte kystdele gav 206 præcise hovedzonekyster, mens seks zoner bevarede sikker fallback.","body":"<div class=\"reader-guide\"><strong>Historisk milepæl:</strong> Dette afsnit beskriver 4.0.182-bestanden. På det tidspunkt viste RavRadar 212 hovedzoner. 206 fik deres synlige kyststreg fra 643 præcise lokale beregningsdele; seks bevarede deres gamle linje, fordi intet sikkert nyt forløb kunne godkendes. Den aktuelle centrale bestand er 210 efter senere ejerbesluttede sletninger; se kapitel 70.</div><p>Delene er ikke selvstændige kortzoner. Brugeren ser ét navn, én klikflade, én scorefarve og kun to ydre sorte grænsemarkeringer pr. hovedzone. Interne beregningsgrænser vises ikke.</p><p>Alle 643 dele har land- og vandpunkt. 632 har fuld marin DMI-dækning og 11 har dokumenteret deldækning. De 39 nye eller ændrede punkter bestod native WAM- og DKSS-kontrol i #31532688885. En korrigeret symmetrisk kontrol fjernede 11 oversete dubletdele; slutbestanden har nul tværzoneoverlap og nul uafklarede relevante kysthuller.</p><p>Vadehavets fastlandskyst fra Emmerlev mod Esbjerg indgår i tre hovedzoner. Rømødæmningen og økyster er ikke del af fastlandslinjen. De to ejer-godkendte forbindelser ved digekysten og Ribe Å er dokumenterede undtagelser.</p><p>DMI-data hentes fortsat som samlede modelfiler, og hver del bruger sit eget kontrollerede vandpunkt. Den højeste gyldige delscore bestemmer hovedzonens score efter den eksisterende syvpunktsregel. Manglende data forbliver manglende; RavScore-reglerne er ikke ændret i 4.0.182.</p><p>Efter aktivering kan den hash-låste bestand kontrolleres i et privat read-only kort med både samlet landsvisning og søgning på hver del. Kortet kan dokumentere problemer, men kan ikke selv rette eller aktivere geometri.</p><div class=\"callout\"><strong>Kontrol:</strong> #31533385967 beviste den deaktiverede runtimepakke og Supabase-roundtrip/rollback uden ændring af beskyttede admin-dokumenter.</div>"},{"id":"admin-main-zone-boundaries-4-0-183","chapter":"62","title":"Redigering af hovedzonernes længde","summary":"En hovedzone forlænges eller forkortes ved at flytte eksisterende, kontrollerede kystdele med alle deres data.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Administratoren vælger den hovedzone, som skal modtage en strækning, og klikker på en grå nabokystdel. Kystdelen bliver orange og følger samlet med til zonen.</div><p>En kystdel er en teknisk beregningsenhed under en forståelig hovedzone. Den har præcis geometri, eget landpunkt, vandpunkt, DMI-gridbevis og lokal scoreidentitet. Ved en grænseændring genbruges disse verificerede oplysninger; systemet tegner ikke et nyt gættet målepunkt.</p><p>Produktionsbygningen kræver én aktiv hovedzoneejer pr. del. Ukendte eller slettede modtagere afvises. Derfor kan en ren ejerskabsflytning ikke skabe et nyt fysisk overlap: den samme geometri flyttes, men kopieres ikke.</p><p>Det offentlige kort viser ikke de interne dele. Det viser én samlet hovedzonefarve og kun et lille sort skel, hvor to forskellige hovedzoner mødes. Ved <em>Tilbage til oversigten</em> vises hele Danmark igen.</p><div class=\"callout\"><strong>Begrænsning:</strong> Hvis en ønsket kyst ikke allerede findes blandt de godkendte dele, kræver den en ny geometri-, land/vand- og DMI-kontrol. Ejerskabseditoren må ikke opfinde ny fysisk kyst.</div>"},{"id":"admin-coast-boundary-drag-4-0-186","chapter":"62","title":"Træk kystgrænsen og brug viskelæderet","summary":"Admin kan flytte en zoneende til en valideret nabokystdel eller deaktivere en hel del uden at skille dataene ad.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Træk endehåndtaget til en eksisterende valideret nabokystdel. Kyst, landpunkt, vandpunkt, DMI-grid og lokal scoreidentitet flyttes samlet, og zonegrænsen følger automatisk.</div><p>Viskelæderet deaktiverer en hel valideret del og dens datakontrakt. Den stiplede del kan gendannes. Central readback kontrollerer både ejerskab og deaktivering.</p><div class=\"callout\"><strong>Begrænsning:</strong> Fri ny kystgeometri får ikke opdigtede målepunkter eller DMI-data. Den skal først gennem privat geometri-, punkt-, grid- og scorekontrol.</div>"},{"id":"local-zone-score-explanation-4-0-184","chapter":"62","title":"Hvilken del af zonen scorer højest?","summary":"Hovedzonens score forklares med navnet og scoren på den lokale kystdel, som faktisk leverer resultatet.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En hovedzone kan bestå af flere præcise kystdele med forskellig retning og forskellige forhold. Når forskellen er mere end 7 point, fortæller zonepanelet tydeligt, hvilken del der scorer højest, og at resten af zonen kan være dårligere.</div><p>Ved højst 7 points forskel behandles forholdene som ens nok til at gælde hele zonen. Ved større forskel vises enten én klart bedste del eller flere dele, som ligger inden for 7 point af maksimum. Navn og RavScore vises for hver fremhævet del.</p><p>De tre delscorer og deres faglige begrundelser kommer fra den samme lokale kystdel som totalscoren. Det sikrer, at forklaring, debug, assistent og observationsdata ikke blander en lokal totalscore med den gamle hovedzonelinjes beregning.</p><div class=\"callout\"><strong>Uændret model:</strong> Funktionen forklarer den eksisterende lokale score. Den ændrer ikke RavScore-vægte, DMI-data, geometri eller syvpunktsgrænsen.</div>"},{"id":"national-land-water-stage-gate-4-0-199","chapter":"62","title":"Land- og vandrettelser gennem hele kystbygningen","summary":"Foreløbige dele må vente på ejerrettelser, men slutbestanden skal indeholde alle dokumenterede punktrettelser.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Den nationale kyst bygges i flere trin. Nogle ejer-godkendte kystdele findes først efter den foreløbige punktkontrol.</div><p>Den foreløbige kontrol anvender alle rettelser, som allerede findes, og registrerer resten med deres konkrete id som udskudte. Efter ejerrettelserne bygges punkterne igen.</p><p>Hvis den uafhængige 10-meterkontrol leverer et sikkert korrigeret punktpar, fjernes den gamle blokering på selve rækken, men DMI, state, score og aktivering forbliver slukket, indtil deres egne kontroller består.</p><div class=\"callout\"><strong>Streng slutkontrol:</strong> I den endelige bestand skal hver dokumenteret land-/vandrettelse findes og anvendes. Ellers stopper workflowet før DMI-kontrol, artifact og aktivering.</div>"},{"id":"national-owner-review-derived-counts-4-0-201","chapter":"62","title":"Gennemgangskortet følger den kontrollerede kystbestand","summary":"Review og admin-rundtur bruger den faktisk validerede delbestand uden at svække kontrollen med et fast historisk antal.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Antallet af tekniske kystdele kan ændre sig, når en dokumenteret kyst opdeles efter retning eller lokalitet. Det må ikke kræve en ny skjult kodekonstant.</div><p>Privat kørsel #31798588868 dokumenterede 835 indbyrdes konsistente dele: 828 med komplet datagrundlag, fire med deldækning og tre blokerede. Kørselens kyst-, punkt-, DMI-, vejr-, state-, vind- og shadow-kontroller bestod før det gamle 783-tal stoppede reviewet.</p><p>Gennemgangskortet og den centrale admin-roundtrip kræver nu i stedet, at geometri, navne, punktstatus, shadow-score-ID''er og alle optællinger er 1:1. Ændres ét led alene, stopper kæden fortsat.</p><div class=\"callout\"><strong>Ingen aktivering:</strong> Rettelsen ændrer ikke offentlig kyst, vejrdata eller RavScore. En ny fuld privat slutkørsel og ejerens særskilte go/no-go er stadig nødvendige.</div>"},{"id":"national-dmi-grid-private-budget-4-0-202","chapter":"62","title":"Landsdækkende DMI-kontrol må få tid til at afslutte","summary":"Et langsomt DMI-kald må ikke forveksles med et forkert vandpunkt, men kontrollen må heller ikke springes over.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Alle private vandpunkter kontrolleres på DMI''s egne gitre. Når 835 dele kontrolleres mod flere bølge- og strømmodeller, kan samme korrekte kontrol variere flere minutter i køretid.</div><p>#31798588868 bestod på 8,5 minutter, mens #31802022918 nåede det gamle standardloft efter 11,1 minutter under sidste model. Derfor får de tre landsdækkende private DMI-gates nu 3.000 sekunder, som allerede bruges af vindkontrollen.</p><div class=\"callout\"><strong>Kravene er uændrede:</strong> Fælles U/V-celle, gyldig afstand, modelproveniens og fail-closed-adfærd bevares. Ekstra tid er ikke en godkendelse af manglende data, og intet aktiveres offentligt.</div>"},{"id":"progressive-public-runtime-4-0-216","chapter":"60","title":"Hurtigt kort før alle femdøgnsdetaljer","summary":"Aktuelle forhold og dagens rangliste vises fra en lille startpakke; prognoser og kystdelsdetaljer følger straks efter.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar henter ikke længere hele landsprognosen og alle lokale kystdeles timeresultater, før kortet kan blive klart.</div><p>Startpakken indeholder aktuelle forhold, kompakt historisk tilstand, pilegrundlag og de kystdele, der vinder aktuelt for waders eller strand. Hele femdøgnsprognosen og alle øvrige kystdelsdetaljer bevares i en separat pakke, som hentes umiddelbart bagefter.</p><div class=\"callout\"><strong>Samme faglige indhold:</strong> Historik, vejr, RavScore, missing-regler og lokale kystdele slettes ikke. Start- og detaljepakken skal have samme dataset-id; ellers afvises detaljerne, mens aktuelle forhold fortsat kan vises.</div>"},{"id":"one-point-pair-per-coastal-part-4-0-207","chapter":"70","title":"Ét flytbart land-/havpunktpar pr. kyststrækning","summary":"Admin flytter det eksisterende punktpar; ekstra par oprettes ikke, og ændringen aktiveres først efter central og DMI-baseret validering.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Hver lokal kyststrækning har ét blåt havpunkt og ét grønt landpunkt. De to markører kan trækkes, men admin opretter ikke flere aktive punktpar på samme strækning.</div><p>Punktparret er fælles sandhed for DMI-sampling, den røde hav→land-retning, den lokale score og den offentlige forklaring. På en bugtet strækning placerer ejeren parret ved det sted, der bedst repræsenterer den relevante ravstrand. Det er et bevidst, dokumenteret kompromis i stedet for automatisk at opdele hele landet igen.</p><p>De tidligere knapper <em>Sæt nyt havpunkt</em> og <em>Sæt nyt landpunkt</em> er fjernet. Træk af de eksisterende markører, rød pil, geometrikontrol og central gemning er bevaret. Efter <em>Godkend og gem centralt</em> skal systemet læse ændringen tilbage og derefter bestå en frisk DMI-/releasekørsel. Ved fejl aktiveres kladden ikke.</p><p>Hvis kun det ene punktmål flyttes eller rettes, nulstilles kun historikken for dette ændrede mål. Den uændrede søsterkontekst beholder sin dokumenterede Candidate G-historik. En ny prøve i samme time erstatter kun det valgte måls prøve; øvrige punkters state må ikke nulstilles.</p><div class=\"callout\"><strong>Manuel gennemgang:</strong> Ejeren kan gennemgå zonerne gradvist. Det blokerer ikke uafhængigt roadmaparbejde, men skal afsluttes før endelig faglig godkendelse af alle lokale RavScores, større scorekalibrering og domæne-/brugerrelease.</div>"},{"id":"verified-current-history-readiness-4-0-220","chapter":"60","title":"Historisk 4.0.220: rå og verificeret strømhistorik","summary":"Historisk revisionsspor for den første opmåling af rå og DMI-verificeret strømhistorik.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> I 4.0.220 målte RavRadar rå og DMI-verificeret strømhistorik. Tallene er ikke en aktuel gate.</div><p>Den daværende skrivebeskyttede kontrol viste antal prøver og tidsspænd for 210 zoner.</p><div class=\"callout\"><strong>Aktuel integreret kontrakt:</strong> Verificeret afledt kystnormal gridstrøm vægtes fuldt i 24 timer og cosinusdæmpes til nul ved 48 timer. Højst tre timers eksplicit hold accepteres; gamle prøver rekonstrueres ikke, og missing fyldes ikke med gentagne værdier. Manglende lokalt grundlag giver ingen erstatningsscore.</div>"},{"id":"effective-water-source-alert-4-0-221","chapter":"32","title":"Alarm for valgte vandstandskilder","summary":"En valgt aktiv kilde advarer først, når både dens DMI-prognose og routede cache nærmer sig udløb.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En midlertidigt manglende observation er ikke automatisk et databrud, hvis en gyldig DMI-prognose eller forecastcache stadig dækker.</div><p>Kun kilder, der faktisk er valgt automatisk eller af administratoren, overvåges. Alarmen bruger seneste gyldige tidspunkt fra både kildeprognose og routet cache. Den centralt gemte tærskel giver advarsel før udløb og kritisk status ved et reelt hul.</p><div class=\"callout\"><strong>Ingen modelændring:</strong> Leverende observationer og historiske/inaktive kilder cachealarmerer ikke. Alarmen ændrer ikke stationvalg, vandstandstal eller RavScore.</div><p>Produktionskontrollen viste, at gamle registerfelter på 15 og 21 zoner for Hals-kilderne var forældede. Den faktisk producerede serie brugte dem både før og efter rettelsen i 5 og 6 zoner. Alarmen følger nu denne faktiske rute; stationvalget blev ikke ændret.</p>"},{"id":"independent-dmi-model-cycles-4-0-222","chapter":"33","title":"Sådan tælles nye DMI-modelkørsler","summary":"Flere RavRadar-kørsler med samme DMI-modelstart er driftbevis, men ikke flere uafhængige vejrcyklusser.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En ny GitHub-kørsel er ikke nødvendigvis en ny vejrprognose. Flere RavRadar-kørsler kan genbruge samme DMI-modelkørsel.</div><p>P1-kontrollen viser nu DMI-model, modellens starttid og om værdien er native eller interpoleret. Når overgangsspring senere sammenlignes, tæller flere artifacts med samme modelstart ikke som flere uafhængige vejrcyklusser. De kan stadig bevise stabil drift og voksende historik.</p><p>Hvis en DMI-time mangler modelnavn eller starttid, står den som udokumenteret. RavRadar gætter ikke oplysningerne.</p><div class=\"callout\"><strong>Ingen modelændring:</strong> Kontrollen ændrer ingen prognose, kilde, fallback eller RavScore. Den forbedrer kun beslutningsgrundlaget.</div>"},{"id":"partial-dmi-model-cycle-4-0-223","chapter":"33","title":"Når en ny DMI-kørsel kun er delvist indfaset","summary":"P1-kontrollen viser både timer og zoner pr. modelkørsel, så en tidlig delvis cyklus ikke kaldes et fuldt bevis.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> En ny DMI-modelkørsel kan begynde med få timer, mens den forrige stadig leverer resten af prognosen.</div><p>Kontrollen viser derfor både antal timer og antal aktive zoner pr. modelkørsel. Artifact #2783 havde en ny HARMONIE 12 UTC-cyklus med 416 timer i 208 zoner, mens 03 UTC stadig bar hovedparten af vindhorisonten.</p><div class=\"callout\"><strong>Ingen modelændring:</strong> En delvis cyklus tæller som ny evidens, men fastsætter ingen permanent overgangsgrænse og ændrer ingen prognose, fallback eller RavScore.</div>"},{"id":"production-verification-4-0-238","chapter":"60","title":"Produktionsverifikation af 4.0.238","summary":"Live 4.0.238 har grøn fuld produktion, voksende verificeret strømhistorik og systematisk browserbevis for alle zoner og kystdele.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> Produktionskørsel #32344813967 gennemførte central adminhydrering, frisk DMI, samlet validering, releasegate, Supabase og Pages. Datasæt rr-20260820074127-210 indeholder 210 zoner.</div><p>De seks bølgehuller fra #3246 har nu 118 prognosetimer uden ændret DMI-first-kildeorden. Feggesund er fortsat dokumenteret bølge-missing. Verificeret strømhistorik vokser igen i de 198 geografisk verificerbare parentzoner og spænder op til 39,594 timer; de 12 reelle gitterhuller forbliver <em>Mangler</em>.</p><p>Onlinekontrollen dækker begge jagtformer, 210 zoner, 673 kystdele, 420 aktuelle paneler og 2.100 femdøgnsvalg. Score, label, farve, pile, tre scorekomponenter, forklaring, lokal kontekst, debug og seks vejrmetrikker passer sammen uden fund. Mobil og desktop har ingen overflow eller funktionsfejl.</p><div class=\"callout\"><strong>Åben driftsevidens:</strong> En naturlig produktion, som faktisk krydser en UTC-timegrænse, følges fortsat uden manuel omgåelse af readiness-gaten. Ingen land-/vandpunkter er flyttet.</div>"},{"id":"candidate-g-wave-mobilisation-memory-2026-08-23","chapter":"54","title":"Historisk Candidate G-princip: mobilisering som ét bølgeforløb","summary":"Candidate G indførte det bølgeforløb, som den integrerede kandidat analytisk genbruger med strammere missing- og migrationskontrakt.","body":"<div class=\"reader-guide\"><strong>Historisk revisionsspor:</strong> Candidate G samlede bølgehøjde og periode i én mobiliseringstilstand, så en kort top ikke lignede en udviklet storm.</div><p>Den integrerede kandidat bevarer <code>Hs² × T</code>, cirka fire timers opbygning og cirka 48 timers halveringstid. Vind og strøm giver ikke ekstra mobiliseringspoint, så samme hændelse ikke belønnes flere gange.</p><p>Missing må ikke opfinde energi. Efter længere gap kan en migreret seed ikke genopstå som frisk; genstart er tidsbundet og får højst én times ny opbygningskredit ved første ægte prøve.</p><p>Bunddybde, render, revler, lokal grundegnethed og sikkerhed indgår ikke. Candidate G er den eneste offentlige model gennem 4.0.316 og bliver ved verificeret cutover kun migrationskilde samt internt rollback-orakel.</p>"},{"id":"central-expert-handbook-validation-4-0-275","chapter":"63","title":"Håndbog og installationskopi følges ad","summary":"Repositoryets webhåndbog og Supabase-installationskopi kontrolleres allerede på PR''ens eksakte kodeversion og igen før deploy.","body":"<div class=\"reader-guide\"><strong>Kort fortalt:</strong> RavRadar har både webhåndbogen i repositoryet og en statisk Supabase-installationskopi. De skal være identiske.</div><p>Kontrollen køres nu på PR''ens eksakte kodeversion, så en glemt installationskopi opdages før merge og dyr vejrbygning. Den fulde produktionsvalidering gentager kontrollen før deploy.</p><p>Den senere beskyttede trevejsfletning af centralt godkendte ekspertændringer er uændret. Den bevarer ekspertens arbejde centralt uden at tillade skjult drift mellem installationskilderne.</p><div class=\"callout\"><strong>Uændret produkt:</strong> Rettelsen ændrer ingen RavScore-regel, vejrdata, zone, geometri eller land-/vandpunkt.</div>"}]}'::jsonb,null)
on conflict(document_key) do update set payload=excluded.payload;

-- Ingen anonym adgang til admin-tabeller eller ekspert-review.
revoke all on public.profiles,public.user_permissions,public.admin_documents,public.admin_document_versions,public.admin_audit_log,public.handbook_reviews,public.handbook_review_versions from anon;

-- Handbook reviews kræver den konkrete rettighed.
drop policy if exists "authenticated users submit handbook reviews" on public.handbook_reviews;
drop policy if exists "users read own handbook reviews" on public.handbook_reviews;
drop policy if exists "authenticated admins manage handbook reviews" on public.handbook_reviews;
drop policy if exists "authenticated reviewers read handbook review queue" on public.handbook_reviews;
drop policy if exists "authenticated admins read handbook review versions" on public.handbook_review_versions;
drop policy if exists "reviewers read handbook review versions" on public.handbook_review_versions;
drop policy if exists "experts submit handbook reviews" on public.handbook_reviews;
drop policy if exists "reviewers update handbook reviews" on public.handbook_reviews;
drop policy if exists "users or reviewers read handbook reviews" on public.handbook_reviews;
drop policy if exists handbook_review_insert on public.handbook_reviews;
drop policy if exists handbook_review_read on public.handbook_reviews;
drop policy if exists handbook_review_manage on public.handbook_reviews;
drop policy if exists handbook_review_delete on public.handbook_reviews;
drop policy if exists handbook_review_versions_read on public.handbook_review_versions;
create policy handbook_review_insert on public.handbook_reviews for insert to authenticated with check(created_by=auth.uid() and public.has_ravradar_permission('handbook_review'));
create policy handbook_review_read on public.handbook_reviews for select to authenticated using((public.has_ravradar_permission('handbook_review') and created_by=auth.uid()) or public.is_ravradar_owner() or public.has_ravradar_permission('full_admin'));
create policy handbook_review_manage on public.handbook_reviews for update to authenticated using(public.is_ravradar_owner() or public.has_ravradar_permission('full_admin')) with check(public.is_ravradar_owner() or public.has_ravradar_permission('full_admin'));
create policy handbook_review_delete on public.handbook_reviews for delete to authenticated using(public.is_ravradar_owner() or public.has_ravradar_permission('full_admin'));
create policy handbook_review_versions_read on public.handbook_review_versions for select to authenticated using(public.is_ravradar_owner() or public.has_ravradar_permission('full_admin'));
revoke all on public.handbook_reviews,public.handbook_review_versions from anon;
grant select,insert,update,delete on public.handbook_reviews to authenticated;
revoke insert,update,delete on public.handbook_review_versions from authenticated;
grant select on public.handbook_review_versions to authenticated;

-- Offentlige Edge Functions bruger en serverejet, atomisk begrænsning.
-- Browserbrugere har ingen direkte adgang til tællerne eller funktionen.
create table if not exists public.public_request_limits (
 scope text not null,
 subject_hash text not null,
 window_started_at timestamptz not null,
 request_count integer not null check(request_count>=0),
 updated_at timestamptz not null default now(),
 primary key(scope,subject_hash)
);
alter table public.public_request_limits enable row level security;
revoke all on public.public_request_limits from public,anon,authenticated;
grant select,insert,update on public.public_request_limits to service_role;

create or replace function public.consume_public_request_limit(p_scope text,p_subject_hash text,p_limit integer,p_window_seconds integer)
returns boolean language plpgsql security definer set search_path=public set row_security=off as $$
declare bucket timestamptz; current_count integer;
begin
 if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 if p_scope is null or char_length(p_scope) not between 3 and 120
  or p_subject_hash is null or char_length(p_subject_hash) not between 6 and 128
  or p_limit not between 1 and 100000 or p_window_seconds not between 10 and 86400 then
  raise exception 'INVALID_RATE_LIMIT_ARGUMENTS' using errcode='22023';
 end if;
 bucket:=to_timestamp(floor(extract(epoch from clock_timestamp())/p_window_seconds)*p_window_seconds);
 insert into public.public_request_limits(scope,subject_hash,window_started_at,request_count,updated_at)
 values(p_scope,p_subject_hash,bucket,1,now())
 on conflict(scope,subject_hash) do update set
  window_started_at=excluded.window_started_at,
  request_count=case when public.public_request_limits.window_started_at=excluded.window_started_at then public.public_request_limits.request_count+1 else 1 end,
  updated_at=now()
 returning request_count into current_count;
 return current_count<=p_limit;
end $$;
revoke all on function public.consume_public_request_limit(text,text,integer,integer) from public,anon,authenticated;
grant execute on function public.consume_public_request_limit(text,text,integer,integer) to service_role;

-- Offentlige observationer må kun skrives gennem den validerende Edge Function.
drop policy if exists "anonymous observations can be inserted" on public.observations;
drop policy if exists "authenticated observations can be inserted" on public.observations;
revoke insert on public.observations from anon,authenticated;
grant insert,select on public.observations to service_role;

-- DEC-0109: trip-v2 quality lineage is an exact allowlist. Both an honestly
-- marked reconstructed RavScore and the public last-complete emergency view
-- remain useful observations, but neither may enter forecast calibration.
alter table public.observations
  drop constraint if exists ravradar_observations_trip_v2_check;

alter table public.observations
  add constraint ravradar_observations_trip_v2_check
  check (
    schema_version = 1 or (schema_version = 2 and
      trip_id is not null
      and trip_started_at is not null
      and trip_ended_at > trip_started_at
      and search_minutes between 1 and 1440
      and search_coverage in ('partial', 'normal', 'thorough')
      and actual_zone_id is not null
      and actual_coastal_part_id is not null
      and forecast_zone_id is not null
      and forecast_coastal_part_id is not null
      and coalesce(data_quality_flags, '[]'::jsonb) in (
        '[]'::jsonb,
        '["ravscore-reconstructed-derived-evidence"]'::jsonb,
        '["public-emergency-last-complete"]'::jsonb,
        '["public-emergency-last-complete","ravscore-reconstructed-derived-evidence"]'::jsonb,
        '["ravscore-evidence-trust-unattested"]'::jsonb
      )
      and calibration_eligible = (
        actual_zone_id = forecast_zone_id
        and actual_coastal_part_id = forecast_coastal_part_id
        and coalesce(data_quality_flags, '[]'::jsonb) = '[]'::jsonb
      )
      and found is not null
      and forecast_snapshot_id is not null
      and forecast_issued_at is not null
      and forecast_valid_at is not null
      and forecast_captured_at is not null
      and jsonb_typeof(calibration_features) = 'object'
      and jsonb_typeof(coalesce(calibration_features -> 'reasonCodes', '[]'::jsonb)) = 'array'
      and jsonb_path_query_array(
        coalesce(calibration_features -> 'reasonCodes', '[]'::jsonb),
        '$[*] ? (@ == "public-emergency-last-complete" || @ == "ravscore-reconstructed-derived-evidence" || @ == "ravscore-evidence-trust-unattested")'
      ) = coalesce(data_quality_flags, '[]'::jsonb)
      and ((coalesce(data_quality_flags, '[]'::jsonb) ? 'ravscore-reconstructed-derived-evidence')
        = (coalesce(calibration_features -> 'reasonCodes', '[]'::jsonb) ? 'ravscore-reconstructed-derived-evidence'))
      and ((coalesce(data_quality_flags, '[]'::jsonb) ? 'public-emergency-last-complete')
        = (coalesce(calibration_features -> 'reasonCodes', '[]'::jsonb) ? 'public-emergency-last-complete'))
      and ((coalesce(data_quality_flags, '[]'::jsonb) ? 'ravscore-evidence-trust-unattested')
        = (coalesce(calibration_features -> 'reasonCodes', '[]'::jsonb) ? 'ravscore-evidence-trust-unattested'))
      and jsonb_array_length(jsonb_path_query_array(
        coalesce(calibration_features -> 'reasonCodes', '[]'::jsonb),
        '$[*] ? (@ == "ravscore-reconstructed-derived-evidence")'
      )) <= 1
      and jsonb_array_length(jsonb_path_query_array(
        coalesce(calibration_features -> 'reasonCodes', '[]'::jsonb),
        '$[*] ? (@ == "public-emergency-last-complete")'
      )) <= 1
      and jsonb_array_length(jsonb_path_query_array(
        coalesce(calibration_features -> 'reasonCodes', '[]'::jsonb),
        '$[*] ? (@ == "ravscore-evidence-trust-unattested")'
      )) <= 1
      and forecast_issued_at <= forecast_captured_at
      and forecast_captured_at <= trip_started_at + interval '5 minutes'
    )
  ) not valid;

alter table public.observations
  validate constraint ravradar_observations_trip_v2_check;

comment on constraint ravradar_observations_trip_v2_check on public.observations is
  'Trip v2 DEC-0109-v2: exact quality allowlist and canonical quality-reason order; reconstructed, public-emergency and legacy-unattested snapshots are always excluded from calibration.';

-- Dataminimeret kontrolfunktion til ejerens produktionskontrol.
create or replace function public.ravradar_security_contract() returns jsonb
language plpgsql security definer set search_path=public,pg_catalog set row_security=off as $$
declare result jsonb;
begin
 if not (public.is_ravradar_owner() or public.has_ravradar_permission('full_admin')) then raise exception 'PERMISSION_DENIED' using errcode='42501'; end if;
 select jsonb_build_object(
  'observations_rls_enabled',coalesce((select relrowsecurity from pg_class where oid='public.observations'::regclass),false),
  'observations_anon_insert',has_table_privilege('anon','public.observations','INSERT'),
  'observations_authenticated_insert',has_table_privilege('authenticated','public.observations','INSERT'),
  'own_observation_read_policy',exists(select 1 from pg_policies where schemaname='public' and tablename='observations' and policyname='users can read own observations'),
  'rate_limit_table_rls_enabled',coalesce((select relrowsecurity from pg_class where oid='public.public_request_limits'::regclass),false),
  'rate_limit_rpc_present',to_regprocedure('public.consume_public_request_limit(text,text,integer,integer)') is not null,
  'permission_rpc_present',to_regprocedure('public.save_ravradar_permissions(uuid,jsonb)') is not null,
  'profiles_expert_scope_policy_present',exists(select 1 from pg_policies where schemaname='public' and tablename='profiles' and policyname='ravradar_profiles_read'),
  'permissions_expert_scope_policy_present',exists(select 1 from pg_policies where schemaname='public' and tablename='user_permissions' and policyname='ravradar_user_permissions_read'),
  'admin_documents_broad_policy_present',exists(select 1 from pg_policies where schemaname='public' and tablename='admin_documents' and policyname='authenticated admins manage documents'),
  'admin_document_versions_broad_policy_present',exists(select 1 from pg_policies where schemaname='public' and tablename='admin_document_versions' and policyname='authenticated admins read document versions'),
  'handbook_review_versions_broad_policy_present',exists(select 1 from pg_policies where schemaname='public' and tablename='handbook_review_versions' and policyname='authenticated admins read handbook review versions')
 ) into result;
 return result;
end $$;
